#!/usr/bin/env bash
# =========================================================================
# ServerTools v2.9.1 — single-file build
# Generated from src/ by build.sh — DO NOT EDIT THIS FILE DIRECTLY.
# https://github.com/Saj-1992/Xray-VPS-Optimizer
# =========================================================================

# ------------------------- src/00-header.sh -------------------------
# ============================================================================
# src/00-header.sh — strict mode, global constants, error trap.
# This file MUST be first in the build order (see build.sh SOURCES).
# ============================================================================

set -Eeuo pipefail
IFS=$'\n\t'

if ((BASH_VERSINFO[0] < 4 || (BASH_VERSINFO[0] == 4 && BASH_VERSINFO[1] < 4))); then
  printf 'ServerTools requires bash >= 4.4 (found %s)\n' "${BASH_VERSION}" >&2
  exit 1
fi

readonly ST_NAME="ServerTools"
readonly ST_VERSION="2.9.1"
readonly ST_REPO_URL="https://github.com/Saj-1992/Xray-VPS-Optimizer"

# Filesystem layout (FHS): config in /etc, state and backups in /var/lib,
# log in /var/log. Nothing is ever written to /tmp (predictable names in
# world-writable directories are a symlink-attack risk for a root tool).
readonly ST_ETC_DIR="/etc/server-tools"
readonly ST_CONFIG_FILE="${ST_ETC_DIR}/config"
readonly ST_LIB_DIR="/var/lib/server-tools"
readonly ST_BACKUP_DIR="${ST_LIB_DIR}/backups"
readonly ST_ORIGINAL_DIR="${ST_BACKUP_DIR}/original"
readonly ST_MANIFEST_FILE="${ST_LIB_DIR}/manifest.tsv"

ST_RUN_ID="$(date +%Y%m%d-%H%M%S)"
readonly ST_RUN_ID
readonly ST_RUN_BACKUP_DIR="${ST_BACKUP_DIR}/runs/${ST_RUN_ID}"

# Runtime flags — may be flipped by CLI arguments before initialisation.
ST_OPT_DEBUG=0
ST_OPT_NO_COLOR=0
ST_OPT_BATCH=0
ST_OPT_JSON=0
ST_DRY_RUN=0

# Exit-code contract (documented in --help and docs/ARCHITECTURE.md):
#   0  every step succeeded (or was legitimately skipped)
#   1  at least one step FAILED
#   2  usage error (bad CLI arguments)
#   3  everything applied but at least one step reported a WARNING
# ST_EXIT_CODE only ever escalates: warn (3) never overwrites fail (1).
ST_EXIT_CODE=0

st_escalate_exit() { # st_escalate_exit CODE
  case "$1" in
    1) ST_EXIT_CODE=1 ;;
    3) ((ST_EXIT_CODE == 1)) || ST_EXIT_CODE=3 ;;
  esac
}

on_unhandled_error() {
  local exit_code="$1" line="$2" command="$3"
  local msg="unhandled failure (exit=${exit_code}) at line ${line}: ${command}"
  if declare -F log_error >/dev/null 2>&1; then
    log_error "$msg"
  else
    printf '\n[%s] %s\n' "$ST_NAME" "$msg" >&2
  fi
}
trap 'on_unhandled_error "$?" "$LINENO" "$BASH_COMMAND"' ERR

# ------------------------- src/core/colors.sh -------------------------
# ============================================================================
# core/colors.sh — terminal capability detection and the UI palette.
#
# Rules:
#   - Color labels/titles only, never values (readable on light AND dark
#     terminals — no assumption about the user's background color).
#   - Honour NO_COLOR (https://no-color.org), non-tty output, and TERM=dumb.
#   - Unicode (box drawing) only when the locale advertises UTF-8.
# ============================================================================

ST_TTY=0
ST_UTF8=0

C_RESET='' C_BOLD='' C_DIM=''
C_TITLE='' C_KEY='' C_ACCENT='' C_LINE='' C_MUTED=''
C_OK='' C_WARN='' C_ERR=''

ui_detect_terminal() {
  [[ -t 1 ]] && ST_TTY=1

  case "${LC_ALL:-${LC_CTYPE:-${LANG:-}}}" in
    *[Uu][Tt][Ff]-8* | *[Uu][Tt][Ff]8*) ST_UTF8=1 ;;
  esac

  local want_color=$ST_TTY
  [[ -n ${NO_COLOR:-} ]] && want_color=0
  [[ ${TERM:-dumb} == dumb ]] && want_color=0
  ((ST_OPT_NO_COLOR)) && want_color=0
  ((want_color)) || return 0

  C_RESET=$'\033[0m'
  # C_BOLD/C_DIM: kept so the palette is complete for future modules.
  # shellcheck disable=SC2034
  C_BOLD=$'\033[1m'
  # shellcheck disable=SC2034
  C_DIM=$'\033[2m'

  # Classic (non-bright) ANSI colors — stable across terminal themes.
  C_TITLE=$'\033[1;36m'  # bold cyan   — screen titles, banner
  C_KEY=$'\033[1;34m'    # bold blue   — menu keys, kv labels
  C_ACCENT=$'\033[1;35m' # bold magenta — highlights
  C_LINE=$'\033[0;34m'   # blue        — separators
  C_MUTED=$'\033[2m'     # dim         — hints, secondary text
  C_OK=$'\033[1;32m'
  C_WARN=$'\033[1;33m'
  C_ERR=$'\033[1;31m'
  return 0
}

# ------------------------- src/core/log.sh -------------------------
# ============================================================================
# core/log.sh — leveled logging with size-based rotation.
# Primary target /var/log/server-tools.log, falling back to the state dir.
# ============================================================================

ST_LOG_FILE="/var/log/server-tools.log"
readonly ST_LOG_MAX_BYTES=$((2 * 1024 * 1024))

log_init() {
  if ! touch "$ST_LOG_FILE" 2>/dev/null; then
    mkdir -p "$ST_LIB_DIR"
    ST_LOG_FILE="${ST_LIB_DIR}/server-tools.log"
    touch "$ST_LOG_FILE"
  fi
}

_log_rotate_if_needed() {
  [[ -f $ST_LOG_FILE ]] || return 0
  local size
  size="$(wc -c <"$ST_LOG_FILE" 2>/dev/null)" || size=0
  if ((size > ST_LOG_MAX_BYTES)); then
    mv -f "$ST_LOG_FILE" "${ST_LOG_FILE}.1"
    : >"$ST_LOG_FILE"
  fi
}

# _log LEVEL MESSAGE... — appends to the log file when it is writable
# (before log_init, or as non-root, messages go to the console only).
_log() {
  local level="$1"
  shift
  [[ -w $ST_LOG_FILE ]] || return 0
  _log_rotate_if_needed
  printf '[%s] [%-5s] %s\n' "$(date '+%F %T')" "$level" "$*" >>"$ST_LOG_FILE"
}

log_debug() {
  ((ST_OPT_DEBUG)) || return 0
  _log DEBUG "$@"
  printf '%bDEBUG%b %s\n' "$C_MUTED" "$C_RESET" "$*" >&2
}

log_info() { _log INFO "$@"; }

# While a step is running its status line is still open ("... "), so console
# warnings are buffered and flushed by st_run_step right after the verdict.
# The log file always receives them immediately.
ST_LOG_BUFFERING=0
ST_LOG_BUFFER=()

log_warn() {
  _log WARN "$@"
  if ((ST_LOG_BUFFERING)); then
    ST_LOG_BUFFER+=("$*")
    return 0
  fi
  printf '%bWARN%b  %s\n' "$C_WARN" "$C_RESET" "$*" >&2
}

log_error() {
  _log ERROR "$@"
  printf '%bERROR%b %s\n' "$C_ERR" "$C_RESET" "$*" >&2
}

# log_note MESSAGE — an informational line for the user, buffered under the
# running step exactly like a warning but without the alarm styling. Always
# recorded in the log; used for "what was done and why" asides.
log_note() {
  _log INFO "$@"
  if ((ST_LOG_BUFFERING)); then
    ST_LOG_BUFFER+=("$*")
    return 0
  fi
  printf '  %s%s%s\n' "$C_MUTED" "$*" "$C_RESET"
}

# die MESSAGE — log the error and exit with failure.
die() {
  log_error "$@"
  exit 1
}

# ------------------------- src/core/ui.sh -------------------------
# ============================================================================
# core/ui.sh — reusable terminal UI kit: rules, titles, key/value rows,
# menu items, confirm/pause. Pure bash + printf, no external UI tools.
# ============================================================================

ui_width() {
  local cols
  cols="$(tput cols 2>/dev/null)" || cols=90
  [[ $cols =~ ^[0-9]+$ ]] || cols=90
  ((cols < 70)) && cols=70
  ((cols > 100)) && cols=100
  printf '%s' "$cols"
}

# ui_repeat CHAR COUNT — prints CHAR repeated COUNT times.
ui_repeat() {
  local pad
  printf -v pad '%*s' "$2" ''
  printf '%s' "${pad// /$1}"
}

# _ui_glyph UTF8 ASCII — the first form on UTF-8 terminals, the second (safe
# on any terminal, and under NO_COLOR/dumb) everywhere else.
_ui_glyph() {
  if ((ST_UTF8)); then printf '%s' "$1"; else printf '%s' "$2"; fi
}

ui_hr() {
  local ch='-'
  ((ST_UTF8)) && ch='─'
  printf '%s%s%s\n' "$C_LINE" "$(ui_repeat "$ch" "$(ui_width)")" "$C_RESET"
}

ui_hr_heavy() {
  local ch='='
  ((ST_UTF8)) && ch='═'
  printf '%s%s%s\n' "$C_LINE" "$(ui_repeat "$ch" "$(ui_width)")" "$C_RESET"
}

# ui_center TEXT [COLOR] — center TEXT within the terminal width.
ui_center() {
  local text="$1" color="${2:-}"
  local width pad
  width="$(ui_width)"
  pad=0
  ((${#text} < width)) && pad=$(((width - ${#text}) / 2))
  printf '%*s%s%s%s\n' "$pad" '' "$color" "$text" "${color:+$C_RESET}"
}

ui_title() {
  ui_center "$1" "$C_TITLE"
  ui_hr
}

# ui_section TITLE — a calm heading: an accent bar + label, with a blank line
# above for air. Deliberately NO full-width rule — sections are separated by
# whitespace, which keeps long screens uncluttered instead of "boxed in".
ui_section() {
  printf '\n  %s%s %s%s\n' "$C_TITLE" "$(_ui_glyph '▍' '|')" "$1" "$C_RESET"
}

# ui_menu_group TITLE — a lightweight category label above a set of menu items.
# Just a coloured word and a blank line; no separator bars (they read as noise).
ui_menu_group() {
  printf '\n  %s%s%s\n' "$C_ACCENT" "$1" "$C_RESET"
}

# _ui_prompt — the input caret shared by the menus (calm, unlabelled).
_ui_prompt() {
  printf '\n  %s%s%s ' "$C_ACCENT" "$(_ui_glyph '❯' '>')" "$C_RESET"
}

# ui_badge STATE — a colored status glyph. STATE: ok | warn | err | idle.
ui_badge() {
  case "$1" in
    ok) printf '%s%s%s' "$C_OK" "$(_ui_glyph '●' '[ok]')" "$C_RESET" ;;
    warn) printf '%s%s%s' "$C_WARN" "$(_ui_glyph '▲' '[!]')" "$C_RESET" ;;
    err) printf '%s%s%s' "$C_ERR" "$(_ui_glyph '✘' '[x]')" "$C_RESET" ;;
    *) printf '%s%s%s' "$C_MUTED" "$(_ui_glyph '○' '[-]')" "$C_RESET" ;;
  esac
}

# ui_hint TEXT — a dim, unobtrusive helper line for less-experienced users.
ui_hint() {
  printf ' %s%s %s%s\n' "$C_MUTED" "$(_ui_glyph 'ℹ' 'i')" "$1" "$C_RESET"
}

# ui_kv KEY VALUE — aligned row: coloured label, plain value, nested under a
# section (indent 4). No colon — the alignment already reads as a label.
ui_kv() {
  printf '    %s%-19s%s %s\n' "$C_KEY" "$1" "$C_RESET" "$2"
}

# ui_menu_item KEY LABEL [HINT] — one clean, aligned selectable row:
#     1  Quick Optimize        auto-tune everything · recommended
ui_menu_item() {
  local key="$1" label="$2" hint="${3:-}"
  if [[ -n $hint ]]; then
    printf '    %s%s%s  %-22s %s%s%s\n' \
      "$C_KEY" "$key" "$C_RESET" "$label" "$C_MUTED" "$hint" "$C_RESET"
  else
    printf '    %s%s%s  %s\n' "$C_KEY" "$key" "$C_RESET" "$label"
  fi
}

ui_logo() {
  # clear can fail on TERM=dumb / weird terminals — purely cosmetic.
  ((ST_OPT_BATCH)) || clear 2>/dev/null || true
  printf '%s' "$C_TITLE"
  cat <<'LOGO'
  ____                          _____           _
 / ___|  ___ _ ____   _____ _ _|_   _|__   ___ | |___
 \___ \ / _ \ '__\ \ / / _ \ '__|| |/ _ \ / _ \| / __|
  ___) |  __/ |   \ V /  __/ |   | | (_) | (_) | \__ \
 |____/ \___|_|    \_/ \___|_|   |_|\___/ \___/|_|___/
LOGO
  printf '%s' "$C_RESET"
  ui_center "Linux server optimization · zero runtime footprint · by Saj-1992" "$C_MUTED"
  ui_center "v${ST_VERSION}" "$C_ACCENT"
  ui_hr_heavy
}

# ui_confirm PROMPT — returns 0 only on an explicit yes.
ui_confirm() {
  local reply
  read -rp "$1 [y/N]: " reply || return 1
  [[ ${reply,,} == y || ${reply,,} == yes ]]
}

# ui_confirm_yes PROMPT — like ui_confirm but Enter means yes.
ui_confirm_yes() {
  local reply
  read -rp "$1 [Y/n]: " reply || return 1
  [[ -z $reply || ${reply,,} == y || ${reply,,} == yes ]]
}

ui_pause() {
  ((ST_OPT_BATCH)) && return 0
  [[ -t 0 ]] || return 0
  # EOF from a closed stdin is not an error here.
  read -rsn1 -p "Press any key to continue..." || true
  printf '\n'
}

# ui_todo FEATURE — honest placeholder for milestones not yet implemented.
ui_todo() {
  printf '%s[planned]%s %s is not implemented yet — it arrives in an upcoming v2 milestone.\n' \
    "$C_WARN" "$C_RESET" "$1"
  printf '%sRoadmap: %s#روادمپ / docs in the repository.%s\n' "$C_MUTED" "$ST_REPO_URL" "$C_RESET"
  ui_pause
}

# ------------------------- src/core/utils.sh -------------------------
# ============================================================================
# core/utils.sh — small dependency-free helpers: command/root checks,
# OS facts (from /proc and /etc/os-release), network facts, cached public IP.
# ============================================================================

has_cmd() { command -v "$1" >/dev/null 2>&1; }

require_root() {
  ((EUID == 0)) || die "This tool must be run as root (try: sudo -i)."
}

os_pretty_name() {
  local name=''
  if [[ -r /etc/os-release ]]; then
    name="$(. /etc/os-release 2>/dev/null && printf '%s' "${PRETTY_NAME:-}")" || name=''
  fi
  printf '%s' "${name:-unknown}"
}

kernel_release() { uname -r 2>/dev/null || printf 'unknown'; }

kernel_base() {
  local rel
  rel="$(kernel_release)"
  printf '%s' "${rel%%-*}"
}

detect_virt() {
  local virt=''
  if has_cmd systemd-detect-virt; then
    # Exit code 1 simply means "not virtualised"; the answer is on stdout.
    virt="$(systemd-detect-virt 2>/dev/null)" || true
  fi
  printf '%s' "${virt:-unknown}"
}

mem_total_mb() {
  awk '/^MemTotal:/ {print int($2 / 1024); exit}' /proc/meminfo 2>/dev/null || printf '0'
}

cpu_cores() {
  if has_cmd nproc; then
    nproc
  else
    grep -c '^processor' /proc/cpuinfo 2>/dev/null || printf '1'
  fi
}

cpu_model() {
  local model
  model="$(awk -F': *' '/^(model name|Model)/ {print $2; exit}' /proc/cpuinfo 2>/dev/null)" || model=''
  printf '%s' "${model:-unknown}"
}

uptime_pretty() {
  local secs
  secs="$(cut -d. -f1 /proc/uptime 2>/dev/null)" || secs=''
  [[ $secs =~ ^[0-9]+$ ]] || {
    printf 'unknown'
    return 0
  }
  printf '%dd %dh %dm' $((secs / 86400)) $((secs % 86400 / 3600)) $((secs % 3600 / 60))
}

load_avg() {
  cut -d' ' -f1-3 /proc/loadavg 2>/dev/null || printf 'unknown'
}

# ver_ge A B — true when dotted version A >= B.
ver_ge() {
  [[ "$(printf '%s\n' "$1" "$2" | sort -V | head -n1)" == "$2" ]]
}

is_valid_ipv4() {
  local ip="$1" octet
  [[ $ip =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] || return 1
  local IFS='.'
  for octet in $ip; do
    ((octet <= 255)) || return 1
  done
  return 0
}

# is_valid_ipv6 — hex groups separated by colons, at most one "::"
# compression, 2..8 groups. Rejects the "anything with a colon" trap.
is_valid_ipv6() {
  local ip="$1"
  [[ $ip == *:* && $ip != *:::* ]] || return 1
  # At most one "::" compression marker.
  local rest="${ip//::/}"
  ((${#ip} - ${#rest} <= 2)) || return 1
  [[ $ip =~ ^([0-9a-fA-F]{0,4}:){1,7}[0-9a-fA-F]{0,4}$ ]] || return 1
  # Without compression every one of the 8 groups must be present.
  if [[ $ip != *::* ]]; then
    local IFS=':' groups
    read -ra groups <<<"$ip"
    ((${#groups[@]} == 8)) || return 1
  fi
  return 0
}

# qdisc_supported NAME — real probe: attach the qdisc to loopback and remove
# it again (loopback traffic is unaffected, the default is restored at once).
# Dry-run must not touch anything, so it falls back to module inspection.
qdisc_supported() {
  local name="$1"
  has_cmd tc || return 1
  if ((ST_DRY_RUN)); then
    # fq/fq_codel are built into every supported kernel; others ship as
    # modules, which modinfo can check without loading them.
    case "$name" in
      fq | fq_codel) return 0 ;;
      *) has_cmd modinfo && modinfo -n "sch_${name}" >/dev/null 2>&1 ;;
    esac
    return
  fi
  tc qdisc add dev lo root "$name" 2>/dev/null || return 1
  tc qdisc del dev lo root 2>/dev/null ||
    log_warn "Could not detach the probe qdisc from loopback."
  return 0
}

# _ss_listen_ports SS_OUTPUT — ports of listeners reachable from OFF the box,
# one per line.
#
# Loopback-bound listeners are deliberately excluded, and that single rule is
# what separates a configured service port from a random internal one. Xray
# keeps internal plumbing on 127.0.0.1 with a port the kernel picks afresh on
# every start (127.0.0.1:39036 one run, 127.0.0.1:57035 after a restart), while
# every port that actually serves clients is bound to a wildcard or a real
# address and comes back unchanged. Reserving a random loopback port is
# meaningless — nothing outside can reach it and the app asked for "any free
# port" in the first place — and it made the generated value differ on every run.
_ss_listen_ports() {
  awk 'NR > 1 {
        addr = $4
        port = addr
        sub(/.*:/, "", port)
        sub(/:[^:]*$/, "", addr) # strip ":port", leaving the local address
        gsub(/[][]/, "", addr)   # drop IPv6 brackets
        if (addr ~ /^127\./ || addr == "::1" || addr ~ /^::ffff:127\./ || addr ~ /%lo$/) next
        if (port ~ /^[0-9]+$/) print port
      }' <<<"$1" | sort -un
}

# _ss_ports_in_range SS_OUTPUT — as above, restricted to the ephemeral range.
# The "+ 0" is not decoration: sub() turns the field into a string, and a
# string comparison would rank "22" above "10240" and let it through.
_ss_ports_in_range() {
  _ss_listen_ports "$1" | awk '$1 + 0 >= 10240 && $1 + 0 <= 65535'
}

# The tool runs with a hardened global IFS ($'\n\t' — deliberately no space).
# That makes two everyday bash idioms silently WRONG on space-separated data:
#   for x in ${list//,/ }  -> no split at all; the whole list arrives as one word
#   "${array[*]}"          -> joined with a NEWLINE instead of a space
# Both failed silently in real features (a port list became one bogus "port";
# a generated systemd ExecStart line was split across nine lines). These two
# helpers are the supported way to do each, and must be used instead.

# ports_split LIST — one token per line from a "80,443 1000-1002" list.
ports_split() {
  local -a items=()
  [[ -n ${1:-} ]] || return 0
  IFS=$', \t' read -ra items <<<"$1"
  ((${#items[@]} > 0)) && printf '%s\n' "${items[@]}"
  return 0
}

# join_sp WORD... — the words joined by single spaces (for argv-shaped strings).
join_sp() {
  local IFS=' '
  printf '%s' "$*"
}

# _ports_subtract SET — read candidate ports (one per line) from stdin and
# print those NOT in SET (a newline-separated list passed as the argument).
# This replaces `comm`, which needs its input in *byte* order while our ports
# are in *numeric* order ("8443" sorts before "51820" numerically but after it
# bytewise), so comm silently returned wrong results. An empty SET is handled
# correctly (everything passes through).
_ports_subtract() {
  awk -v set="$1" '
    BEGIN { n = split(set, a, "\n"); for (i = 1; i <= n; i++) if (a[i] != "") m[a[i]] = 1 }
    !($1 in m)'
}

# wg_listen_ports — the ports WireGuard is configured to listen on, asked of
# wg itself (one per line). Authoritative, unlike inspecting sockets.
wg_listen_ports() {
  has_cmd wg || return 0
  local out
  out="$(wg show all listen-port 2>/dev/null)" || return 0
  awk 'NF {print $NF}' <<<"$out" | grep -E '^[0-9]+$' | sort -un
}

# listening_service_ports — ports of REAL services inside the ephemeral range
# (10240-65535), one per line. Only unambiguous evidence counts:
#
#   - TCP sockets in LISTEN state — a listener IS a service, by definition;
#   - WireGuard's configured listen port, read from `wg` itself.
#
# Generic UDP listeners are deliberately NOT auto-detected. A userspace proxy
# (Xray/sing-box) opens one UNCONN socket per UDP session, and a QUIC/Hysteria
# session outlives any sampling window we could afford — so by socket inspection
# alone those ephemeral ports are indistinguishable from a service. Reserving
# them spent the list on ports that belong to nothing AND, because the set is
# rebuilt from the live system on every render, made the rendered value differ
# on every single run. Sampling twice and capping the count only reduced how
# often that happened; it could not fix it, because the input is genuinely
# ambiguous. A UDP-only service on a fixed port is pinned explicitly with the
# `reserved_ports` config key instead — deterministic by construction.
listening_service_ports() {
  local tcp wg_ports
  {
    if has_cmd ss; then
      tcp="$(ss -tln 2>/dev/null)" || tcp=''
      _ss_ports_in_range "$tcp"
    fi
    wg_ports="$(wg_listen_ports)" || wg_ports=''
    # Only ports inside the ephemeral range can ever be stolen by an outgoing
    # connection; reserving anything outside it would be noise.
    if [[ -n $wg_ports ]]; then
      awk '$1 + 0 >= 10240 && $1 + 0 <= 65535' <<<"$wg_ports"
    fi
  } | sort -un
}

# net_dns_capable_links — links worth carrying a DNS override: everything
# that is up, minus loopback and container/virtual bridges.
net_dns_capable_links() {
  has_cmd ip || return 0
  ip -o link show up 2>/dev/null |
    awk -F': ' '{print $2}' |
    sed 's/@.*//' |
    grep -vE '^(lo|docker[0-9]*|br-|veth|cni|virbr|kube)' || true
}

# net_default_iface / net_default_gw — read from the default route.
# The route is captured first, then parsed from a here-string: piping into an
# awk that exits on the first match would SIGPIPE `ip`, and under pipefail the
# function would return 141 even on success — which the callers' `|| x=''`
# guards would then mistake for failure and blank a perfectly good value.
net_default_iface() {
  has_cmd ip || return 0
  local route
  route="$(ip route show default 2>/dev/null)" || return 0
  awk '{for (i = 1; i < NF; i++) if ($i == "dev") {print $(i + 1); exit}}' <<<"$route"
}

net_default_gw() {
  has_cmd ip || return 0
  local route
  route="$(ip route show default 2>/dev/null)" || return 0
  awk '{for (i = 1; i < NF; i++) if ($i == "via") {print $(i + 1); exit}}' <<<"$route"
}

# pkg_install PACKAGE — caller must already have the user's consent
# (CLAUDE.md rule 1: nothing is installed silently). Output goes to the log.
ST_PKG_INDEX_UPDATED=0

pkg_install() {
  local pkg="$1"
  if has_cmd apt-get; then
    export DEBIAN_FRONTEND=noninteractive
    if ((ST_PKG_INDEX_UPDATED == 0)); then
      apt-get update -qq >>"$ST_LOG_FILE" 2>&1 ||
        log_warn "apt index update failed — trying the install anyway."
      ST_PKG_INDEX_UPDATED=1
    fi
    apt-get install -y -qq "$pkg" >>"$ST_LOG_FILE" 2>&1
  elif has_cmd dnf; then
    dnf install -y "$pkg" >>"$ST_LOG_FILE" 2>&1
  elif has_cmd yum; then
    yum install -y "$pkg" >>"$ST_LOG_FILE" 2>&1
  elif has_cmd pacman; then
    pacman -Sy --noconfirm "$pkg" >>"$ST_LOG_FILE" 2>&1
  else
    log_error "No supported package manager found to install ${pkg}."
    return 1
  fi
}

# sysctl_get KEY — current value or "?" when unavailable.
sysctl_get() {
  local value
  if has_cmd sysctl; then
    value="$(sysctl -n "$1" 2>/dev/null)" || value=''
  fi
  printf '%s' "${value:-?}"
}

# --- Public IP (fetched once per process, then cached — the menu redraws
# --- must never block on network calls).
ST_CACHE_IP4=''
ST_CACHE_IP6=''

_net_fetch() { # _net_fetch 4|6 URL
  has_cmd curl || return 1
  # Short timeout: this runs during the first dashboard render and must
  # never make the menu feel stuck on servers with broken connectivity.
  curl "-$1" -fsS --max-time 2 "$2" 2>/dev/null | tr -d '[:space:]'
}

net_public_ip4() {
  if [[ -z $ST_CACHE_IP4 ]]; then
    local ip='' url
    for url in 'https://api.ipify.org' 'https://ifconfig.me/ip'; do
      ip="$(_net_fetch 4 "$url")" || ip=''
      is_valid_ipv4 "$ip" && break
      ip=''
    done
    if [[ -z $ip ]] && has_cmd ip; then
      ip="$(ip -4 addr show scope global 2>/dev/null |
        awk '/inet / {sub(/\/.*/, "", $2); print $2; exit}')" || ip=''
    fi
    ST_CACHE_IP4="${ip:-N/A}"
  fi
  printf '%s' "$ST_CACHE_IP4"
}

net_public_ip6() {
  if [[ -z $ST_CACHE_IP6 ]]; then
    local ip='' url
    for url in 'https://api64.ipify.org' 'https://ifconfig.me/ip'; do
      ip="$(_net_fetch 6 "$url")" || ip=''
      [[ $ip == *:* ]] && break
      ip=''
    done
    if [[ -z $ip ]] && has_cmd ip; then
      ip="$(ip -6 addr show scope global 2>/dev/null |
        awk '/inet6 / {sub(/\/.*/, "", $2); print $2; exit}')" || ip=''
    fi
    ST_CACHE_IP6="${ip:-N/A}"
  fi
  printf '%s' "$ST_CACHE_IP6"
}

# ------------------------- src/core/state.sh -------------------------
# ============================================================================
# core/state.sh — persistent user config (key=value) and the change manifest.
#
# The manifest is the source of truth for rollback: every file the tool
# creates or modifies gets one TSV row (see docs/ROLLBACK.md).
# ============================================================================

declare -A ST_CONFIG=()

state_init() {
  mkdir -p "$ST_ETC_DIR" "$ST_LIB_DIR" "$ST_BACKUP_DIR"
  if [[ ! -f $ST_MANIFEST_FILE ]]; then
    printf '# timestamp\trun_id\taction\ttarget\n' >"$ST_MANIFEST_FILE"
  fi
}

config_load() {
  ST_CONFIG=()
  [[ -f $ST_CONFIG_FILE ]] || return 0
  local key value
  while IFS='=' read -r key value; do
    [[ -z $key || $key == \#* ]] && continue
    ST_CONFIG[$key]="$value"
  done <"$ST_CONFIG_FILE"
}

config_get() { # config_get KEY [DEFAULT]
  printf '%s' "${ST_CONFIG[$1]:-${2:-}}"
}

config_set() { # config_set KEY VALUE — updates memory and persists.
  ST_CONFIG[$1]="$2"
  config_save
}

config_save() {
  mkdir -p "$ST_ETC_DIR"
  local tmp="${ST_CONFIG_FILE}.tmp" key
  {
    printf '# %s configuration — generated; editing by hand is fine.\n' "$ST_NAME"
    for key in "${!ST_CONFIG[@]}"; do
      printf '%s=%s\n' "$key" "${ST_CONFIG[$key]}"
    done | sort
  } >"$tmp"
  mv -f "$tmp" "$ST_CONFIG_FILE"
}

# manifest_add ACTION TARGET — ACTION is "created" or "modified".
manifest_add() {
  printf '%s\t%s\t%s\t%s\n' "$(date '+%F %T')" "$ST_RUN_ID" "$1" "$2" >>"$ST_MANIFEST_FILE"
}

manifest_entry_count() {
  [[ -f $ST_MANIFEST_FILE ]] || {
    printf '0'
    return 0
  }
  awk 'NR > 1' "$ST_MANIFEST_FILE" | wc -l | tr -d '[:space:]'
}

# manifest_latest_run — most recent run id that recorded changes (empty if none).
manifest_latest_run() {
  [[ -f $ST_MANIFEST_FILE ]] || return 0
  awk -F'\t' 'NR > 1 {print $2}' "$ST_MANIFEST_FILE" | sort -u | tail -n1
}

# ------------------------- src/core/backup.sh -------------------------
# ============================================================================
# core/backup.sh — track-before-touch backups and manifest-driven rollback.
#
# Contract (see CLAUDE.md rule 3): call `st_track_file PATH` BEFORE creating
# or modifying PATH. This yields:
#   - a pristine copy under original/ the first time the tool ever touches
#     the file (never overwritten afterwards),
#   - a per-run copy under runs/<run-id>/ (mirror of the absolute path),
#   - a manifest row ("modified" or "created") for rollback.
# ============================================================================

# Paths already captured in this run. Tracking the same file twice would
# overwrite its run backup with our own edit and silently break rollback.
declare -A ST_TRACKED=()

st_track_file() {
  local path="$1"
  [[ -n ${ST_TRACKED[$path]:-} ]] && return 0
  ST_TRACKED[$path]=1

  mkdir -p "$ST_RUN_BACKUP_DIR"
  if [[ -e $path || -L $path ]]; then
    if [[ ! -e ${ST_ORIGINAL_DIR}${path} && ! -L ${ST_ORIGINAL_DIR}${path} ]]; then
      mkdir -p "${ST_ORIGINAL_DIR}$(dirname "$path")"
      cp -a "$path" "${ST_ORIGINAL_DIR}${path}"
    fi
    mkdir -p "${ST_RUN_BACKUP_DIR}$(dirname "$path")"
    cp -a "$path" "${ST_RUN_BACKUP_DIR}${path}"
    manifest_add modified "$path"
    log_debug "tracked (modified): $path"
  else
    manifest_add created "$path"
    log_debug "tracked (created): $path"
  fi
}

# backup_prune [KEEP] — keep the newest KEEP run directories (default 10).
# The pristine original/ tree is never touched: it is the only way back to
# the state the server was in before ServerTools ever ran.
backup_prune() {
  local keep="${1:-10}" runs="${ST_BACKUP_DIR}/runs" dir
  [[ -d $runs ]] || return 0
  while IFS= read -r dir; do
    [[ -n $dir ]] || continue
    rm -rf "${runs:?}/${dir}" ||
      log_warn "Could not prune the old backup ${dir}."
    log_debug "pruned old run backup: ${dir}"
  done < <(find "$runs" -mindepth 1 -maxdepth 1 -type d -printf '%f\n' 2>/dev/null |
    sort -r | awk -v k="$keep" 'NR > k')
}

# rollback_original — restore every file to the state it had the first time
# ServerTools touched it, across all runs, and remove everything it created.
rollback_original() {
  if [[ ! -d $ST_ORIGINAL_DIR ]]; then
    log_warn "No pristine backups recorded — nothing to restore."
    return 0
  fi

  local file target restored=0 removed=0
  # Restore first, then remove created files: a file can appear as created in
  # one run and modified in a later one, and the original must win.
  while IFS= read -r file; do
    target="${file#"$ST_ORIGINAL_DIR"}"
    [[ -n $target ]] || continue
    mkdir -p "$(dirname "$target")"
    cp -a "$file" "$target" && restored=$((restored + 1))
  done < <(find "$ST_ORIGINAL_DIR" -type f -o -type l 2>/dev/null)

  while IFS= read -r target; do
    [[ -n $target ]] || continue
    # Only remove what was created and never existed before this tool ran.
    [[ -e ${ST_ORIGINAL_DIR}${target} ]] && continue
    if [[ -r /proc/swaps ]] && grep -q "^${target}[[:space:]]" /proc/swaps 2>/dev/null; then
      swapoff "$target" 2>>"$ST_LOG_FILE" || {
        log_warn "Cannot swapoff ${target} — left in place."
        continue
      }
    fi
    rm -f "$target" && removed=$((removed + 1))
  done < <(awk -F'\t' 'NR > 1 && $3 == "created" {print $4}' "$ST_MANIFEST_FILE" 2>/dev/null | sort -u)

  local unit
  while IFS= read -r unit; do
    [[ -n $unit ]] || continue
    has_cmd systemctl || break
    systemctl disable --now "$unit" >/dev/null 2>>"$ST_LOG_FILE" ||
      log_warn "Could not disable unit ${unit}."
  done < <(awk -F'\t' 'NR > 1 && $3 == "unit" {print $4}' "$ST_MANIFEST_FILE" 2>/dev/null | sort -u)

  has_cmd systemctl && { systemctl daemon-reload 2>>"$ST_LOG_FILE" || log_warn "daemon-reload failed."; }
  has_cmd sysctl && { sysctl --system >/dev/null 2>>"$ST_LOG_FILE" || log_warn "sysctl reload reported errors."; }

  log_info "Factory restore: ${restored} restored, ${removed} removed."
  printf '%sRestored to the state before ServerTools ever ran:%s %d file(s) restored, %d removed.\n' \
    "$C_OK" "$C_RESET" "$restored" "$removed"
  printf '%sA reboot guarantees every runtime setting is back as well.%s\n' "$C_MUTED" "$C_RESET"
  return 0
}

# rollback_latest — revert everything recorded by the most recent run,
# newest change first. Files "created" by that run are removed; "modified"
# files are restored from the run backup.
rollback_latest() {
  local run
  run="$(manifest_latest_run)"
  if [[ -z $run ]]; then
    log_warn "No recorded changes — nothing to roll back."
    return 0
  fi

  local src="${ST_BACKUP_DIR}/runs/${run}"
  local action target restored=0 removed=0 missing=0 sysctl_touched=0 units_touched=0
  while IFS=$'\t' read -r action target; do
    case "$action" in
      unit)
        # A systemd unit this run enabled: disable it (stop included) so no
        # dangling .wants symlink survives after its file is removed below.
        if has_cmd systemctl; then
          systemctl disable --now "$target" >/dev/null 2>>"$ST_LOG_FILE" ||
            log_warn "Could not disable unit ${target}."
          units_touched=1
        fi
        ;;
      modified)
        if [[ -e ${src}${target} || -L ${src}${target} ]]; then
          cp -a "${src}${target}" "$target"
          restored=$((restored + 1))
          [[ $target == /etc/sysctl.d/* || $target == /etc/sysctl.conf ]] && sysctl_touched=1
        else
          log_warn "Backup missing for ${target} — skipped."
          missing=$((missing + 1))
        fi
        ;;
      created)
        # Never delete an active swap file out from under the kernel.
        if [[ -r /proc/swaps ]] && grep -q "^${target}[[:space:]]" /proc/swaps 2>/dev/null; then
          if ! swapoff "$target" 2>>"$ST_LOG_FILE"; then
            log_warn "Cannot swapoff ${target} — left in place."
            missing=$((missing + 1))
            continue
          fi
        fi
        rm -f "$target"
        removed=$((removed + 1))
        [[ $target == /etc/sysctl.d/* ]] && sysctl_touched=1
        ;;
    esac
  done < <(awk -F'\t' -v run="$run" 'NR > 1 && $2 == run {print $3 "\t" $4}' "$ST_MANIFEST_FILE" | tac)

  if ((units_touched)) && has_cmd systemctl; then
    systemctl daemon-reload 2>>"$ST_LOG_FILE" ||
      log_warn "daemon-reload after rollback failed."
  fi
  if ((sysctl_touched)) && has_cmd sysctl; then
    sysctl --system >/dev/null 2>>"$ST_LOG_FILE" ||
      log_warn "sysctl reload after rollback reported errors (see log)."
  fi

  log_info "Rollback of run ${run}: ${restored} restored, ${removed} removed, ${missing} missing."
  printf '%sRollback of run %s:%s %d file(s) restored, %d removed' \
    "$C_OK" "$run" "$C_RESET" "$restored" "$removed"
  ((missing > 0)) && printf ', %s%d backup(s) missing%s' "$C_WARN" "$missing" "$C_RESET"
  printf '\n'
  printf '%sNote:%s runtime state (loaded sysctl values, running services) is not\n' "$C_MUTED" "$C_RESET"
  printf '%sreverted automatically — a reboot guarantees a clean slate.%s\n' "$C_MUTED" "$C_RESET"
  return 0
}

# ------------------------- src/modules/detect.sh -------------------------
# ============================================================================
# modules/detect.sh — detect which VPN workload runs on this server.
#
# A server is usually EITHER a panel (Marzban/Pasarguard dashboard, no VPN
# traffic) OR a node (marzban-node / pg-node — the Xray core carrying user
# traffic) OR a WireGuard host. Detection picks the workload layer that the
# optimizer will suggest; the base layer always covers the whole server.
# ============================================================================

ST_DETECTED=()

_detect_add() { # _detect_add TAG — append once.
  local tag="$1" existing
  for existing in "${ST_DETECTED[@]-}"; do
    [[ $existing == "$tag" ]] && return 0
  done
  ST_DETECTED+=("$tag")
}

_detect_match() { # _detect_match HAYSTACK REGEX
  [[ -n $1 ]] && grep -qiE "$2" <<<"$1"
}

detect_stack() {
  ST_DETECTED=()

  # Containers from docker AND podman — some hosts run nodes under podman.
  local containers=''
  if has_cmd docker; then
    containers="$(docker ps --format '{{.Names}} {{.Image}}' 2>/dev/null)" || containers=''
  fi
  if has_cmd podman; then
    local podman_ps
    podman_ps="$(podman ps --format '{{.Names}} {{.Image}}' 2>/dev/null)" || podman_ps=''
    containers="${containers}${containers:+$'\n'}${podman_ps}"
  fi

  # Nodes first — "marzban" alone must not swallow the node. Gozargah's node
  # ships both as "marzban-node" and, since the rename, plain "marznode".
  _detect_match "$containers" 'marzban[-_]node|marznode' && _detect_add 'marzban-node'
  _detect_match "$containers" 'pg[-_]node|pasarguard' && _detect_add 'pg-node'
  if _detect_match "$containers" 'marzban|marzneshin' &&
    ! _detect_match "$containers" 'marzban[-_]node|marznode'; then
    _detect_add 'marzban-panel'
  fi
  _detect_match "$containers" 'hiddify' && _detect_add 'hiddify'
  _detect_match "$containers" '3x-ui|x-ui' && _detect_add 'x-ui'
  _detect_match "$containers" 'sing-?box' && _detect_add 'sing-box'
  _detect_match "$containers" 'hysteria' && _detect_add 'hysteria'
  _detect_match "$containers" 'openvpn' && _detect_add 'openvpn'
  _detect_match "$containers" 'wgdashboard|wg-easy' && _detect_add 'wg-dashboard'

  if has_cmd systemctl; then
    systemctl is-active --quiet x-ui 2>/dev/null && _detect_add 'x-ui'
    systemctl is-active --quiet xray 2>/dev/null && _detect_add 'xray'
    systemctl is-active --quiet sing-box 2>/dev/null && _detect_add 'sing-box'
    systemctl is-active --quiet hysteria-server 2>/dev/null && _detect_add 'hysteria'
    systemctl is-active --quiet openvpn 2>/dev/null && _detect_add 'openvpn'
  fi

  if has_cmd wg && [[ -n "$(wg show interfaces 2>/dev/null)" ]]; then
    _detect_add 'wireguard'
  fi

  log_debug "detected workloads: ${ST_DETECTED[*]-none}"
  return 0
}

detect_summary() {
  if ((${#ST_DETECTED[@]} == 0)); then
    printf 'none (general server)'
  else
    local IFS=', '
    printf '%s' "${ST_DETECTED[*]}"
  fi
}

# ------------------------- src/modules/sysinfo.sh -------------------------
# ============================================================================
# modules/sysinfo.sh — the System Status report (menu option and --status).
#
# Everything is read live from /proc, /sys and the tools that are present;
# nothing is cached from a previous run, so the report always reflects the
# machine as it is right now. Missing tools degrade to "n/a", never an error.
# ============================================================================

_meminfo_kb() { # _meminfo_kb FIELD — e.g. MemTotal
  awk -v field="$1:" '$1 == field {print $2; exit}' /proc/meminfo 2>/dev/null || printf '0'
}

# _hr_mb MB — human readable size, one decimal from a gigabyte upwards.
_hr_mb() {
  local mb="${1:-0}"
  if ((mb >= 1024)); then
    awk -v m="$mb" 'BEGIN {printf "%.1f GB", m / 1024}'
  else
    printf '%s MB' "$mb"
  fi
}

# _pct USED TOTAL — integer percentage, "0" when total is zero.
_pct() {
  if (($2 > 0)); then
    printf '%d' $(($1 * 100 / $2))
  else
    printf '0'
  fi
}

_status_system() {
  ui_section "System"
  ui_kv "Hostname" "$(hostname 2>/dev/null || cat /proc/sys/kernel/hostname 2>/dev/null || printf 'unknown')"
  ui_kv "OS" "$(os_pretty_name)"
  ui_kv "Kernel" "$(kernel_release) ($(uname -m 2>/dev/null || printf 'unknown'))"
  ui_kv "Virtualization" "$(detect_virt)"
  ui_kv "Uptime" "$(uptime_pretty)"

  local tz='n/a' ntp=''
  if has_cmd timedatectl; then
    tz="$(timedatectl show -p Timezone --value 2>/dev/null)" || tz='n/a'
    ntp="$(timedatectl show -p NTPSynchronized --value 2>/dev/null)" || ntp=''
  fi
  case "$ntp" in
    yes) ui_kv "Time" "${tz} (NTP synchronized)" ;;
    no) ui_kv "Time" "${tz} (NTP NOT synchronized)" ;;
    *) ui_kv "Time" "$tz" ;;
  esac
}

_status_cpu() {
  ui_section "CPU"
  ui_kv "Model" "$(cpu_model)"
  ui_kv "Cores" "$(cpu_cores)"
  ui_kv "Load (1/5/15m)" "$(load_avg)"
}

# _swap_backend — how swap is provided: zram, file, partition, or none.
_swap_backend() {
  [[ -r /proc/swaps ]] || {
    printf 'unknown'
    return 0
  }
  awk 'NR > 1 {
    if ($1 ~ /zram/) kind = "zram (compressed RAM)"
    else if ($2 == "file") kind = "file " $1
    else kind = $2 " " $1
    print kind
    exit
  }' /proc/swaps
}

_status_memory() {
  ui_section "Memory & Storage"
  local total_kb avail_kb swap_total_kb swap_free_kb used_mb
  total_kb="$(_meminfo_kb MemTotal)"
  avail_kb="$(_meminfo_kb MemAvailable)"
  swap_total_kb="$(_meminfo_kb SwapTotal)"
  swap_free_kb="$(_meminfo_kb SwapFree)"
  used_mb=$(((total_kb - avail_kb) / 1024))

  ui_kv "RAM" "$(_hr_mb $((total_kb / 1024))) total · $(_hr_mb "$used_mb") used · $(_hr_mb $((avail_kb / 1024))) available"
  if ((swap_total_kb > 0)); then
    ui_kv "Swap" "$(_hr_mb $(((swap_total_kb - swap_free_kb) / 1024))) used / $(_hr_mb $((swap_total_kb / 1024))) · $(_swap_backend)"
  else
    ui_kv "Swap" "disabled"
  fi
  if has_cmd df; then
    ui_kv "Disk (/)" "$(df -h / 2>/dev/null | awk 'NR == 2 {printf "%s used / %s (%s full)", $3, $2, $5}')"
  fi
}

_status_network() {
  ui_section "Network"
  local iface mtu qdisc tc_out
  iface="$(net_default_iface)" || iface=''
  ui_kv "Default IF" "${iface:-unknown}"
  if [[ -n $iface ]]; then
    mtu="$(cat "/sys/class/net/${iface}/mtu" 2>/dev/null)" || mtu='?'
    tc_out="$(tc qdisc show dev "$iface" 2>/dev/null)" || tc_out=''
    qdisc="$(awk 'NR == 1 {print $2}' <<<"$tc_out")"
    ui_kv "MTU / qdisc" "${mtu} / ${qdisc:-unknown}"
  fi
  ui_kv "Gateway" "$(net_default_gw || printf 'unknown')"
  ui_kv "Public IPv4" "$(net_public_ip4)"
  ui_kv "Public IPv6" "$(net_public_ip6)"

  # Socket counts come from /proc — far cheaper than parsing `ss` output.
  if [[ -r /proc/net/sockstat ]]; then
    ui_kv "TCP sockets" "$(awk '/^TCP:/ {printf "%s in use · %s time-wait · %s orphan", $3, $7, $5}' /proc/net/sockstat)"
  fi
}

_status_dns() {
  ui_section "DNS"
  local stack
  stack="$(dns_stack)"
  case "$stack" in
    resolved) ui_kv "Resolver" "systemd-resolved" ;;
    resolvconf) ui_kv "Resolver" "resolvconf" ;;
    *) ui_kv "Resolver" "plain /etc/resolv.conf" ;;
  esac
  ui_kv "Servers in effect" "$(dns_effective_servers)"
  [[ $stack == resolved ]] && ui_kv "DNS over TLS" "$(dns_over_tls_state)"
  if [[ -L /etc/resolv.conf ]]; then
    ui_kv "resolv.conf" "symlink -> $(readlink /etc/resolv.conf 2>/dev/null)"
  else
    ui_kv "resolv.conf" "regular file"
  fi
}

_status_tuning() {
  ui_section "Kernel tuning"
  local cc
  cc="$(sysctl_get net.ipv4.tcp_congestion_control)"
  if [[ $cc == bbr* ]]; then
    ui_kv "Congestion" "${cc} (BBR active)"
  else
    ui_kv "Congestion" "${cc}"
  fi
  ui_kv "Default qdisc" "$(sysctl_get net.core.default_qdisc)"
  ui_kv "MTU probing" "$(sysctl_get net.ipv4.tcp_mtu_probing)"
  ui_kv "Forwarding" "IPv4=$(sysctl_get net.ipv4.ip_forward) · IPv6=$(sysctl_get net.ipv6.conf.all.forwarding)"
  ui_kv "Accept queues" "somaxconn=$(sysctl_get net.core.somaxconn) · backlog=$(sysctl_get net.core.netdev_max_backlog)"
  ui_kv "Socket buffers" "rmem_max=$(sysctl_get net.core.rmem_max) · wmem_max=$(sysctl_get net.core.wmem_max)"

  local ct_count ct_max
  ct_count="$(sysctl_get net.netfilter.nf_conntrack_count)"
  ct_max="$(sysctl_get net.netfilter.nf_conntrack_max)"
  if [[ $ct_count =~ ^[0-9]+$ && $ct_max =~ ^[0-9]+$ ]]; then
    ui_kv "Conntrack" "${ct_count} / ${ct_max} ($(_pct "$ct_count" "$ct_max")% used)"
  else
    ui_kv "Conntrack" "module not loaded"
  fi
}

_status_limits() {
  ui_section "Limits"
  ui_kv "nofile (this shell)" "soft=$(ulimit -Sn 2>/dev/null || printf '?') · hard=$(ulimit -Hn 2>/dev/null || printf '?')"
  if has_cmd systemctl; then
    ui_kv "systemd default" "$(systemctl show -p DefaultLimitNOFILE --value 2>/dev/null || printf 'n/a')"
  fi
  ui_kv "fs.file-max" "$(sysctl_get fs.file-max)"
  [[ -r /proc/sys/fs/file-nr ]] &&
    ui_kv "Open files" "$(awk '{print $1}' /proc/sys/fs/file-nr)"
  if has_cmd docker; then
    if grep -q 'default-ulimits' /etc/docker/daemon.json 2>/dev/null; then
      ui_kv "Docker ulimits" "configured in daemon.json"
    else
      ui_kv "Docker ulimits" "engine default (containers ignore limits.d)"
    fi
  fi
}

_status_security() {
  ui_section "Security"
  if has_cmd ufw; then
    local ufw_out=''
    ufw_out="$(ufw status 2>/dev/null)" || ufw_out=''
    ui_kv "Firewall (UFW)" "$(awk 'NR == 1 {print $2; exit}' <<<"$ufw_out" || printf 'unknown')"
  else
    ui_kv "Firewall (UFW)" "not installed"
  fi
  if has_cmd systemctl; then
    if systemctl is-active --quiet fail2ban 2>/dev/null; then
      ui_kv "fail2ban" "active"
    else
      ui_kv "fail2ban" "inactive"
    fi
    if systemctl is-enabled --quiet server-tools-mss.service 2>/dev/null; then
      ui_kv "MSS clamping" "enabled at boot"
    fi
  fi
  if has_cmd sshd; then
    local sshd_cfg port pw
    sshd_cfg="$(sshd -T 2>/dev/null)" || sshd_cfg=''
    if [[ -n $sshd_cfg ]]; then
      port="$(awk '/^port / {print $2; exit}' <<<"$sshd_cfg")"
      pw="$(awk '/^passwordauthentication / {print $2; exit}' <<<"$sshd_cfg")"
      ui_kv "SSH" "port ${port:-?} · password auth ${pw:-?}"
    fi
  fi
}

_status_servertools() {
  ui_section "Workload & ServerTools"
  ui_kv "Detected" "$(detect_summary)"
  ui_kv "Version" "$ST_VERSION"
  local users
  users="$(config_get expected_users 0)"
  if [[ $users =~ ^[1-9][0-9]*$ ]]; then
    ui_kv "Applied profile" "$(config_get last_profile 'not applied yet') · tier $(config_get last_tier '-') · ${users} users"
  else
    ui_kv "Applied profile" "$(config_get last_profile 'not applied yet') · tier $(config_get last_tier '-')"
  fi
  ui_kv "Recorded changes" "$(manifest_entry_count) (last run: $(manifest_latest_run || printf 'none'))"
  ui_kv "Log file" "$ST_LOG_FILE"
  ui_kv "Backups" "$ST_BACKUP_DIR"
}

show_status() {
  ui_logo
  ui_title "System Status"

  _status_system
  _status_cpu
  _status_memory
  _status_network
  _status_dns
  _status_tuning
  _status_limits
  _status_security
  _status_servertools

  printf '\n'
  ui_hint "\"st --dry-run\" shows which kernel keys still differ · \"st --report\" saves this to a file."
  ui_pause
}

# ------------------------- src/modules/profile.sh -------------------------
# ============================================================================
# modules/profile.sh — layered profile resolution and capacity tiers.
# Implements docs/PROFILES.md: the base layer ALWAYS covers the whole server;
# the workload profile only decides the specialised extras on top.
# ============================================================================

ST_PROFILE='general'
ST_PROFILE_SOURCE='default'

ST_TIER=''
ST_TIER_USERS=''
ST_SOMAXCONN=0
ST_NETDEV_BACKLOG=0
ST_BUF_MB=0
ST_CONNTRACK=0

profile_resolve_auto() {
  local detected=" ${ST_DETECTED[*]-} "
  ST_PROFILE_SOURCE='auto-detected'
  if [[ $detected == *'marzban-node'* || $detected == *'pg-node'* ||
    $detected == *'xray'* || $detected == *'x-ui'* || $detected == *'hiddify'* ||
    $detected == *'sing-box'* || $detected == *'hysteria'* || $detected == *'openvpn'* ]]; then
    ST_PROFILE='vpn-node'
  elif [[ $detected == *'wireguard'* || $detected == *'wg-dashboard'* ]]; then
    ST_PROFILE='wireguard'
  elif [[ $detected == *'marzban-panel'* ]]; then
    ST_PROFILE='panel'
  else
    ST_PROFILE='general'
    ST_PROFILE_SOURCE='nothing detected'
  fi
}

# profile_wants_forwarding — vpn workloads route user traffic.
profile_wants_forwarding() {
  [[ $ST_PROFILE == vpn-node || $ST_PROFILE == wireguard || $ST_PROFILE == accounting || $ST_PROFILE == full ]]
}

tier_set() {
  ST_TIER="$1"
  case "$1" in
    S) ST_TIER_USERS='~1k' ST_SOMAXCONN=8192 ST_NETDEV_BACKLOG=16384 ST_BUF_MB=8 ST_CONNTRACK=65536 ;;
    M) ST_TIER_USERS='~10k' ST_SOMAXCONN=16384 ST_NETDEV_BACKLOG=32768 ST_BUF_MB=16 ST_CONNTRACK=262144 ;;
    L) ST_TIER_USERS='~100k' ST_SOMAXCONN=32768 ST_NETDEV_BACKLOG=65536 ST_BUF_MB=32 ST_CONNTRACK=1048576 ;;
    XL) ST_TIER_USERS='100k+' ST_SOMAXCONN=65535 ST_NETDEV_BACKLOG=65536 ST_BUF_MB=64 ST_CONNTRACK=2097152 ;;
    *) tier_set S ;;
  esac
}

# tier_compute — pick from RAM; the capacity_tier config key overrides.
tier_compute() {
  local override ram_mb
  override="$(config_get capacity_tier auto)"
  case "$override" in
    S | M | L | XL)
      tier_set "$override"
      return 0
      ;;
  esac

  ram_mb="$(mem_total_mb)"
  if ((ram_mb <= 1536)); then
    tier_set S
  elif ((ram_mb <= 6144)); then
    tier_set M
  elif ((ram_mb <= 24576)); then
    tier_set L
  else
    tier_set XL
  fi

  # A panel host never needs an L/XL conntrack table (docs/PROFILES.md) —
  # its RAM is better left to the database.
  if [[ $ST_PROFILE == panel && ($ST_TIER == L || $ST_TIER == XL) ]]; then
    tier_set M
  fi

  capacity_apply_users
  return 0
}

tier_conntrack_ram_mb() {
  # ~300 bytes per conntrack entry, worst case (table full).
  printf '%d' $((ST_CONNTRACK * 300 / 1048576))
}

# --- User-based capacity model -------------------------------------------
# Conntrack demand follows the ACTIVE USER COUNT, not RAM: ~24 flows per
# online user × 1.5 headroom. RAM still sizes the buffers, and the honest
# feasibility check below warns when the combination cannot fit.

ST_EXPECTED_USERS=0

# capacity_apply_users — override ST_CONNTRACK from expected users (config
# key expected_users; the --users CLI flag wins when given). No-op when 0.
capacity_apply_users() {
  local users ct
  users="$(config_get expected_users 0)"
  if [[ ${ST_AUTO_USERS:-} =~ ^[0-9]+$ ]] && ((${ST_AUTO_USERS:-0} > 0)); then
    users="$ST_AUTO_USERS"
  fi
  [[ $users =~ ^[0-9]+$ ]] || users=0
  ST_EXPECTED_USERS="$users"
  ((users > 0)) || return 0

  ct=$((users * 24 * 3 / 2))
  ((ct < 65536)) && ct=65536
  ((ct > 4194304)) && ct=4194304
  ST_CONNTRACK="$ct"
  return 0
}

# capacity_warning — prints an honest RAM-math warning when the estimated
# need (conntrack + ~0.5 MB proxy userspace per online user) crowds >75% of
# RAM; prints nothing when the sizing fits.
capacity_warning() {
  ((ST_EXPECTED_USERS > 0)) || return 0
  local ram_mb ct_mb proxy_mb need_mb
  ram_mb="$(mem_total_mb)"
  ct_mb=$((ST_CONNTRACK * 300 / 1048576))
  proxy_mb=$((ST_EXPECTED_USERS / 2))
  need_mb=$((ct_mb + proxy_mb))
  if ((ram_mb > 0 && need_mb > ram_mb * 3 / 4)); then
    printf 'estimated need ~%d MB (conntrack %d + proxy ~%d) vs %d MB RAM — OOM risk at peak. Split users across nodes or add RAM (rule of thumb: ~8 GB per 10k users).' \
      "$need_mb" "$ct_mb" "$proxy_mb" "$ram_mb"
  fi
  return 0
}

# ------------------------- src/modules/sysctl.sh -------------------------
# ============================================================================
# modules/sysctl.sh — kernel network tuning. Implements docs/SYSCTL.md
# exactly: Layer 1 (base) always, Layer 2 forwarding keys for VPN profiles.
# Every written file is tracked via st_track_file for rollback, and every
# apply ends in sysctl_verify() comparing the live kernel to the intent.
# ============================================================================

readonly ST_SYSCTL_FILE='/etc/sysctl.d/99-server-tools.conf'
readonly ST_MODULES_FILE='/etc/modules-load.d/server-tools.conf'
readonly ST_MODPROBE_FILE='/etc/modprobe.d/server-tools.conf'

ST_CC='cubic'
ST_QDISC='fq_codel'
ST_AUTO_QDISC='' # --qdisc: fq | fq_codel | cake (empty = config / auto)

# sysctl_detect_bbr — pick congestion control and queueing discipline.
# fq_codel is ALWAYS the first choice, with BBR or without; fq and cake are
# opt-in (--qdisc / config key `qdisc`), and fq_codel is the fallback when the
# kernel lacks the requested one.
# The qdisc is probed for real (see qdisc_supported) instead of assumed, and
# an explicit `qdisc` config key wins when the kernel actually supports it.
sysctl_detect_bbr() {
  ST_CC='cubic'
  ST_QDISC='fq_codel'

  if ver_ge "$(kernel_base)" "4.9"; then
    # Kernels with built-in BBR have no module to load; availability is
    # verified against the actual sysctl list right after.
    ((ST_DRY_RUN)) || modprobe tcp_bbr 2>/dev/null || true # absent module is not fatal
    if [[ " $(sysctl_get net.ipv4.tcp_available_congestion_control) " == *bbr* ]]; then
      ST_CC='bbr'
    elif ((ST_DRY_RUN)) && has_cmd modinfo && modinfo -n tcp_bbr >/dev/null 2>&1; then
      # Dry-run must not load anything, so on a host where tcp_bbr is a module
      # that is not loaded YET, the sysctl list above still says "no bbr" — and
      # the plan would promise cubic while the real run (which does modprobe)
      # delivers BBR. Inspecting the module without loading it, exactly as
      # qdisc_supported does under dry-run, makes the preview match the outcome.
      ST_CC='bbr'
    fi
  fi

  local wanted
  wanted="${ST_AUTO_QDISC:-$(config_get qdisc auto)}"
  if [[ $wanted != auto ]]; then
    if qdisc_supported "$wanted"; then
      ST_QDISC="$wanted"
    else
      log_warn "Configured qdisc '${wanted}' is not supported by this kernel — using ${ST_QDISC}."
    fi
  fi

  if ! qdisc_supported "$ST_QDISC"; then
    log_warn "Kernel does not support ${ST_QDISC} — falling back to fq_codel."
    ST_QDISC='fq_codel'
  fi
  return 0
}

# _sysctl_reserved_ports — listening ports inside our ephemeral range, so an
# outgoing connection can never grab a panel/node listener. Consecutive
# ports are collapsed into ranges, which keeps the value short enough to
# cover far more than a flat list would. Extra ports can be pinned with the
# `reserved_ports` config key (comma separated) for inbounds added later.
_sysctl_reserved_ports() {
  local detected='' extra
  detected="$(listening_service_ports)" || detected=''
  extra="$(config_get reserved_ports '')"
  [[ -n $extra ]] && detected+=$'\n'"${extra//,/$'\n'}"
  [[ -n $detected ]] || return 0

  # Collapse runs of consecutive ports: 11000 11001 11002 -> 11000-11002.
  printf '%s\n' "$detected" |
    grep -E '^[0-9]+$' |
    sort -un |
    awk '
      NR == 1 { start = last = $1; next }
      $1 == last + 1 { last = $1; next }
      { print (start == last ? start : start "-" last); start = last = $1 }
      END { if (NR) print (start == last ? start : start "-" last) }
    ' |
    awk 'NR <= 64' |
    paste -sd, -
}

# _sysctl_triple_ceiling KEY MIN DEFAULT MAX — the ceiling rule for the
# three-field memory keys (tcp_rmem/tcp_wmem): emit each field as the greater
# of ours and the running kernel's. The middle field is the *initial* buffer a
# new socket gets, and modern kernels raised their own default (tcp_rmem is
# "4096 131072 6291456" on 6.x); a hardcoded triple silently shrank it back to
# the pre-4.20 87380, i.e. a smaller initial receive window on every new
# connection. Raising is tuning; lowering a kernel default is a regression.
_sysctl_triple_ceiling() {
  local key="$1" cur i
  local -a want=("$2" "$3" "$4") live=()
  cur="$(sysctl_get "$key")"
  # sysctl prints these tab-separated; accept any run of whitespace.
  if [[ $cur =~ ^[0-9]+[[:space:]]+[0-9]+[[:space:]]+[0-9]+$ ]]; then
    # The global IFS ($'\n\t') has no space, so it must be set explicitly here.
    IFS=$' \t' read -ra live <<<"$cur"
    for i in 0 1 2; do
      if ((live[i] > want[i])); then want[i]="${live[i]}"; fi
    done
  fi
  printf '%s = %s %s %s\n' "$key" "${want[0]}" "${want[1]}" "${want[2]}"
}

# _sysctl_ceiling KEY TARGET — emit "KEY = N" where N is the greater of the
# running kernel value and TARGET. Modern kernels ship high defaults for these
# capacity keys (e.g. vm.max_map_count is 1048576 since 6.7, fs.file-max is
# effectively unlimited); a fixed value would REGRESS them. Raising is fine,
# lowering a kernel/distro default is not.
_sysctl_ceiling() {
  local key="$1" target="$2" cur
  cur="$(sysctl_get "$key")"
  [[ $cur =~ ^[0-9]+$ ]] && ((cur > target)) && target="$cur"
  printf '%s = %s\n' "$key" "$target"
}

_sysctl_render() {
  local buf_bytes=$((ST_BUF_MB * 1048576))
  local ram_mb ram_pages swappiness=10 fastopen=3
  ram_mb="$(mem_total_mb)"
  ram_pages=$((ram_mb * 256)) # 4 KiB pages

  # Compressed swap is orders of magnitude faster than a disk swap file, so
  # the kernel should actually use it instead of treating it as a last resort.
  [[ "$(swap_backend_active)" == zram ]] && swappiness=100

  # TCP Fast Open opens an extra fingerprinting surface on servers exposed to
  # DPI, and some middleboxes drop SYNs carrying data. VPN workloads keep the
  # outgoing (client) half only; ordinary servers keep both.
  profile_wants_forwarding && fastopen=1

  cat <<EOF
# Generated by ${ST_NAME} v${ST_VERSION} (profile=${ST_PROFILE}, tier=${ST_TIER})
# The rationale for every key lives in docs/SYSCTL.md:
# ${ST_REPO_URL}

# --- Congestion control & queueing
net.core.default_qdisc = ${ST_QDISC}
net.ipv4.tcp_congestion_control = ${ST_CC}

# --- Connection accept path (tier ${ST_TIER})
net.core.somaxconn = ${ST_SOMAXCONN}
net.ipv4.tcp_max_syn_backlog = ${ST_SOMAXCONN}
net.core.netdev_max_backlog = ${ST_NETDEV_BACKLOG}
net.ipv4.tcp_syncookies = 1
# Drain more packets per softirq before yielding — a single core can otherwise
# cap the packet rate on a busy node (paired with RPS in the perf module).
net.core.netdev_budget = 600
net.core.netdev_budget_usecs = 8000

# --- Ports, timers, keepalive
net.ipv4.ip_local_port_range = 10240 65535
net.ipv4.tcp_fin_timeout = 30
net.ipv4.tcp_tw_reuse = 1
net.ipv4.tcp_keepalive_time = 300
net.ipv4.tcp_keepalive_intvl = 60
net.ipv4.tcp_keepalive_probes = 5
net.ipv4.tcp_slow_start_after_idle = 0
net.ipv4.tcp_no_metrics_save = 1
net.ipv4.tcp_fastopen = ${fastopen}
net.ipv4.tcp_notsent_lowat = 16384
# Protect TIME-WAIT sockets from RST assassination (RFC 1337).
net.ipv4.tcp_rfc1337 = 1
# Mode 1 probes only after a blackhole is detected (mode 2 is the harmful one).
net.ipv4.tcp_mtu_probing = 1
# CVE-2019-11479 safe floor: keeps PMTU probing useful without letting a peer
# force a pathologically small MSS (goodput collapse / remote DoS).
net.ipv4.tcp_min_snd_mss = 512

# --- Buffers (tier ${ST_TIER})
net.core.rmem_max = ${buf_bytes}
net.core.wmem_max = ${buf_bytes}
net.core.rmem_default = 262144
net.core.wmem_default = 262144
$(_sysctl_triple_ceiling net.ipv4.tcp_rmem 4096 87380 "${buf_bytes}")
$(_sysctl_triple_ceiling net.ipv4.tcp_wmem 4096 65536 "${buf_bytes}")
net.ipv4.udp_rmem_min = 16384
net.ipv4.udp_wmem_min = 16384
# udp_mem is deliberately NOT set: the kernel already sizes it from RAM, and a
# fixed formula only ever caps it lower on a busy UDP (QUIC/Hysteria) node.
$(_sysctl_ceiling net.core.optmem_max 131072)

# --- System capacity (ceilings — never below the running kernel's own value)
$(_sysctl_ceiling fs.file-max 2097152)
$(_sysctl_ceiling fs.nr_open 2097152)
# Xray/sing-box map many buffers per connection; the ~65k default caps scale.
$(_sysctl_ceiling vm.max_map_count 262144)
vm.swappiness = ${swappiness}
# Cheap, universally-safe ICMP hardening.
net.ipv4.icmp_echo_ignore_broadcasts = 1
net.ipv4.icmp_ignore_bogus_error_responses = 1
EOF

  # User-based capacity mode: bound total TCP memory explicitly so buffer
  # autotuning can never crowd a small-RAM host out of userspace memory.
  if ((ST_EXPECTED_USERS > 0)); then
    cat <<EOF

# --- TCP memory bounds (user-based capacity mode: ${ST_EXPECTED_USERS} users)
net.ipv4.tcp_mem = $((ram_pages * 10 / 100)) $((ram_pages * 13 / 100)) $((ram_pages * 16 / 100))
EOF
  fi

  # High-churn caps only where the connection volume justifies them.
  if [[ $ST_TIER == L || $ST_TIER == XL ]]; then
    local tw_buckets=524288 max_orphans=131072
    if [[ $ST_TIER == XL ]]; then
      tw_buckets=1048576
      max_orphans=262144
    fi
    cat <<EOF

# --- High-churn caps (tier ${ST_TIER})
net.ipv4.tcp_max_tw_buckets = ${tw_buckets}
net.ipv4.tcp_max_orphans = ${max_orphans}
EOF
  fi

  local reserved
  reserved="$(_sysctl_reserved_ports)" || reserved=''
  if [[ -n $reserved ]]; then
    cat <<EOF

# --- Listening ports inside the ephemeral range, reserved automatically
net.ipv4.ip_local_reserved_ports = ${reserved}
EOF
  fi

  if profile_wants_forwarding; then
    # UDP conntrack entries dominate the table on QUIC/Hysteria2 nodes: the
    # kernel keeps an assured stream for 120s by default. Proxy traffic keeps
    # flowing (so active flows are refreshed), while WireGuard benefits from
    # longer-lived NAT mappings, hence the profile split.
    local udp_stream=60
    [[ $ST_PROFILE == wireguard ]] && udp_stream=180

    cat <<EOF

# --- VPN workload (profile ${ST_PROFILE}): routing + conntrack + hardening
net.ipv4.ip_forward = 1
net.ipv6.conf.all.forwarding = 1
net.netfilter.nf_conntrack_max = ${ST_CONNTRACK}
# Kernel default is 5 DAYS — idle VPN flows would exhaust the table.
net.netfilter.nf_conntrack_tcp_timeout_established = 3600
net.netfilter.nf_conntrack_tcp_timeout_time_wait = 60
net.netfilter.nf_conntrack_tcp_timeout_close_wait = 30
net.netfilter.nf_conntrack_udp_timeout = 30
net.netfilter.nf_conntrack_udp_timeout_stream = ${udp_stream}
net.netfilter.nf_conntrack_generic_timeout = 300
net.ipv4.conf.all.rp_filter = 2
net.ipv4.conf.default.rp_filter = 2
net.ipv4.conf.all.accept_redirects = 0
net.ipv4.conf.default.accept_redirects = 0
net.ipv4.conf.all.send_redirects = 0
net.ipv4.conf.default.send_redirects = 0
net.ipv4.conf.all.accept_source_route = 0
net.ipv4.conf.default.accept_source_route = 0
EOF

    # Enabling IPv6 forwarding makes the kernel ignore router advertisements,
    # which silently kills the IPv6 default route on RA/SLAAC providers after
    # a reboot. Value 2 keeps accepting RAs while forwarding.
    # accept_ra is per-device, so the live interface must be named explicitly.
    local iface iface_ra
    iface="$(net_default_iface)" || iface=''
    cat <<EOF
net.ipv6.conf.all.accept_ra = 2
net.ipv6.conf.default.accept_ra = 2
EOF
    # Per-interface accept_ra is only pinned where the link ACTUALLY uses RA.
    # On a statically-addressed link networkd holds accept_ra at 0 and reverts
    # our value on every reload — a permanent false "drift" — and forcing RA
    # acceptance there is pointless. So we set it only when the link already
    # accepts RAs (value >= 1). The leading "-" lets systemd-sysctl ignore the
    # line if the interface is absent at early boot.
    if [[ -n $iface ]]; then
      iface_ra="$(sysctl_get "net.ipv6.conf.${iface}.accept_ra")"
      [[ $iface_ra =~ ^[1-9] ]] &&
        printf -- '-net.ipv6.conf.%s.accept_ra = 2\n' "$iface"
    fi
  fi

  # This helper's stdout is captured via `rendered="$(_sysctl_render)"`. Under
  # errexit a bare assignment propagates the callee's exit status, so a
  # trailing conditional evaluating false (e.g. the accept_ra guard above on a
  # host with no default route) would trip the ERR trap and abort the run.
  # Value-producing helpers must therefore always return success explicitly.
  return 0
}

# _ports_expand LIST — "80,1000-1002" -> a sorted, space separated port set.
# The kernel normalises ip_local_reserved_ports (it stores a bitmap and
# prints merged ranges), so that key can only be compared as a set.
_ports_expand() {
  local item low high
  {
    while IFS= read -r item; do
      if [[ $item == *-* ]]; then
        low="${item%%-*}"
        high="${item##*-}"
        [[ $low =~ ^[0-9]+$ && $high =~ ^[0-9]+$ ]] || continue
        while ((low <= high)); do
          printf '%s\n' "$low"
          low=$((low + 1))
        done
      elif [[ $item =~ ^[0-9]+$ ]]; then
        printf '%s\n' "$item"
      fi
    done < <(ports_split "$1")
  } | sort -un | paste -sd' ' -
}

# _ports_covered WANTED HAVE — 0 when every port in WANTED is also in HAVE
# (both in "80,1000-1002" form). Coverage, not equality.
_ports_covered() {
  local wanted have missing
  wanted="$(_ports_expand "$1" | tr ' ' '\n')"
  have="$(_ports_expand "$2" | tr ' ' '\n')"
  [[ -n $wanted ]] || return 0
  missing="$(_ports_subtract "$have" <<<"$wanted")"
  [[ -z $missing ]]
}

# _sysctl_values_match KEY ACTUAL EXPECTED
_sysctl_values_match() {
  case "$1" in
    net.ipv4.ip_local_reserved_ports)
      # Coverage, not equality: this is the one key whose intent is rebuilt from
      # the live system on every render, so the set legitimately differs between
      # runs (a service stopped, a session port vanished). Reserving MORE than
      # we ask for is harmless — a missing port is the actual hazard, and Doctor
      # reports that separately via _doctor_unreserved_ports. Comparing for
      # equality made this key report drift forever on a busy node.
      _ports_covered "$3" "$2"
      ;;
    *)
      # Normalise whitespace runs so multi-value keys compare fairly.
      [[ "$(tr -s ' \t' ' ' <<<"$2")" == "$(tr -s ' \t' ' ' <<<"$3")" ]]
      ;;
  esac
}

# sysctl_verify [RENDERED] — compare the live kernel against the intent of
# this profile (the text just written, or the file on disk when called with no
# argument). Returns 0 when everything matches, 2 when never configured, 3 on drift.
# The caller passes the text it actually wrote: re-rendering here would read
# live inputs again (listening ports, swap backend) and could compare against
# a different expectation than the one on disk.
ST_SYSCTL_DRIFT=()

sysctl_verify() {
  ST_SYSCTL_DRIFT=()
  local rendered="${1:-}" line key expected actual
  if [[ -z $rendered ]]; then
    # Standalone callers (Doctor, health, menu) have no profile/tier in memory,
    # so re-rendering would compare against defaults and report false drift on a
    # perfectly tuned host. The file on disk IS the intent.
    [[ -f $ST_SYSCTL_FILE ]] || return 2
    rendered="$(<"$ST_SYSCTL_FILE")"
  fi

  while IFS= read -r line; do
    [[ -z $line || $line == \#* ]] && continue
    expected="${line#*=}"
    expected="${expected#"${expected%%[![:space:]]*}"}"
    key="${line%%=*}"
    key="${key//[[:space:]]/}"
    key="${key#-}" # a leading "-" only tells systemd to ignore failures
    actual="$(sysctl_get "$key")"
    _sysctl_values_match "$key" "$actual" "$expected" ||
      ST_SYSCTL_DRIFT+=("${key}|${actual}|${expected}")
  done <<<"$rendered"

  ((${#ST_SYSCTL_DRIFT[@]} == 0)) && return 0
  return 3
}

# sysctl_dry_run — render the exact config this run would write and diff
# every key against the live kernel. Applies NOTHING and tracks nothing.
sysctl_dry_run() {
  sysctl_detect_bbr
  local rendered
  rendered="$(_sysctl_render)"
  printf '%s[Rendered %s]%s\n%s\n\n' "$C_TITLE" "$ST_SYSCTL_FILE" "$C_RESET" "$rendered"
  printf '%s[Diff vs live kernel]%s\n' "$C_TITLE" "$C_RESET"

  local entry key actual expected total
  total="$(grep -cE '^-?[a-z]' <<<"$rendered")"
  sysctl_verify "$rendered" || true # drift is the expected outcome here
  if ((${#ST_SYSCTL_DRIFT[@]} == 0)); then
    printf '  (kernel already matches this profile)\n'
  else
    # Guarded: iterating "${arr[@]-}" on an empty array yields one empty
    # element, which would print a bare "->" row.
    for entry in "${ST_SYSCTL_DRIFT[@]}"; do
      IFS='|' read -r key actual expected <<<"$entry"
      printf '  %s%-50s%s %s -> %s\n' "$C_KEY" "$key" "$C_RESET" "$actual" "$expected"
    done
  fi
  printf '\n%s%d of %d keys would change. Nothing was applied.%s\n' \
    "$C_WARN" "${#ST_SYSCTL_DRIFT[@]}" "$total" "$C_RESET"
}

# _sysctl_neutralize_overrides RENDERED — `sysctl --system` reads /etc/sysctl.d
# in name order and /etc/sysctl.conf LAST, so a stock sysctl.conf that sets
# the same key (Ubuntu images often carry default_qdisc=fq_codel there) silently
# beats our file at every apply and every boot. No file name can win against
# it, so the conflicting lines are commented out — tracked first, so a rollback
# restores them exactly. Only keys we set, with a DIFFERENT value, are touched.
_sysctl_neutralize_overrides() {
  local rendered="$1" ours candidate real tmp base n
  local -a seen=()
  ours="$(basename "$ST_SYSCTL_FILE")"
  local -a candidates=(/etc/sysctl.conf)
  for candidate in /etc/sysctl.d/*.conf; do
    [[ -e $candidate ]] || continue
    base="$(basename "$candidate")"
    # Files sorting before ours lose to it anyway; leave them alone.
    [[ $base > "$ours" ]] && candidates+=("$candidate")
  done

  for candidate in "${candidates[@]}"; do
    [[ -f $candidate ]] || continue
    real="$(readlink -f "$candidate")" || continue
    [[ $real == /etc/* && $real != "$ST_SYSCTL_FILE" ]] || continue
    [[ " ${seen[*]-} " == *" $real "* ]] && continue
    seen+=("$real")

    tmp="${real}.st-tmp"
    awk -v ours="$ours" '
      function norm(s) { gsub(/[[:space:]]+/, " ", s); sub(/^ /, "", s); sub(/ $/, "", s); return s }
      function key(s) { s = norm(s); sub(/^-/, "", s); gsub(/\//, ".", s); return s }
      NR == FNR {
        if ($0 ~ /^[[:space:]]*(#|$)/) next
        i = index($0, "=")
        if (i > 0) want[key(substr($0, 1, i - 1))] = norm(substr($0, i + 1))
        next
      }
      {
        i = index($0, "=")
        if ($0 !~ /^[[:space:]]*[#;]/ && i > 0) {
          k = key(substr($0, 1, i - 1))
          if ((k in want) && norm(substr($0, i + 1)) != want[k]) {
            print "# [ServerTools] overridden by " ours ": " $0
            next
          }
        }
        print
      }' <(printf '%s\n' "$rendered") "$real" >"$tmp" || {
      rm -f "$tmp"
      log_warn "Could not scan ${real} for conflicting sysctl keys."
      continue
    }
    if cmp -s "$tmp" "$real"; then
      rm -f "$tmp"
      continue
    fi
    n="$(grep -c '^# \[ServerTools\] overridden by' "$tmp")" || n=0
    st_track_file "$real"
    cat "$tmp" >"$real"
    rm -f "$tmp"
    log_info "Disabled ${n} sysctl line(s) in ${real} that override ${ours}."
    ST_LOG_BUFFER+=("Disabled ${n} conflicting line(s) in ${real} (it is read last and was overriding the tuning; a rollback restores them).")
  done
  return 0
}

sysctl_apply() {
  if ! has_cmd sysctl; then
    log_error "sysctl command not found — cannot tune the kernel."
    return 1
  fi

  sysctl_detect_bbr

  local modules=()
  [[ $ST_CC == bbr ]] && modules+=(tcp_bbr)

  if profile_wants_forwarding; then
    # Without the module loaded, net.netfilter.* keys silently fail to apply.
    modprobe nf_conntrack 2>/dev/null ||
      log_warn "nf_conntrack module unavailable — conntrack keys may not apply."
    modules+=(nf_conntrack)
  fi

  # Rendered exactly once: the same text is written and later verified.
  local rendered
  rendered="$(_sysctl_render)"

  st_track_file "$ST_SYSCTL_FILE"
  mkdir -p "$(dirname "$ST_SYSCTL_FILE")"
  printf '%s\n' "$rendered" >"$ST_SYSCTL_FILE"
  _sysctl_neutralize_overrides "$rendered"

  if ((${#modules[@]} > 0)); then
    st_track_file "$ST_MODULES_FILE"
    mkdir -p "$(dirname "$ST_MODULES_FILE")"
    {
      printf '# Generated by %s v%s\n' "$ST_NAME" "$ST_VERSION"
      printf '%s\n' "${modules[@]}"
    } >"$ST_MODULES_FILE"
  fi

  if profile_wants_forwarding; then
    # The conntrack hash table must scale with the table itself; the runtime
    # knob is a module parameter, persisted for reboots via modprobe.d.
    local hashsize=$((ST_CONNTRACK / 4))
    st_track_file "$ST_MODPROBE_FILE"
    mkdir -p "$(dirname "$ST_MODPROBE_FILE")"
    printf '# Generated by %s v%s\noptions nf_conntrack hashsize=%s\n' \
      "$ST_NAME" "$ST_VERSION" "$hashsize" >"$ST_MODPROBE_FILE"
    if [[ -w /sys/module/nf_conntrack/parameters/hashsize ]]; then
      printf '%s' "$hashsize" >/sys/module/nf_conntrack/parameters/hashsize 2>>"$ST_LOG_FILE" ||
        log_warn "Could not resize the conntrack hash table live (persisted for next boot)."
    fi
  fi

  # Apply; per-key errors land in the log instead of vanishing — the result
  # is verified against the live kernel right after.
  sysctl --system >/dev/null 2>>"$ST_LOG_FILE" || true

  # default_qdisc only affects NEW interfaces; switch the live default
  # interface too so the change is complete without a reboot.
  local iface
  iface="$(net_default_iface)" || iface=''
  if [[ -n $iface ]] && has_cmd tc; then
    tc qdisc replace dev "$iface" root "$ST_QDISC" 2>>"$ST_LOG_FILE" ||
      log_warn "Could not switch ${iface} to ${ST_QDISC} live (it applies after reboot)."
  fi

  local rc=0
  if ! sysctl_verify "$rendered"; then
    local entry key actual expected names=''
    for entry in "${ST_SYSCTL_DRIFT[@]}"; do
      IFS='|' read -r key actual expected <<<"$entry"
      names+="${key} "
      log_info "drift: ${key} is '${actual}', expected '${expected}'"
    done
    log_warn "${#ST_SYSCTL_DRIFT[@]} key(s) did not take the expected value: ${names% }"
    rc=3
  fi

  log_info "sysctl applied: cc=$(sysctl_get net.ipv4.tcp_congestion_control), qdisc=${ST_QDISC}, tier=${ST_TIER}, profile=${ST_PROFILE}"
  return "$rc"
}

# qdisc_verify — the queue discipline is checked against what ServerTools
# configured (fq_codel unless --qdisc / the config key chose otherwise), both
# as the kernel default and on the real default interface.
# 0 in effect · 2 not configured here · 3 drifted.
qdisc_verify() {
  [[ -f $ST_SYSCTL_FILE ]] || return 2
  local want live iface shown
  want="$(awk -F'= *' '/^net.core.default_qdisc/ {print $2; exit}' "$ST_SYSCTL_FILE")" || want=''
  [[ -n $want ]] || return 2
  live="$(sysctl_get net.core.default_qdisc)"
  [[ $live == "$want" ]] || return 3
  iface="$(net_default_iface)" || iface=''
  if [[ -n $iface ]] && has_cmd tc; then
    # A multiqueue NIC shows "mq" at the root with the real qdisc on its
    # queues, so look at everything attached to the interface, not just the root.
    shown="$(tc qdisc show dev "$iface" 2>/dev/null)" || shown=''
    [[ -z $shown || $shown == *"qdisc ${want} "* ]] || return 3
  fi
  return 0
}

# ------------------------- src/modules/dns.sh -------------------------
# ============================================================================
# modules/dns.sh — DNS provider selection and application that actually sticks.
#
# Selection and application are deliberately decoupled: "Keep current DNS"
# really keeps it. Applying is harder than writing one file:
#
#   * systemd list settings ACCUMULATE across drop-ins — without an empty
#     reset assignment the previously configured servers stay ahead of ours;
#   * per-link DNS (netplan / DHCP) takes PRECEDENCE over the global resolved
#     configuration, so it must be overridden now and persisted for reboots;
#   * /etc/resolv.conf may bypass systemd-resolved entirely.
#
# Every path therefore ends in a verification of what will really answer
# queries — a written config file alone is never reported as success.
# ============================================================================

readonly ST_RESOLVED_DROPIN='/etc/systemd/resolved.conf.d/99-server-tools.conf'
readonly ST_DNS_UNIT='/etc/systemd/system/server-tools-dns.service'

ST_DNS1=''
ST_DNS2=''

# Format: name|primary|secondary
# Iran-hosted anti-sanction resolvers with PUBLIC IPs only — services like
# 403.online announce private-range addresses that only route inside Iran.
readonly -a ST_DNS_PROVIDERS=(
  'Cloudflare|1.1.1.1|1.0.0.1'
  'Google|8.8.8.8|8.8.4.4'
  'Quad9|9.9.9.9|149.112.112.112'
  'OpenDNS|208.67.222.222|208.67.220.220'
  'Shecan (for Iran-hosted servers)|178.22.122.100|185.51.200.2'
  'Electro (for Iran-hosted servers)|78.157.42.100|78.157.42.101'
  'Begzar (for Iran-hosted servers)|185.55.226.26|185.55.225.25'
)

# is_valid_ip — a real address in either family (see core/utils.sh).
is_valid_ip() {
  is_valid_ipv4 "$1" || is_valid_ipv6 "$1"
}

# --- Inspection -----------------------------------------------------------

# dns_stack — which resolver actually owns /etc/resolv.conf on this host.
dns_stack() {
  if has_cmd systemctl && systemctl is-active --quiet systemd-resolved 2>/dev/null; then
    printf 'resolved'
  elif has_cmd resolvconf && [[ -d /etc/resolvconf/resolv.conf.d ]]; then
    printf 'resolvconf'
  else
    printf 'plain'
  fi
}

# _dns_link_servers IFACE — servers configured on that link ("" when none).
_dns_link_servers() {
  has_cmd resolvectl || return 0
  resolvectl dns "$1" 2>/dev/null |
    sed -e 's/^Link [0-9]* ([^)]*)://' -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//'
}

# _resolvectl_status — cached copy of `resolvectl status`.
# Parsing it through a pipe is a trap: an awk that exits early kills the
# producer with SIGPIPE, pipefail turns that into a failed command, and the
# caller's error branch then discards the value that was read correctly.
# Capture first, parse from a here-string.
ST_RESOLVECTL_STATUS=''

_resolvectl_status() {
  has_cmd resolvectl || return 1
  if [[ -z $ST_RESOLVECTL_STATUS ]]; then
    ST_RESOLVECTL_STATUS="$(resolvectl status 2>/dev/null)" || ST_RESOLVECTL_STATUS=''
  fi
  [[ -n $ST_RESOLVECTL_STATUS ]] || return 1
  printf '%s' "$ST_RESOLVECTL_STATUS"
}

# _dns_global_servers — servers in the resolved global scope ("" when none).
_dns_global_servers() {
  local status
  status="$(_resolvectl_status)" || return 0
  awk '/^ *DNS Servers:/ {sub(/^ *DNS Servers: */, ""); print; exit}' <<<"$status"
}

# dns_effective_servers — what will really answer queries: link scope first
# (it wins over global), then global, then plain resolv.conf.
dns_effective_servers() {
  local iface link
  if has_cmd resolvectl; then
    iface="$(net_default_iface)" || iface=''
    if [[ -n $iface ]]; then
      link="$(_dns_link_servers "$iface")"
      if [[ -n $link ]]; then
        printf '%s' "$link"
        return 0
      fi
    fi
    link="$(_dns_global_servers)"
    if [[ -n $link ]]; then
      printf '%s' "$link"
      return 0
    fi
  fi
  awk '/^[[:space:]]*nameserver/ {printf "%s ", $2}' /etc/resolv.conf 2>/dev/null |
    sed 's/[[:space:]]*$//'
}

# dns_over_tls_state — current DNSOverTLS mode, "n/a" without resolved.
dns_over_tls_state() {
  local status mode=''
  if status="$(_resolvectl_status)"; then
    mode="$(sed -n 's/.*DNSOverTLS=\([^ ]*\).*/\1/p' <<<"$status" | head -n1)"
  fi
  printf '%s' "${mode:-n/a}"
}

# --- Latency test ---------------------------------------------------------

# _dns_probe_ms IP — a real DNS query time when dig exists (resolvers often
# deprioritize ICMP, so ping understates real performance); ping fallback.
_dns_probe_ms() {
  local out=''
  if has_cmd dig; then
    out="$(dig +tries=1 +time=2 "@$1" google.com A 2>/dev/null)" || return 0
    awk '/Query time:/ {print $4; exit}' <<<"$out"
  elif has_cmd ping; then
    out="$(ping -c 1 -W 1 "$1" 2>/dev/null)" || return 0
    awk -F'time=' '/time=/ {split($2, a, " "); print a[1]; exit}' <<<"$out"
  fi
}

dns_latency_test() {
  if ! has_cmd dig && ! has_cmd ping; then
    printf 'Neither dig nor ping is available on this system.\n'
    return 0
  fi
  local entry name ip1 ip2 ms method='ping'
  has_cmd dig && method='real DNS query (dig)'
  printf '%sLatency per provider — measured via %s:%s\n' "$C_MUTED" "$method" "$C_RESET"
  for entry in "${ST_DNS_PROVIDERS[@]}"; do
    IFS='|' read -r name ip1 ip2 <<<"$entry"
    ms="$(_dns_probe_ms "$ip1")" || ms=''
    if [[ -n $ms ]]; then
      printf '  %-34s %s ms\n' "$name" "$ms"
    else
      printf '  %-34s timeout\n' "$name"
    fi
  done
}

# --- Selection ------------------------------------------------------------

# dns_select_menu — sets ST_DNS1/ST_DNS2 and returns 0 when the user picked
# a provider to apply; returns 1 for "keep current" (caller MUST skip apply).
dns_select_menu() {
  local choice entry name ip1 ip2 i
  while true; do
    printf '\n%s[DNS provider]%s  current: %s\n' \
      "$C_TITLE" "$C_RESET" "$(dns_effective_servers)"
    i=1
    for entry in "${ST_DNS_PROVIDERS[@]}"; do
      IFS='|' read -r name ip1 ip2 <<<"$entry"
      ui_menu_item "$i" "$name" "${ip1} / ${ip2}"
      i=$((i + 1))
    done
    ui_menu_item 8 "Custom" "enter your own (IPv4 or IPv6)"
    ui_menu_item t "Latency test" "measure every provider first"
    ui_menu_item 0 "Keep current DNS" "no DNS change"
    read -rp "Select [0]: " choice || return 1
    case "${choice:-0}" in
      [1-7])
        IFS='|' read -r name ST_DNS1 ST_DNS2 <<<"${ST_DNS_PROVIDERS[$((choice - 1))]}"
        return 0
        ;;
      8)
        read -rp "Primary DNS: " ST_DNS1 || return 1
        read -rp "Secondary DNS: " ST_DNS2 || return 1
        if is_valid_ip "$ST_DNS1" && is_valid_ip "$ST_DNS2"; then
          return 0
        fi
        printf '%sInvalid address — DNS left unchanged.%s\n' "$C_ERR" "$C_RESET"
        return 1
        ;;
      t | T) dns_latency_test ;;
      0) return 1 ;;
      *) printf '%sInvalid choice.%s\n' "$C_ERR" "$C_RESET" ;;
    esac
  done
}

# dns_resolve_cli VALUE — non-interactive parsing for --dns: a provider name
# or "primary,secondary" addresses.
dns_resolve_cli() {
  local value="$1"
  case "${value,,}" in
    cloudflare)
      ST_DNS1='1.1.1.1'
      ST_DNS2='1.0.0.1'
      ;;
    google)
      ST_DNS1='8.8.8.8'
      ST_DNS2='8.8.4.4'
      ;;
    quad9)
      ST_DNS1='9.9.9.9'
      ST_DNS2='149.112.112.112'
      ;;
    opendns)
      ST_DNS1='208.67.222.222'
      ST_DNS2='208.67.220.220'
      ;;
    shecan)
      ST_DNS1='178.22.122.100'
      ST_DNS2='185.51.200.2'
      ;;
    electro)
      ST_DNS1='78.157.42.100'
      ST_DNS2='78.157.42.101'
      ;;
    begzar)
      ST_DNS1='185.55.226.26'
      ST_DNS2='185.55.225.25'
      ;;
    *,*)
      ST_DNS1="${value%%,*}"
      ST_DNS2="${value#*,}"
      is_valid_ip "$ST_DNS1" && is_valid_ip "$ST_DNS2"
      ;;
    *) return 1 ;;
  esac
}

# --- Application ----------------------------------------------------------

# _dns_persist_link IFACE — a runtime `resolvectl dns` override is lost on
# reboot and on DHCP renewal. Preferred fix: clear the link's own DNS in a
# systemd-networkd drop-in so the global configuration governs it (addressing
# is untouched). Fallback for NetworkManager/unmanaged links: a oneshot unit
# that re-applies the override at boot and exits.
_dns_persist_link() {
  local iface="$1" netfile='' dropin
  if has_cmd networkctl; then
    local status
    status="$(SYSTEMD_COLORS=0 networkctl status --no-pager "$iface" 2>/dev/null)" || status=''
    [[ -n $status ]] && netfile="$(awk '/Network File:/ {print $NF; exit}' <<<"$status")"
  fi

  if [[ $netfile == /*.network ]]; then
    dropin="/etc/systemd/network/$(basename "$netfile").d/99-server-tools.conf"
    st_track_file "$dropin"
    mkdir -p "$(dirname "$dropin")"
    cat >"$dropin" <<EOF
# Generated by ${ST_NAME} v${ST_VERSION}
# Pin the chosen DNS on this link and stop consuming the DHCP-provided servers,
# so per-link DNS (which OUTRANKS the global resolved config) points where we
# want. Addressing and routing are deliberately untouched.
[Network]
DNS=${ST_DNS1}
DNS=${ST_DNS2}
[DHCPv4]
UseDNS=false
[DHCPv6]
UseDNS=false
EOF
    # Apply the drop-in now. This is a config-only reload (no re-addressing, so
    # no connectivity blip); networkd then re-pushes the corrected DNS to
    # resolved and stops overwriting it with the DHCP servers.
    if has_cmd networkctl; then
      networkctl reload 2>>"$ST_LOG_FILE" ||
        log_warn "networkctl reload failed — the link DNS drop-in applies on reboot."
    fi
    log_info "Link DNS persistence: networkd drop-in ${dropin} (DHCP DNS disabled)."
    return 0
  fi

  if [[ ! -d /etc/systemd/system ]] || ! has_cmd systemctl || ! has_cmd resolvectl; then
    log_warn "No way to persist the link DNS override — it is active now but resets on reboot."
    return 3
  fi

  # The interface is resolved at boot instead of being baked in: cloud images
  # rename NICs, and network-online.target must be pulled in with Wants= or
  # the After= alone never activates it.
  st_track_file "$ST_DNS_UNIT"
  cat >"$ST_DNS_UNIT" <<EOF
# Generated by ${ST_NAME} v${ST_VERSION}
[Unit]
Description=ServerTools per-link DNS override (oneshot, exits after boot)
After=systemd-resolved.service network-online.target
Wants=systemd-resolved.service network-online.target

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/bin/bash -c 'for i in \$(ip -o link show up | awk -F": " "{print \\\$2}" | sed "s/@.*//" | grep -vE "^(lo|docker|br-|veth|cni|virbr)"); do $(command -v resolvectl) dns "\$i" ${ST_DNS1} ${ST_DNS2} || true; done'

[Install]
WantedBy=multi-user.target
EOF
  systemctl daemon-reload 2>>"$ST_LOG_FILE" || log_warn "daemon-reload failed."
  if systemctl enable server-tools-dns.service >/dev/null 2>>"$ST_LOG_FILE"; then
    manifest_add unit server-tools-dns.service
    log_info "Link DNS persistence: oneshot unit server-tools-dns.service."
    return 0
  fi
  log_warn "Could not enable the DNS persistence unit — override resets on reboot."
  return 3
}

# _dns_override_link — per-link DNS OUTRANKS the global config, so every up
# link that carries its own servers must be re-pointed. This runs the PERSISTENT
# fix (networkd drop-in / oneshot unit) and is called BEFORE the resolved
# restart, so resolved reloads the corrected link DNS instead of the DHCP
# servers. The immediate runtime override is a separate step after the restart
# (see _dns_reassert_links) — doing it before would just be clobbered by
# networkd's post-restart re-push.
_dns_override_link() {
  has_cmd resolvectl || return 0
  local iface current rc=0 handled=0

  while IFS= read -r iface; do
    [[ -n $iface ]] || continue
    current="$(_dns_link_servers "$iface")"
    # No link-level servers: the global scope already governs this link.
    [[ -n $current ]] || continue
    [[ $current == "${ST_DNS1} ${ST_DNS2}" ]] && continue

    log_info "Link ${iface} carries its own DNS (${current}) — pinning ours."
    _dns_persist_link "$iface" || rc=$?
    handled=1
  done < <(net_dns_capable_links)

  ((handled)) && log_info "Per-link DNS pinned."
  return "$rc"
}

# _dns_reassert_links — the immediate runtime override, applied AFTER resolved
# restarts. With DHCP DNS now disabled per link (drop-in above), networkd no
# longer overwrites this, so it holds for the session while the drop-in covers
# reboots.
_dns_reassert_links() {
  has_cmd resolvectl || return 0
  local iface
  while IFS= read -r iface; do
    [[ -n $iface ]] || continue
    resolvectl dns "$iface" "$ST_DNS1" "$ST_DNS2" 2>>"$ST_LOG_FILE" ||
      log_warn "Could not set runtime DNS on ${iface}."
  done < <(net_dns_capable_links)
}

# _dns_resolv_conf_visible — do applications reading /etc/resolv.conf end up
# at our servers? True via the resolved stub, or by listing them directly.
_dns_resolv_conf_visible() {
  grep -qE '^[[:space:]]*nameserver[[:space:]]+127\.0\.0\.5[34]' /etc/resolv.conf 2>/dev/null ||
    grep -qF "$ST_DNS1" /etc/resolv.conf 2>/dev/null
}

_dns_write_resolv_conf() {
  st_track_file /etc/resolv.conf
  if has_cmd chattr; then
    # Some providers lock resolv.conf with +i; unlocking may legitimately
    # fail when the attribute is not set — the write below is the real test.
    chattr -i /etc/resolv.conf 2>/dev/null || true
  fi
  rm -f /etc/resolv.conf
  cat >/etc/resolv.conf <<EOF
# Generated by ${ST_NAME} v${ST_VERSION}
nameserver ${ST_DNS1}
nameserver ${ST_DNS2}
# Fast failover: 2s per try, alternate between the two servers.
options timeout:2 attempts:2 rotate
EOF
}

_dns_apply_resolved() {
  local rc=0
  st_track_file "$ST_RESOLVED_DROPIN"
  mkdir -p "$(dirname "$ST_RESOLVED_DROPIN")"
  cat >"$ST_RESOLVED_DROPIN" <<EOF
# Generated by ${ST_NAME} v${ST_VERSION}
[Resolve]
# The empty assignments RESET the lists inherited from resolved.conf and
# earlier drop-ins — systemd appends to list settings, so without them the
# previously configured servers would stay ahead of ours.
DNS=
DNS=${ST_DNS1} ${ST_DNS2}
# Left empty on purpose: distributions ship Google/Cloudflare fallbacks that
# would silently answer queries the chosen resolver cannot. resolved only
# uses FallbackDNS when no DNS= is known, so a value here would be dead code.
FallbackDNS=
# Encrypt DNS when the resolver supports it, fall back to plain otherwise.
DNSOverTLS=opportunistic
EOF

  # Pin the per-link DNS and disable DHCP DNS BEFORE restarting resolved, so
  # the restart's reload from networkd already carries our servers instead of
  # the ISP's — otherwise networkd's post-restart re-push shadows the global
  # config (the exact failure seen on netplan+DHCP hosts).
  _dns_override_link || rc=$?

  if ! systemctl restart systemd-resolved 2>>"$ST_LOG_FILE"; then
    log_warn "systemd-resolved restart failed — drop-in written but not active yet."
    return 3
  fi

  # Immediate runtime override, now safe from networkd's re-push (DHCP DNS off).
  _dns_reassert_links

  if ! _dns_resolv_conf_visible; then
    log_info "/etc/resolv.conf bypasses systemd-resolved — writing the servers into it directly as well."
    _dns_write_resolv_conf
  fi
  return "$rc"
}

_dns_apply_resolvconf() {
  local head='/etc/resolvconf/resolv.conf.d/head'
  st_track_file "$head"
  cat >"$head" <<EOF
# Generated by ${ST_NAME} v${ST_VERSION}
nameserver ${ST_DNS1}
nameserver ${ST_DNS2}
options timeout:2 attempts:2 rotate
EOF
  if resolvconf -u 2>>"$ST_LOG_FILE"; then
    return 0
  fi
  log_warn "resolvconf -u failed — writing /etc/resolv.conf directly instead."
  _dns_write_resolv_conf
  return 3
}

_dns_apply_plain() {
  _dns_write_resolv_conf
  if has_cmd systemctl && systemctl is-active --quiet NetworkManager 2>/dev/null; then
    log_warn "NetworkManager is active and may rewrite /etc/resolv.conf on the next connection change."
  fi
  return 0
}

# dns_verify — do the servers we configured actually answer queries?
# Returns 0 on match, 3 on drift, 2 when nothing was ever configured.
dns_verify() {
  local want effective
  want="$(config_get dns_primary '')"
  [[ -n $want ]] || return 2
  effective="$(dns_effective_servers)"
  [[ $effective == *"$want"* ]] && return 0
  return 3
}

dns_apply() {
  [[ -n $ST_DNS1 && -n $ST_DNS2 ]] || return 2 # nothing selected — skip

  local stack rc=0
  stack="$(dns_stack)"
  case "$stack" in
    resolved) _dns_apply_resolved || rc=$? ;;
    resolvconf) _dns_apply_resolvconf || rc=$? ;;
    *) _dns_apply_plain || rc=$? ;;
  esac
  ((rc == 1)) && return 1 # hard failure — do not claim anything was applied

  # Config files mean nothing on their own: verify what answers queries now.
  local effective
  effective="$(dns_effective_servers)"
  if [[ $effective != *"$ST_DNS1"* ]]; then
    log_warn "DNS verification failed: '${effective:-none}' is in effect, expected ${ST_DNS1} (stack: ${stack})."
    rc=3
  fi

  config_set dns_primary "$ST_DNS1"
  config_set dns_secondary "$ST_DNS2"
  log_info "DNS applied via ${stack}: ${ST_DNS1} / ${ST_DNS2} (in effect: ${effective:-unknown})"
  return "$rc"
}

# ------------------------- src/modules/swap.sh -------------------------
# ============================================================================
# modules/swap.sh — swap provisioning when no swap exists at all.
#
# Backends (config key swap_backend = auto | file | zram):
#   file — swap file on disk: real extra capacity, the universal safe default.
#   zram — compressed in-RAM swap: no disk needed, much faster than slow VPS
#          disks, but adds no capacity beyond RAM itself.
#   auto — file first (best scenario for most servers); falls back to zram
#          automatically when the disk is too small for a swap file.
#
# The fstab entry / boot unit is only written AFTER swapon verifiably works.
# ============================================================================

readonly ST_ZRAM_UNIT='/etc/systemd/system/server-tools-zram.service'

swap_is_active() {
  [[ -r /proc/swaps ]] && awk 'NR > 1 {found = 1} END {exit !found}' /proc/swaps
}

# swap_backend_active — zram | file | partition | none. The sysctl module
# uses this to pick vm.swappiness: compressed RAM should be used eagerly,
# a disk swap file should not.
swap_backend_active() {
  [[ -r /proc/swaps ]] || {
    printf 'none'
    return 0
  }
  awk 'NR > 1 {
    if ($1 ~ /zram/) { print "zram"; exit }
    print ($2 == "file" ? "file" : "partition"); exit
  } END { if (NR < 2) print "none" }' /proc/swaps
}

# swap_verify — 0 when swap is available, 3 when the host has none at all.
swap_verify() {
  swap_is_active && return 0
  return 3
}

# _swap_file_setup SIZE_MB
_swap_file_setup() {
  local size_mb="$1" swapfile='/swapfile' fstype
  st_track_file /etc/fstab
  st_track_file "$swapfile" # recorded as "created" so rollback removes it

  fstype="$(stat -f -c %T / 2>/dev/null)" || fstype=''
  if [[ $fstype == btrfs ]]; then
    # CoW must be disabled on the empty file before any data is written, and
    # fallocate'd files are not usable as swap on btrfs — always use dd.
    touch "$swapfile"
    if has_cmd chattr; then
      chattr +C "$swapfile" 2>/dev/null || true # best effort; swapon verifies below
    fi
    dd if=/dev/zero of="$swapfile" bs=1M count="$size_mb" status=none 2>>"$ST_LOG_FILE" || return 1
  else
    if ! fallocate -l "${size_mb}M" "$swapfile" 2>/dev/null; then
      dd if=/dev/zero of="$swapfile" bs=1M count="$size_mb" status=none 2>>"$ST_LOG_FILE" || return 1
    fi
  fi

  chmod 600 "$swapfile"
  mkswap "$swapfile" >/dev/null 2>>"$ST_LOG_FILE" || return 1
  if ! swapon "$swapfile" 2>>"$ST_LOG_FILE"; then
    log_error "swapon failed (filesystem: ${fstype:-unknown}) — swap file removed, fstab untouched."
    rm -f "$swapfile"
    return 1
  fi

  if ! grep -qE '^[[:space:]]*/swapfile[[:space:]]' /etc/fstab 2>/dev/null; then
    printf '/swapfile none swap sw 0 0\n' >>/etc/fstab
  fi
  log_info "Swap file enabled: ${size_mb} MB (fs: ${fstype:-unknown})."
  return 0
}

# _swap_zram_setup SIZE_MB — compressed swap in RAM, priority above any
# future disk swap. Boot persistence via a oneshot unit (nothing resident).
_swap_zram_setup() {
  local size_mb="$1"
  ((size_mb < 256)) && size_mb=256
  ((size_mb > 4096)) && size_mb=4096

  if ! modprobe zram 2>>"$ST_LOG_FILE" || [[ ! -b /dev/zram0 ]]; then
    log_error "zram kernel module unavailable on this system."
    return 1
  fi
  # lz4 beats the default algorithm on weak vCPUs; not fatal when missing.
  echo lz4 >/sys/block/zram0/comp_algorithm 2>/dev/null || true
  if ! echo "${size_mb}M" >/sys/block/zram0/disksize 2>>"$ST_LOG_FILE"; then
    log_error "Could not size /dev/zram0."
    return 1
  fi
  mkswap /dev/zram0 >/dev/null 2>>"$ST_LOG_FILE" || return 1
  if ! swapon -p 100 /dev/zram0 2>>"$ST_LOG_FILE"; then
    log_error "swapon on /dev/zram0 failed."
    return 1
  fi

  if [[ -d /etc/systemd/system ]] && has_cmd systemctl; then
    st_track_file "$ST_ZRAM_UNIT"
    cat >"$ST_ZRAM_UNIT" <<EOF
# Generated by ${ST_NAME} v${ST_VERSION}
[Unit]
Description=ServerTools zram swap (oneshot, exits after boot)

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/bin/bash -c 'modprobe zram && { echo lz4 > /sys/block/zram0/comp_algorithm 2>/dev/null; true; } && echo ${size_mb}M > /sys/block/zram0/disksize && mkswap /dev/zram0 && swapon -p 100 /dev/zram0'
ExecStop=/bin/bash -c 'swapoff /dev/zram0 && echo 1 > /sys/block/zram0/reset'

[Install]
WantedBy=multi-user.target
EOF
    systemctl daemon-reload 2>>"$ST_LOG_FILE" || log_warn "daemon-reload failed."
    if systemctl enable server-tools-zram.service >/dev/null 2>>"$ST_LOG_FILE"; then
      manifest_add unit server-tools-zram.service
    else
      log_warn "Could not enable zram boot persistence — active now, gone after reboot."
    fi
  else
    log_warn "No systemd — zram swap is active now but will not survive a reboot."
  fi

  log_info "zram swap enabled: ${size_mb} MB compressed (priority 100)."
  return 0
}

swap_apply() {
  if swap_is_active; then
    log_info "Swap already active — skipped."
    return 2
  fi

  local backend size_mb ram_mb avail_mb disk_ok=0
  backend="$(config_get swap_backend auto)"
  size_mb="$(config_get swap_size_mb 2048)"
  [[ $size_mb =~ ^[0-9]+$ ]] || size_mb=2048
  ram_mb="$(mem_total_mb)"

  # Disk headroom check: swap size + 1 GB safety margin.
  avail_mb="$(df -Pm / 2>/dev/null | awk 'NR == 2 {print $4}')" || avail_mb=0
  [[ $avail_mb =~ ^[0-9]+$ ]] || avail_mb=0
  ((avail_mb >= size_mb + 1024)) && disk_ok=1

  case "$backend" in
    file)
      if ((disk_ok == 0)); then
        log_error "Not enough free disk for a ${size_mb} MB swap file (available: ${avail_mb} MB)."
        return 1
      fi
      _swap_file_setup "$size_mb"
      ;;
    zram)
      _swap_zram_setup "$((ram_mb / 2))"
      ;;
    *) # auto — real disk capacity first, compressed RAM as the fallback.
      if ((disk_ok)); then
        _swap_file_setup "$size_mb"
      else
        log_warn "Disk too small for a swap file — using zram (compressed RAM) instead."
        _swap_zram_setup "$((ram_mb / 2))"
      fi
      ;;
  esac
}

# ------------------------- src/modules/limits.sh -------------------------
# ============================================================================
# modules/limits.sh — file-descriptor limits for 100k+ concurrent sockets.
# Uses a systemd drop-in instead of sed-editing system.conf, so rollback is
# a clean file removal (legacy v1 mutated /etc/systemd/system.conf in place).
# ============================================================================

readonly ST_LIMITS_FILE='/etc/security/limits.d/99-server-tools.conf'
readonly ST_SYSTEMD_DROPIN='/etc/systemd/system.conf.d/99-server-tools.conf'

# Set when limits were (re)written this run — running services keep their
# old nofile until restarted, so the optimizer offers a restart afterwards.
ST_LIMITS_CHANGED=0

limits_apply() {
  ST_LIMITS_CHANGED=1
  st_track_file "$ST_LIMITS_FILE"
  mkdir -p "$(dirname "$ST_LIMITS_FILE")"
  cat >"$ST_LIMITS_FILE" <<EOF
# Generated by ${ST_NAME} v${ST_VERSION}
* soft nofile 1048576
* hard nofile 1048576
root soft nofile 1048576
root hard nofile 1048576
EOF

  if [[ -d /etc/systemd ]]; then
    st_track_file "$ST_SYSTEMD_DROPIN"
    mkdir -p "$(dirname "$ST_SYSTEMD_DROPIN")"
    cat >"$ST_SYSTEMD_DROPIN" <<EOF
# Generated by ${ST_NAME} v${ST_VERSION}
[Manager]
DefaultLimitNOFILE=1048576
EOF
    if has_cmd systemctl && ! systemctl daemon-reexec 2>>"$ST_LOG_FILE"; then
      log_warn "systemd daemon-reexec failed — new limits take effect after reboot."
      return 3
    fi
  fi

  log_info "nofile limits set to 1048576 (PAM + systemd drop-in)."
  return 0
}

# limits_verify — 0 when the systemd manager default is already raised.
limits_verify() {
  [[ -f $ST_LIMITS_FILE ]] || return 2
  has_cmd systemctl || return 0
  local current
  current="$(systemctl show -p DefaultLimitNOFILE --value 2>/dev/null)" || current=''
  [[ $current =~ ^[0-9]+$ ]] || return 3
  ((current >= 1048576)) && return 0
  return 3
}

# limits_docker_ulimits — containers inherit their file limit from the
# container engine, never from limits.d. Editing an existing daemon.json
# safely needs a JSON parser we cannot depend on, so an existing file is
# only reported: printing the exact snippet is better than corrupting it.
limits_docker_ulimits() {
  local daemon='/etc/docker/daemon.json'
  ui_section "Docker container file limits"
  if ! has_cmd docker; then
    printf 'Docker is not installed on this server.\n'
    return 2
  fi

  if [[ -f $daemon ]]; then
    if grep -q 'default-ulimits' "$daemon" 2>/dev/null; then
      printf '%sAlready configured%s in %s.\n' "$C_OK" "$C_RESET" "$daemon"
      return 0
    fi
    printf '%s exists and cannot be edited safely without a JSON parser.\n' "$daemon"
    printf 'Add this block yourself, then run: systemctl restart docker\n\n'
    printf '  "default-ulimits": { "nofile": { "Name": "nofile", "Soft": 1048576, "Hard": 1048576 } }\n\n'
    return 3
  fi

  printf 'Creating %s with a raised nofile limit for all containers.\n' "$daemon"
  printf '%sRestarting Docker briefly interrupts every container on this host.%s\n' "$C_WARN" "$C_RESET"
  ui_confirm "Write the file and restart Docker now?" || return 2

  st_track_file "$daemon"
  mkdir -p "$(dirname "$daemon")"
  cat >"$daemon" <<'EOF'
{
  "default-ulimits": {
    "nofile": { "Name": "nofile", "Soft": 1048576, "Hard": 1048576 }
  }
}
EOF
  if has_cmd systemctl && systemctl restart docker 2>>"$ST_LOG_FILE"; then
    printf '%sDone.%s Containers started from now on get nofile=1048576.\n' "$C_OK" "$C_RESET"
    log_info "docker daemon.json default-ulimits applied."
    return 0
  fi
  log_error "Docker restart failed — check the log; daemon.json is tracked for rollback."
  return 1
}

# ------------------------- src/modules/extras.sh -------------------------
# ============================================================================
# modules/extras.sh — base-layer hygiene: journald disk cap and NTP sync.
# Small-disk VPSes fill up with journal logs; Reality/TLS handshakes need
# an accurate clock.
# ============================================================================

readonly ST_JOURNALD_DROPIN='/etc/systemd/journald.conf.d/99-server-tools.conf'

extras_apply() {
  local rc=0 did_anything=0

  if [[ -d /etc/systemd ]]; then
    st_track_file "$ST_JOURNALD_DROPIN"
    mkdir -p "$(dirname "$ST_JOURNALD_DROPIN")"
    cat >"$ST_JOURNALD_DROPIN" <<EOF
# Generated by ${ST_NAME} v${ST_VERSION}
[Journal]
SystemMaxUse=100M
RuntimeMaxUse=50M
EOF
    if has_cmd systemctl; then
      systemctl restart systemd-journald 2>>"$ST_LOG_FILE" ||
        log_warn "journald restart failed — the disk cap applies after next boot."
    fi
    did_anything=1
  fi

  if has_cmd timedatectl; then
    if ! timedatectl set-ntp true 2>>"$ST_LOG_FILE"; then
      log_warn "Could not enable NTP via timedatectl."
      rc=3
    fi
    did_anything=1
  fi

  ((did_anything)) || return 2
  return "$rc"
}

# ------------------------- src/modules/perf.sh -------------------------
# ============================================================================
# modules/perf.sh — CPU/NIC data-path tuning that lives in /sys, not sysctl.
#
# Three wins that /etc/sysctl.d cannot express, all zero-footprint:
#   - RPS/RFS/XPS: spread NIC softirq processing across every core. Decisive
#     on the single-queue virtio NICs most VPS ship — one core otherwise caps
#     the whole node's packet rate. Skipped when the NIC already has as many
#     hardware queues as cores (RSS already spreads the load).
#   - CPU governor = performance: no ramp-up latency on bursty proxy traffic.
#     Silently skipped where cpufreq is absent (typical virtualised host).
#   - Transparent Huge Pages = madvise: stops khugepaged compaction stalls
#     from adding tail-latency spikes, without denying THP to code that asks.
#
# These settings do not survive a reboot on their own, so they are persisted
# through ONE oneshot systemd unit that runs a generated, idempotent boot
# script and exits — no resident process (CLAUDE.md rule 1). NIC ring/coalesce
# tuning (ethtool -G) is deliberately excluded: it can reset the link and
# harms latency on many hypervisors (see docs/SYSCTL.md "Deliberately NOT set").
# ============================================================================

readonly ST_PERF_BOOT='/etc/server-tools/perf-boot.sh'
readonly ST_PERF_UNIT='/etc/systemd/system/server-tools-perf.service'

# _perf_cpu_mask CORES — the kernel rps_cpus/xps_cpus bitmask covering CORES
# online CPUs: comma-separated 32-bit hex words, most-significant first
# (e.g. 4 -> "0000000f", 40 -> "000000ff,ffffffff"). Capped at 64 cores.
_perf_cpu_mask() {
  local cores="$1"
  ((cores > 64)) && cores=64
  # Two-step arithmetic throughout: nested parens inside $(( )) get normalised
  # to a triple-paren form that ShellCheck then misreads as $( (subshell) ).
  local i bits word mask='' groups
  groups=$((cores + 31))
  groups=$((groups / 32))
  for ((i = groups - 1; i >= 0; i--)); do
    bits=$((cores - i * 32))
    ((bits > 32)) && bits=32
    if ((bits >= 32)); then
      word=4294967295 # 0xffffffff — a full 32-bit group
    else
      word=$((1 << bits))
      word=$((word - 1))
    fi
    mask+="$(printf '%08x' "$word")"
    ((i > 0)) && mask+=','
  done
  printf '%s' "$mask"
}

# _perf_rps_beneficial IFACE CORES — RPS helps only when the NIC spreads
# traffic across fewer hardware queues than we have cores to steer it onto.
_perf_rps_beneficial() {
  local iface="$1" cores="$2" mode nq
  mode="$(config_get rps_mode auto)"
  case "$mode" in
    on) return 0 ;;
    off) return 1 ;;
  esac
  ((cores > 1)) || return 1
  [[ -n $iface && -d /sys/class/net/$iface/queues ]] || return 1
  nq="$(find "/sys/class/net/${iface}/queues" -maxdepth 1 -name 'rx-*' -type d 2>/dev/null | wc -l)"
  [[ $nq =~ ^[0-9]+$ ]] || return 1
  ((nq < cores))
}

# _perf_plan IFACE MASK — emit "path<TAB>value" for every /sys tweak that
# applies on THIS host. Single source of truth for both live-apply and the
# persisted boot script; only writable targets are listed.
_perf_plan() {
  local iface="$1" mask="$2" g q
  for g in /sys/devices/system/cpu/cpu*/cpufreq/scaling_governor; do
    [[ -w $g ]] && printf '%s\t%s\n' "$g" performance
  done
  [[ -w /sys/kernel/mm/transparent_hugepage/enabled ]] &&
    printf '%s\t%s\n' /sys/kernel/mm/transparent_hugepage/enabled madvise
  [[ -w /sys/kernel/mm/transparent_hugepage/defrag ]] &&
    printf '%s\t%s\n' /sys/kernel/mm/transparent_hugepage/defrag madvise
  if [[ -n $iface && -n $mask ]]; then
    # RFS global flow table; per-queue counts complete the RFS hash.
    [[ -w /proc/sys/net/core/rps_sock_flow_entries ]] &&
      printf '%s\t%s\n' /proc/sys/net/core/rps_sock_flow_entries 32768
    for q in /sys/class/net/"$iface"/queues/rx-*; do
      [[ -w $q/rps_cpus ]] && printf '%s\t%s\n' "$q/rps_cpus" "$mask"
      [[ -w $q/rps_flow_cnt ]] && printf '%s\t%s\n' "$q/rps_flow_cnt" 4096
    done
    for q in /sys/class/net/"$iface"/queues/tx-*; do
      [[ -w $q/xps_cpus ]] && printf '%s\t%s\n' "$q/xps_cpus" "$mask"
    done
  fi
  # Value-producing helper: never leak the exit status of a trailing loop/guard
  # into the bare `plan="$(_perf_plan …)"` capture under errexit. On a host with
  # a read-only /sys (unprivileged LXC) every -w test above is false and the
  # plan is simply empty — the caller then skips the step cleanly.
  return 0
}

# _perf_write_boot PLAN — a self-contained, idempotent boot script (each write
# tolerant) plus the oneshot unit that runs it. Both are tracked for rollback.
_perf_write_boot() {
  local plan="$1" path value
  st_track_file "$ST_PERF_BOOT"
  mkdir -p "$(dirname "$ST_PERF_BOOT")"
  {
    printf '#!/usr/bin/env bash\n'
    printf '# Generated by %s v%s — reapplies non-persistent /sys tuning at boot.\n' "$ST_NAME" "$ST_VERSION"
    printf '# RPS/RFS/XPS, CPU governor, THP. Idempotent; safe to run repeatedly.\n'
    printf 'set -u\n'
    while IFS=$'\t' read -r path value; do
      [[ -n $path ]] || continue
      printf 'printf %%s %s > %s 2>/dev/null || true\n' "$value" "$path"
    done <<<"$plan"
  } >"$ST_PERF_BOOT"
  chmod 0755 "$ST_PERF_BOOT"

  st_track_file "$ST_PERF_UNIT"
  mkdir -p "$(dirname "$ST_PERF_UNIT")"
  {
    printf '# Generated by %s v%s\n' "$ST_NAME" "$ST_VERSION"
    printf '[Unit]\nDescription=ServerTools CPU/NIC performance tuning (oneshot, exits after boot)\n'
    printf 'After=network-online.target\nWants=network-online.target\n\n'
    printf '[Service]\nType=oneshot\nRemainAfterExit=yes\n'
    printf 'ExecStart=%s\n' "$ST_PERF_BOOT"
    printf '\n[Install]\nWantedBy=multi-user.target\n'
  } >"$ST_PERF_UNIT"
}

# perf_apply — Quick/Custom Optimize step. 0=applied, 2=nothing applicable,
# 3=applied but some targets were read-only.
perf_apply() {
  local cores iface mask='' rps=0
  cores="$(cpu_cores)"
  [[ $cores =~ ^[0-9]+$ ]] || cores=1
  iface="$(net_default_iface)" || iface=''
  if _perf_rps_beneficial "$iface" "$cores"; then
    mask="$(_perf_cpu_mask "$cores")"
    rps=1
  fi

  local plan
  plan="$(_perf_plan "$iface" "$mask")"
  if [[ -z $plan ]]; then
    log_info "perf: nothing applicable (no cpufreq, THP or RPS on this host)."
    return 2
  fi

  local path value applied=0 unavail=0
  while IFS=$'\t' read -r path value; do
    [[ -n $path ]] || continue
    if printf '%s\n' "$value" >"$path" 2>>"$ST_LOG_FILE"; then
      applied=$((applied + 1))
    else
      unavail=$((unavail + 1))
    fi
  done <<<"$plan"

  local rc=0
  if [[ -d /etc/systemd/system ]] && has_cmd systemctl; then
    _perf_write_boot "$plan"
    if ! systemctl daemon-reload 2>>"$ST_LOG_FILE"; then
      log_warn "systemd daemon-reload failed — the unit is written but not loaded (needs a manual reload or reboot)."
      rc=3
    fi
    if systemctl enable server-tools-perf.service >/dev/null 2>>"$ST_LOG_FILE"; then
      manifest_add unit server-tools-perf.service
    else
      log_warn "Could not enable boot persistence for the performance tuning."
      rc=3
    fi
  else
    log_warn "No systemd — performance tuning is active now but will not survive a reboot."
    rc=3
  fi

  if ((rps)); then
    log_note "RPS/RFS/XPS spread across ${cores} core(s) on ${iface} (single/low-queue NIC)."
  elif [[ -n $iface ]]; then
    log_note "RPS skipped — ${iface} already has enough hardware queues."
  fi
  if ((unavail > 0)); then
    log_note "${unavail} target(s) were read-only and left as-is."
    ((rc == 0)) && rc=3
  fi

  log_info "perf applied: applied=${applied} unavail=${unavail} rps=${rps} cores=${cores} iface=${iface:-none}."
  return "$rc"
}

# perf_verify — 0 when every setting the boot script manages is still live,
# 3 on drift, 2 when performance tuning was never configured here.
perf_verify() {
  [[ -f $ST_PERF_BOOT ]] || return 2
  local line value path cur drift=0
  while IFS= read -r line; do
    [[ $line == printf* ]] || continue
    # printf %s VALUE > PATH 2>/dev/null || true
    value="$(awk '{print $3}' <<<"$line")"
    path="$(awk '{print $5}' <<<"$line")"
    [[ -n $path && -r $path ]] || continue
    cur="$(cat "$path" 2>/dev/null)" || continue
    case "$path" in
      *transparent_hugepage*)
        [[ $cur == *"[$value]"* ]] || drift=1
        ;;
      *rps_cpus | *xps_cpus)
        # The kernel reformats the mask; a non-zero read means RPS is active.
        [[ -n ${cur//[,0]/} ]] || drift=1
        ;;
      *)
        [[ $cur == "$value" ]] || drift=1
        ;;
    esac
  done <"$ST_PERF_BOOT"
  ((drift)) && return 3
  return 0
}

# ------------------------- src/modules/security.sh -------------------------
# ============================================================================
# modules/security.sh — Layer 3 optional hardening: UFW, fail2ban, SSH.
#
# Everything here is consent-based (CLAUDE.md rule 1). fail2ban is the only
# resident service in the whole project and its cost is stated before the
# user agrees. The SSH allow rule always lands before any deny rule, and the
# sshd drop-in is validated with `sshd -t` before restart — no lockouts.
# ============================================================================

readonly ST_F2B_JAIL='/etc/fail2ban/jail.d/99-server-tools.local'
# sshd applies the FIRST value it sees for a keyword and reads the drop-in
# directory in lexical order, so a 99- file loses against the cloud-init
# 50-cloud-init.conf that ships with most images. 00- wins.
readonly ST_SSHD_DROPIN='/etc/ssh/sshd_config.d/00-server-tools.conf'
readonly ST_SSHD_DROPIN_LEGACY='/etc/ssh/sshd_config.d/99-server-tools.conf'

# detect_ssh_port — the port sshd really listens on. `sshd -T` is the only
# source that accounts for drop-ins; the config file and `ss` are fallbacks.
# Nothing is parsed through a pipe: an early-exiting awk would SIGPIPE the
# producer and pipefail would then discard a perfectly good answer — and
# guessing 22 here could lock the user out through the firewall rules.
detect_ssh_port() {
  local port='' out=''
  if has_cmd sshd; then
    out="$(sshd -T 2>/dev/null)" || out=''
    [[ -n $out ]] && port="$(awk '$1 == "port" {print $2; exit}' <<<"$out")"
  fi
  if [[ -z $port ]]; then
    port="$(awk '/^[[:space:]]*[Pp]ort[[:space:]]/ {print $2; exit}' /etc/ssh/sshd_config 2>/dev/null)" || port=''
  fi
  if [[ -z $port ]] && has_cmd ss; then
    out="$(ss -tnlp 2>/dev/null)" || out=''
    [[ -n $out ]] && port="$(awk '/sshd/ {sub(/.*:/, "", $4); print $4; exit}' <<<"$out")"
  fi
  [[ $port =~ ^[0-9]+$ ]] || port=22
  printf '%s' "$port"
}

# _ssh_session_port — the server-side port of the SSH session running this
# tool (from SSH_CONNECTION), empty when not run over SSH. It can differ from
# the configured port (NAT, port forwarding), and blocking it drops the user.
_ssh_session_port() {
  local port
  port="$(awk '{print $4}' <<<"${SSH_CONNECTION:-}")"
  [[ $port =~ ^[0-9]+$ ]] && printf '%s' "$port"
  return 0
}

security_ufw() {
  ui_section "UFW firewall"
  if ! has_cmd ufw; then
    ui_confirm "UFW is not installed. Install it now?" || return 0
    if ! pkg_install ufw; then
      log_error "UFW installation failed — see the log."
      return 0
    fi
  fi

  local ssh_port
  ssh_port="$(detect_ssh_port)"
  printf 'Detected SSH port: %s — it is allowed FIRST, so you cannot be locked out.\n' "$ssh_port"
  if ! ufw allow "${ssh_port}/tcp" >/dev/null 2>>"$ST_LOG_FILE"; then
    log_error "Could not add the SSH allow rule — aborting before any deny rule."
    return 0
  fi
  # Safety net 1: the port THIS session arrived on is always allowed too.
  local session_port
  session_port="$(_ssh_session_port)"
  if [[ -n $session_port && $session_port != "$ssh_port" ]]; then
    printf '%sYou are connected through port %s (sshd listens on %s) — allowing both.%s\n' \
      "$C_WARN" "$session_port" "$ssh_port" "$C_RESET"
    ufw allow "${session_port}/tcp" >/dev/null 2>>"$ST_LOG_FILE" ||
      log_warn "Could not allow your current session port ${session_port}."
  fi
  ufw default deny incoming >/dev/null 2>>"$ST_LOG_FILE" || log_warn "Could not set default deny incoming."
  ufw default allow outgoing >/dev/null 2>>"$ST_LOG_FILE" || log_warn "Could not set default allow outgoing."

  local ports p
  read -rp "Extra ports to allow (e.g. 443/tcp 80/tcp 51820/udp) [Enter=none]: " ports || ports=''
  if [[ -n $ports ]]; then
    local IFS=' ' # the global IFS has no space — restore word splitting here
    for p in $ports; do
      if [[ $p =~ ^[0-9]+(/(tcp|udp))?$ ]]; then
        ufw allow "$p" >/dev/null 2>>"$ST_LOG_FILE" || log_warn "Rule failed: ${p}"
      else
        log_warn "Skipped invalid port spec: ${p}"
      fi
    done
  fi

  # Safety net 2: services that listen publicly right now would go dark the
  # moment UFW denies by default. Show them and offer to keep them open.
  local open_ports='' lp
  while IFS= read -r lp; do
    [[ $lp =~ ^[0-9]+$ ]] || continue
    ufw status 2>/dev/null | grep -qE "^${lp}(/| )" && continue
    [[ $lp == "$ssh_port" || $lp == "$session_port" ]] && continue
    open_ports+="${lp} "
  done < <(listening_service_ports)
  if [[ -n $open_ports ]]; then
    printf '%sThese ports are serving clients right now but have no allow rule:%s %s\n' \
      "$C_WARN" "$C_RESET" "$open_ports"
    printf 'Enabling UFW without them would cut your users off.\n'
    if ui_confirm_yes "Allow them (tcp+udp) so nothing breaks?"; then
      for lp in $open_ports; do
        ufw allow "$lp" >/dev/null 2>>"$ST_LOG_FILE" || log_warn "Rule failed: ${lp}"
      done
    fi
  fi

  if has_cmd docker && docker ps -q 2>/dev/null | grep -q .; then
    printf '%sWarning:%s Docker publishes container ports directly in iptables and\n' "$C_WARN" "$C_RESET"
    printf 'BYPASSES UFW — published panel/node ports stay reachable regardless of\n'
    printf 'these rules (see Network tools > Docker+UFW audit).\n'
  fi

  if ui_confirm "Enable UFW now?"; then
    if ufw --force enable >/dev/null 2>>"$ST_LOG_FILE"; then
      printf '%sUFW enabled.%s\n' "$C_OK" "$C_RESET"
      ufw status verbose 2>/dev/null || log_warn "Could not print UFW status."
    else
      log_error "Enabling UFW failed — see the log."
      return 0
    fi
  fi
  printf '%sNote:%s firewall state is not covered by manifest rollback — revert with: ufw disable\n' \
    "$C_MUTED" "$C_RESET"
  log_info "UFW configured (SSH ${ssh_port}/tcp allowed)."
}

security_fail2ban() {
  ui_section "fail2ban (SSH brute-force protection)"
  printf 'fail2ban runs as a small resident service (~20 MB RAM) — the only\n'
  printf 'exception to the zero-footprint rule, and only with your consent.\n'
  ui_confirm "Install and enable fail2ban?" || return 0

  if ! has_cmd fail2ban-server && ! pkg_install fail2ban; then
    log_error "fail2ban installation failed — see the log."
    return 0
  fi

  local ssh_port
  ssh_port="$(detect_ssh_port)"
  st_track_file "$ST_F2B_JAIL"
  mkdir -p "$(dirname "$ST_F2B_JAIL")"
  cat >"$ST_F2B_JAIL" <<EOF
# Generated by ${ST_NAME} v${ST_VERSION}
[sshd]
enabled = true
port = ${ssh_port}
backend = systemd
maxretry = 5
findtime = 10m
bantime = 1h
EOF

  if has_cmd systemctl &&
    systemctl enable fail2ban >/dev/null 2>>"$ST_LOG_FILE" &&
    systemctl restart fail2ban 2>>"$ST_LOG_FILE"; then
    printf '%sfail2ban active%s (sshd jail on port %s, ban 1h after 5 tries).\n' \
      "$C_OK" "$C_RESET" "$ssh_port"
    log_info "fail2ban enabled (sshd jail, port ${ssh_port})."
  else
    log_error "fail2ban could not be enabled — see the log."
  fi
}

security_ssh() {
  ui_section "SSH hardening"
  if [[ ! -d /etc/ssh/sshd_config.d ]]; then
    log_warn "This system has no /etc/ssh/sshd_config.d — skipping (editing sshd_config in place is not safe enough)."
    return 0
  fi

  local lines=('UseDNS no')
  if [[ -s /root/.ssh/authorized_keys ]]; then
    printf 'An SSH key for root exists.\n'
    printf '%sVerify key login works in a second terminal BEFORE confirming.%s\n' "$C_WARN" "$C_RESET"
    printf 'Typing KEY-OK below means you tested it. Anything else keeps passwords on.
'
    local ack
    read -rp "Disable password authentication? [KEY-OK / Enter=no]: " ack || ack=''
    if [[ $ack == KEY-OK ]]; then
      lines+=('PasswordAuthentication no')
    fi
  else
    printf '%sNo /root/.ssh/authorized_keys found — password login stays enabled.%s\n' "$C_WARN" "$C_RESET"
  fi

  # A drop-in from an older version sorts after cloud-init and would keep
  # losing; remove it so only the winning file remains.
  if [[ -f $ST_SSHD_DROPIN_LEGACY ]]; then
    st_track_file "$ST_SSHD_DROPIN_LEGACY"
    rm -f "$ST_SSHD_DROPIN_LEGACY"
    log_info "Removed the superseded 99- SSH drop-in."
  fi

  st_track_file "$ST_SSHD_DROPIN"
  {
    printf '# Generated by %s v%s\n' "$ST_NAME" "$ST_VERSION"
    printf '%s\n' "${lines[@]}"
  } >"$ST_SSHD_DROPIN"

  if has_cmd sshd && ! sshd -t 2>>"$ST_LOG_FILE"; then
    rm -f "$ST_SSHD_DROPIN"
    log_error "sshd config validation failed — drop-in removed, nothing changed."
    return 1
  fi
  if has_cmd systemctl; then
    # Service name differs across distros (ssh on Debian/Ubuntu, sshd elsewhere).
    systemctl restart ssh 2>/dev/null || systemctl restart sshd 2>>"$ST_LOG_FILE" ||
      log_warn "Could not restart sshd — settings apply on its next restart."
  fi

  # Verify against the effective configuration, not the file we wrote.
  local effective
  for effective in "${lines[@]}"; do
    ssh_effective_matches "$effective" || {
      log_warn "SSH setting '${effective}' is NOT in effect — another drop-in overrides it (check: sshd -T)."
      printf '%sWarning:%s "%s" did not take effect — see the log.\n' "$C_WARN" "$C_RESET" "$effective"
      return 3
    }
  done

  # "${lines[*]}" would join with the global IFS's newline and break this into
  # one line per setting; the entries contain spaces, so join with ", ".
  local summary
  summary="$(
    IFS=', '
    printf '%s' "${lines[*]}"
  )"
  printf '%sApplied and verified:%s %s\n' "$C_OK" "$C_RESET" "$summary"
  log_info "SSH hardening drop-in applied and verified: ${summary}"
  return 0
}

# ssh_effective_matches "Keyword value" — is that what sshd really uses?
ssh_effective_matches() {
  has_cmd sshd || return 0 # cannot check; do not claim failure
  local keyword value actual
  keyword="${1%% *}"
  value="${1#* }"
  actual="$(sshd -T 2>/dev/null | awk -v k="${keyword,,}" '$1 == k {print $2; exit}')" || actual=''
  [[ -z $actual ]] && return 0 # keyword unknown to this sshd build
  [[ ${actual,,} == "${value,,}" ]]
}

# ssh_verify — 0 when our drop-in exists and its settings are in effect.
ssh_verify() {
  [[ -f $ST_SSHD_DROPIN ]] || return 2
  local line
  while IFS= read -r line; do
    [[ -z $line || $line == \#* ]] && continue
    ssh_effective_matches "$line" || return 3
  done <"$ST_SSHD_DROPIN"
  return 0
}

# security_node_ports — a node's API port only ever talks to its panel.
security_node_api() {
  ui_section "Restrict node API ports to the panel"
  if ! has_cmd ufw; then
    log_error "UFW is not installed — set it up first (menu option 1)."
    return 2
  fi
  printf 'Marzban-node uses 62050/62051, pg-node 62050 by default. Leaving them\n'
  printf 'open to the internet exposes the service to every scanner.\n'
  local panel_ip ports port
  read -rp "Panel IP address (empty = cancel): " panel_ip || return 2
  [[ -n $panel_ip ]] || return 2
  if ! is_valid_ip "$panel_ip"; then
    log_error "'${panel_ip}' is not a valid IP address."
    return 1
  fi
  read -rp "API ports [62050,62051]: " ports || ports=''
  ports="${ports:-62050,62051}"

  local rc=0
  while IFS= read -r port; do
    [[ $port =~ ^[0-9]+$ ]] || {
      log_warn "Skipped invalid port '${port}'."
      continue
    }
    ufw delete allow "${port}/tcp" >/dev/null 2>&1 || true # rule may simply not exist
    if ufw allow from "$panel_ip" to any port "$port" proto tcp >/dev/null 2>>"$ST_LOG_FILE"; then
      printf '  %s/tcp: only %s\n' "$port" "$panel_ip"
    else
      log_warn "Could not restrict port ${port}."
      rc=3
    fi
  done < <(ports_split "$ports")
  log_info "Node API ports restricted to ${panel_ip} (rc=${rc})."
  return "$rc"
}

security_menu() {
  local choice
  while true; do
    ui_logo
    ui_title "Security (Layer 3 — optional, consent-based)"
    ui_menu_item 1 "UFW firewall" "SSH-safe setup, extra ports, Docker warning"
    ui_menu_item 2 "fail2ban" "SSH brute-force bans (resident service ~20 MB)"
    ui_menu_item 3 "SSH hardening" "UseDNS off, optional key-only login (validated)"
    ui_menu_item 4 "Restrict node API" "panel-only access to 62050/62051"
    ui_menu_item 0 "Back"
    read -rp "$(_ui_prompt)" choice || return 0
    case "${choice:-}" in
      1)
        security_ufw
        ui_pause
        ;;
      2)
        security_fail2ban
        ui_pause
        ;;
      3)
        security_ssh || true # outcome already reported to the user
        ui_pause
        ;;
      4)
        security_node_api || true
        ui_pause
        ;;
      0) return 0 ;;
      *)
        printf '%sInvalid choice.%s\n' "$C_ERR" "$C_RESET"
        sleep 1
        ;;
    esac
  done
}

# ------------------------- src/modules/vpn.sh -------------------------
# ============================================================================
# modules/vpn.sh — VPN-aware non-sysctl fixes.
#
# Smart MTU/MSS: measures the real path MTU, then clamps MSS to it. A clamp is
# the most common fix for "WireGuard connects but pages
# don't load" behind NAT. Persistence uses a systemd ONESHOT unit: it runs
# once at boot and exits — no resident process, zero-footprint compliant.
# ============================================================================

readonly ST_MSS_UNIT='/etc/systemd/system/server-tools-mss.service'
readonly ST_MSS_UFW_MARK='# --- server-tools MSS clamping'

# _mss_rule FAMILY — the TCPMSS rule words for this host. A configured
# mss_value (measured path MTU − headers) wins over --clamp-mss-to-pmtu, which
# only knows the INTERFACE mtu and so does nothing when the real bottleneck is
# further along the path (tunnels, provider overlay, PPPoE).
# FAMILY is 4 or 6; the headers are 40 and 60 bytes. The value stored in
# config is the IPv4 MSS, so IPv6 subtracts 20 more.
_mss_rule() {
  local family="$1" value
  value="$(config_get mss_value 0)"
  [[ $value =~ ^[0-9]+$ ]] || value=0
  if ((value > 0)); then
    ((family == 6)) && value=$((value - 20))
    printf '%s\n' FORWARD -p tcp --tcp-flags 'SYN,RST' SYN -j TCPMSS --set-mss "$value"
  else
    printf '%s\n' FORWARD -p tcp --tcp-flags 'SYN,RST' SYN -j TCPMSS --clamp-mss-to-pmtu
  fi
}

# _mss_rule_words FAMILY — the rule as one space-joined string.
_mss_rule_words() {
  local -a words
  mapfile -t words < <(_mss_rule "$1")
  join_sp "${words[@]}"
}

# _mss_remove_live TOOL — delete every TCPMSS rule in FORWARD so a changed
# value replaces the old rule instead of stacking beside it.
_mss_remove_live() {
  local tool="$1" rule
  while IFS= read -r rule; do
    [[ $rule == -A\ FORWARD* ]] || continue
    # shellcheck disable=SC2086 # rule words are iptables syntax by design
    "$tool" -t mangle ${rule/-A /-D } 2>>"$ST_LOG_FILE" ||
      log_warn "Could not remove an old MSS rule from ${tool}."
  done < <("$tool" -t mangle -S FORWARD 2>/dev/null | grep -- '-j TCPMSS' || true) # no match is normal
}

# _mss_ufw_strip — remove our managed block from before.rules.
_mss_ufw_strip() {
  local rules="$1" tmp="${1}.st-tmp"
  awk -v mark="$ST_MSS_UFW_MARK" '
    index($0, mark) == 1 {skip = 1}
    skip {if ($0 == "COMMIT") {skip = 0}; next}
    {print}
  ' "$rules" >"$tmp" && cat "$tmp" >"$rules"
  rm -f "$tmp"
}

# _vpn_mss_ufw_persist — add the clamp to UFW's before.rules so `ufw reload`
# keeps it. The file is tracked first and restored if UFW refuses to reload.
_vpn_mss_ufw_persist() {
  local rules='/etc/ufw/before.rules' rule
  has_cmd ufw || return 2
  [[ -f $rules ]] || return 2
  rule="$(_mss_rule_words 4)"
  # Idempotent: the same rule already in place means nothing to do.
  grep -qF -- "-A ${rule}" "$rules" 2>/dev/null && return 0

  st_track_file "$rules"
  _mss_ufw_strip "$rules"
  cat >>"$rules" <<EOF

${ST_MSS_UFW_MARK} (managed block, safe to remove as a whole)
*mangle
:FORWARD - [0:0]
-A ${rule}
COMMIT
EOF

  if ufw status 2>/dev/null | grep -q '^Status: active'; then
    if ! ufw reload >/dev/null 2>>"$ST_LOG_FILE"; then
      cp -a "${ST_RUN_BACKUP_DIR}${rules}" "$rules"
      log_warn "UFW rejected the before.rules change — reverted; the clamp survives only until the next ufw reload."
      return 3
    fi
  fi
  log_info "MSS clamp persisted in ${rules}."
  return 0
}

# --- Path MTU measurement ---------------------------------------------------

# Public anycast resolvers answer ICMP everywhere and sit behind the same
# international path real users' traffic takes.
readonly -a ST_PMTU_TARGETS=(1.1.1.1 8.8.8.8)

# _pmtu_probe TARGET — largest IPv4 packet that crosses unfragmented, found by
# binary search with DF-flagged pings. Prints nothing and fails when the target
# does not answer a small ping or the ping tool lacks -M do.
_pmtu_probe() {
  local target="$1" lo=1200 hi=1500 mid
  has_cmd ping || return 1
  ping -c1 -W2 -s 56 "$target" >/dev/null 2>&1 || return 1
  ping -M "do" -c1 -W1 -s $((lo - 28)) "$target" >/dev/null 2>&1 || return 1
  while ((lo < hi)); do
    mid=$(((lo + hi + 1) / 2))
    if ping -M "do" -c1 -W1 -s $((mid - 28)) "$target" >/dev/null 2>&1; then
      lo=$mid
    else
      hi=$((mid - 1))
    fi
  done
  printf '%s' "$lo"
}

# Lowest measured path MTU (0 = unknown) and the default interface's MTU.
ST_PMTU=0
ST_IFACE_MTU=0

# vpn_measure_mtu — fill ST_PMTU and ST_IFACE_MTU and print the evidence.
vpn_measure_mtu() {
  ST_PMTU=0
  ST_IFACE_MTU=0
  local iface target value
  iface="$(net_default_iface)" || iface=''
  if [[ -n $iface ]] && has_cmd ip; then
    ST_IFACE_MTU="$(ip -o link show dev "$iface" 2>/dev/null | awk '{for (i = 1; i < NF; i++) if ($i == "mtu") {print $(i + 1); exit}}')"
    [[ $ST_IFACE_MTU =~ ^[0-9]+$ ]] || ST_IFACE_MTU=0
  fi
  printf 'Interface %s%s%s MTU: %s\n' "$C_KEY" "${iface:-?}" "$C_RESET" "$((ST_IFACE_MTU))"
  for target in "${ST_PMTU_TARGETS[@]}"; do
    if value="$(_pmtu_probe "$target")"; then
      printf '  path to %-9s %s bytes\n' "$target" "$value"
      if ((ST_PMTU == 0 || value < ST_PMTU)); then
        ST_PMTU="$value"
      fi
    else
      printf '  path to %-9s %sno answer%s\n' "$target" "$C_MUTED" "$C_RESET"
    fi
  done
  return 0
}

# _wg_mtu_advice — compare each WireGuard interface with what the path allows.
_wg_mtu_advice() {
  has_cmd wg || return 0
  ((ST_PMTU > 0)) || return 0
  local wg_if mtu want
  want=$((ST_PMTU - 80)) # 60 (IPv4) / 80 (IPv6) bytes of WireGuard overhead; use the safe one
  for wg_if in $(wg show interfaces 2>/dev/null); do
    mtu="$(ip -o link show dev "$wg_if" 2>/dev/null | awk '{for (i = 1; i < NF; i++) if ($i == "mtu") {print $(i + 1); exit}}')"
    [[ $mtu =~ ^[0-9]+$ ]] || continue
    if ((mtu > want)); then
      printf '  %s  %s has MTU %s but this path carries at most %s — set "MTU = %s" in its config\n' \
        "$(ui_badge warn)" "$wg_if" "$mtu" "$want" "$want"
    else
      printf '  %s  %s MTU %s fits the path\n' "$(ui_badge ok)" "$wg_if" "$mtu"
    fi
  done
}

vpn_mss_clamp() {
  local rc_ufw=0 tool mss=0
  ui_section "Smart MTU / MSS (TCP over tunnels/NAT)"
  printf 'Measures the real path MTU toward the internet, then clamps TCP MSS to what\n'
  printf 'actually fits. Fixes "VPN connects but sites do not load" and the slow,\n'
  printf 'stalling pages that come from silent packet fragmentation.\n\n'
  if ! has_cmd iptables; then
    log_error "iptables not available — cannot apply MSS clamping."
    return 0
  fi

  vpn_measure_mtu
  if ((ST_PMTU > 0 && ST_IFACE_MTU > 0 && ST_PMTU < ST_IFACE_MTU)); then
    mss=$((ST_PMTU - 40))
    printf '\n%sThe path is narrower than the interface%s (%s < %s): fixed MSS %s is the right fix.\n' \
      "$C_WARN" "$C_RESET" "$ST_PMTU" "$ST_IFACE_MTU" "$mss"
  elif ((ST_PMTU > 0)); then
    printf '\n%sThe path carries the full interface MTU.%s Automatic clamping to the route MTU is enough.\n' \
      "$C_OK" "$C_RESET"
  else
    printf '\n%sCould not measure the path%s (ICMP filtered or no connectivity) — using automatic clamping.\n' \
      "$C_WARN" "$C_RESET"
  fi
  _wg_mtu_advice
  ui_confirm_yes "Apply MSS clamping now?" || return 0

  config_set mss_value "$mss"
  for tool in iptables ip6tables; do
    has_cmd "$tool" || continue
    _mss_remove_live "$tool"
    local -a rule
    if [[ $tool == iptables ]]; then
      mapfile -t rule < <(_mss_rule 4)
    else
      mapfile -t rule < <(_mss_rule 6)
    fi
    if ! "$tool" -t mangle -A "${rule[@]}" 2>>"$ST_LOG_FILE"; then
      if [[ $tool == iptables ]]; then
        log_error "Could not add the IPv4 MSS rule — see the log."
        return 0
      fi
      log_warn "IPv6 MSS rule failed (IPv6 clamping skipped)."
    fi
  done

  # UFW rebuilds the whole ruleset on `ufw reload` and at boot, wiping rules
  # added with plain iptables. When UFW owns the firewall, the clamp belongs
  # in before.rules so it is restored with everything else.
  _vpn_mss_ufw_persist || rc_ufw=$?

  if [[ -d /etc/systemd/system ]] && has_cmd systemctl; then
    local ipt ip6t
    ipt="$(command -v iptables)"
    ip6t="$(command -v ip6tables)" || ip6t=''
    st_track_file "$ST_MSS_UNIT"
    {
      printf '# Generated by %s v%s\n' "$ST_NAME" "$ST_VERSION"
      printf '[Unit]\nDescription=ServerTools MSS clamping (oneshot, exits after boot)\nAfter=network-pre.target\nWants=network-pre.target\n\n'
      printf '[Service]\nType=oneshot\nRemainAfterExit=yes\n'
      printf 'ExecStart=%s -t mangle -A %s\n' "$ipt" "$(_mss_rule_words 4)"
      [[ -n $ip6t ]] && printf 'ExecStart=%s -t mangle -A %s\n' "$ip6t" "$(_mss_rule_words 6)"
      printf '\n[Install]\nWantedBy=multi-user.target\n'
    } >"$ST_MSS_UNIT"
    systemctl daemon-reload 2>>"$ST_LOG_FILE" || log_warn "daemon-reload failed."
    if systemctl enable server-tools-mss.service >/dev/null 2>>"$ST_LOG_FILE"; then
      manifest_add unit server-tools-mss.service
    else
      log_warn "Could not enable boot persistence for the MSS rule."
    fi
  else
    log_warn "No systemd — the MSS rule is active now but will not survive a reboot."
  fi

  if ((rc_ufw == 0)); then
    printf '%sMSS clamping active%s (persisted for reboots and for "ufw reload").\n' \
      "$C_OK" "$C_RESET"
  else
    printf '%sMSS clamping active%s (persisted via oneshot unit — nothing stays running).\n' \
      "$C_OK" "$C_RESET"
  fi
  log_info "MSS clamping applied (mss_value=${mss}, ufw persistence rc=${rc_ufw})."
}

# mss_verify — 0 when the clamp rule is present in the live mangle table.
mss_verify() {
  has_cmd iptables || return 2
  local -a rule
  mapfile -t rule < <(_mss_rule 4)
  iptables -t mangle -C "${rule[@]}" 2>/dev/null && return 0
  # Only report drift when we were actually asked to set it up.
  [[ -f $ST_MSS_UNIT ]] && return 3
  return 2
}

# ---------------------------------------------------------------------------
# NOTRACK — exempt userspace-proxy data ports from connection tracking.
#
# A Reality/Xray/Trojan/Hysteria node terminates every inbound connection in
# userspace and opens its OWN outbound sockets; the kernel never NATs the
# inbound leg, so the conntrack entry it creates for each of the millions of
# short-lived client connections is pure overhead. Exempting the proxy data
# ports (raw table, both directions) keeps the conntrack table near-empty — it
# can no longer hit nf_conntrack_max under load — and removes the per-packet
# tracking cost on the hottest path on the box.
#
# Never applied to a WireGuard/NAT port (that genuinely needs conntrack) or to
# SSH (kept tracked for fail2ban/stateful rules); both are excluded below.
# ---------------------------------------------------------------------------
readonly ST_NOTRACK_UNIT='/etc/systemd/system/server-tools-notrack.service'
# Filled by _notrack_detect_target: the working "no-track" target for this
# kernel — modern "-j CT --notrack" or the legacy "-j NOTRACK" alias.
ST_NOTRACK_TARGET=()

# _notrack_detect_target — probe which raw NOTRACK target this kernel accepts,
# by adding then removing one harmless rule on an unused high port.
_notrack_detect_target() {
  has_cmd iptables || return 1
  local probe=65533 form
  local -a probe_args=()
  for form in 'CT --notrack' 'NOTRACK'; do
    # Split explicitly: with the global IFS ($'\n\t') an unquoted $form does NOT
    # word-split, so iptables would receive "-j CT --notrack" as a single
    # argument and reject every rule.
    IFS=' ' read -ra probe_args <<<"-j ${form}"
    if iptables -t raw -A OUTPUT -p tcp --dport "$probe" "${probe_args[@]}" 2>/dev/null; then
      iptables -t raw -D OUTPUT -p tcp --dport "$probe" "${probe_args[@]}" 2>/dev/null ||
        log_warn "Could not remove the NOTRACK probe rule (port ${probe})."
      ST_NOTRACK_TARGET=("${probe_args[@]}")
      return 0
    fi
  done
  return 1
}

# _notrack_specs PORT — the rule bodies (everything after "-A") for one port,
# one per line. Single source of truth shared by apply, persist and verify.
_notrack_specs() {
  local port="$1" proto
  for proto in tcp udp; do
    printf 'PREROUTING -p %s --dport %s\n' "$proto" "$port"
    printf 'OUTPUT -p %s --sport %s\n' "$proto" "$port"
  done
}

# _notrack_dnat_ports — host ports that a DNAT/REDIRECT rule forwards (Docker
# `-p`, manual port-forwards). NOTRACK skips the nat table, so exempting one of
# these silently breaks its forwarding — fatal with docker userland-proxy off.
_notrack_dnat_ports() {
  has_cmd iptables || return 0
  local out out6=''
  out="$(iptables -t nat -S 2>/dev/null)" || out=''
  if has_cmd ip6tables; then
    out6="$(ip6tables -t nat -S 2>/dev/null)" || out6=''
  fi
  printf '%s\n%s\n' "$out" "$out6" |
    grep -E -- '-j (DNAT|REDIRECT)' |
    grep -oE -- '--dport [0-9]+' |
    awk '{print $2}' | sort -un
}

# _notrack_candidates SSH WG DNAT — listening TCP ports worth exempting:
# everything with a listener, minus the ports that must keep conntrack
# (SSH, WireGuard, and any DNAT/Docker-forwarded port).
_notrack_candidates() {
  has_cmd ss || return 0
  local excl listeners
  excl="$(printf '%s\n%s\n%s\n' "$1" "$2" "$3" | grep -E '^[0-9]+$' | sort -un)"
  listeners="$(ss -tln 2>/dev/null)" || return 0
  # Same reachability rule as the reserved-ports logic: a loopback-only listener
  # is internal plumbing, so exempting it from conntrack would buy nothing.
  _ss_listen_ports "$listeners" | _ports_subtract "$excl" | paste -sd, -
}

# _notrack_sanitize LIST — keep valid 1..65535 ports, dedup, comma-join.
_notrack_sanitize() {
  local tok out=()
  while IFS= read -r tok; do
    if [[ $tok =~ ^[0-9]+$ ]] && ((tok >= 1 && tok <= 65535)); then out+=("$tok"); fi
  done < <(ports_split "$1")
  ((${#out[@]})) || return 0
  printf '%s\n' "${out[@]}" | sort -un | paste -sd, -
}

# _notrack_drop_ports LIST DROP — LIST minus DROP (either comma- or newline-
# separated), dedup, comma-join. Empty output is a valid result.
_notrack_drop_ports() {
  local drop
  drop="$(tr ',' '\n' <<<"$2" | grep -E '^[0-9]+$' | sort -un)"
  tr ',' '\n' <<<"$1" | grep -E '^[0-9]+$' | sort -un | _ports_subtract "$drop" | paste -sd, -
}

# _notrack_apply_live PORTS... — add the rules idempotently to IPv4 (+IPv6).
_notrack_apply_live() {
  local port spec bin
  local -a rule=()
  for bin in iptables ip6tables; do
    has_cmd "$bin" || continue
    for port in "$@"; do
      while IFS= read -r spec; do
        # Each token must be its own argv entry (the global IFS would not split
        # an unquoted $spec, handing iptables one nonsense argument).
        IFS=' ' read -ra rule <<<"$spec"
        "$bin" -t raw -C "${rule[@]}" "${ST_NOTRACK_TARGET[@]}" 2>/dev/null && continue
        "$bin" -t raw -A "${rule[@]}" "${ST_NOTRACK_TARGET[@]}" 2>>"$ST_LOG_FILE" ||
          log_warn "Could not add NOTRACK rule (${bin}): ${spec}"
      done < <(_notrack_specs "$port")
    done
  done
  return 0
}

# _notrack_write_unit PORTS... — a oneshot unit that re-adds the rules at boot
# and removes them on `systemctl disable --now` (so rollback clears them live).
_notrack_write_unit() {
  local port spec ipt ip6t tgt
  ipt="$(command -v iptables)"
  ip6t="$(command -v ip6tables)" || ip6t=''
  # join_sp, not "${arr[*]}": the global IFS would join with newlines and split
  # every ExecStart= across several broken lines.
  tgt="$(join_sp "${ST_NOTRACK_TARGET[@]}")"
  st_track_file "$ST_NOTRACK_UNIT"
  {
    printf '# Generated by %s v%s\n' "$ST_NAME" "$ST_VERSION"
    printf '[Unit]\nDescription=ServerTools conntrack NOTRACK for proxy ports (oneshot, exits after boot)\n'
    printf 'After=network-pre.target\nWants=network-pre.target\n\n'
    printf '[Service]\nType=oneshot\nRemainAfterExit=yes\n'
    for port in "$@"; do
      while IFS= read -r spec; do
        printf 'ExecStart=%s -t raw -A %s %s\n' "$ipt" "$spec" "$tgt"
        [[ -n $ip6t ]] && printf 'ExecStart=%s -t raw -A %s %s\n' "$ip6t" "$spec" "$tgt"
      done < <(_notrack_specs "$port")
    done
    for port in "$@"; do
      while IFS= read -r spec; do
        # "-" prefix: a rule already gone at stop time is not an error.
        printf 'ExecStop=-%s -t raw -D %s %s\n' "$ipt" "$spec" "$tgt"
        [[ -n $ip6t ]] && printf 'ExecStop=-%s -t raw -D %s %s\n' "$ip6t" "$spec" "$tgt"
      done < <(_notrack_specs "$port")
    done
    printf '\n[Install]\nWantedBy=multi-user.target\n'
  } >"$ST_NOTRACK_UNIT"
  return 0
}

# _notrack_unit_ports — ports the persisted unit covers (self-describing, so
# verify needs no config state and reports "not configured" after rollback).
_notrack_unit_ports() {
  [[ -f $ST_NOTRACK_UNIT ]] || return 0
  grep -oE -- '--dport [0-9]+' "$ST_NOTRACK_UNIT" | awk '{print $2}' | sort -un
}

vpn_conntrack_bypass() {
  ui_section "NOTRACK — take proxy ports out of connection tracking"
  printf 'On a userspace-proxy node (Xray/Reality, VLESS/VMess/Trojan, Hysteria)\n'
  printf 'every inbound connection creates a conntrack entry the proxy never needs:\n'
  printf 'it terminates traffic in userspace and opens its own outbound sockets.\n'
  printf 'Exempting the proxy data ports keeps the conntrack table near-empty, so\n'
  printf 'it cannot fill under load and the per-packet tracking cost disappears.\n\n'
  printf '%sTrade-off:%s the exempted ports lose stateful (ESTABLISHED/RELATED)\n' "$C_WARN" "$C_RESET"
  printf 'firewall matching, so they must be allowed by an explicit port rule —\n'
  printf 'which a proxy inbound always has. WireGuard/NAT and SSH ports are\n'
  printf 'excluded automatically because they genuinely need conntrack.\n\n'

  if ! has_cmd iptables; then
    log_error "iptables is not available — cannot manage NOTRACK rules."
    return 0
  fi
  if ! _notrack_detect_target; then
    log_error "This kernel's iptables has no usable raw NOTRACK target — skipped."
    return 0
  fi

  local ssh_port wg_ports dnat_ports suggested
  ssh_port="$(detect_ssh_port)" || ssh_port=22
  # WireGuard must keep conntrack: it relies on NAT for client routing.
  wg_ports="$(wg_listen_ports)" || wg_ports=''
  dnat_ports="$(_notrack_dnat_ports)" || dnat_ports=''
  suggested="$(_notrack_candidates "$ssh_port" "$wg_ports" "$dnat_ports")" || suggested=''

  if [[ -n $wg_ports ]]; then
    printf '%sWireGuard detected%s on port(s) %s — excluded (NAT needs conntrack).\n' \
      "$C_KEY" "$C_RESET" "$(paste -sd, - <<<"$wg_ports")"
  fi
  if [[ -n $dnat_ports ]]; then
    printf '%sDocker/DNAT-forwarded port(s)%s %s — excluded: NOTRACK skips the nat\n' \
      "$C_KEY" "$C_RESET" "$(paste -sd, - <<<"$dnat_ports")"
    printf 'table, which would break their port forwarding.\n'
  fi
  if [[ -z $suggested ]]; then
    printf 'No proxy data ports were detected to exempt (nothing is listening\n'
    printf 'outside SSH/WireGuard/Docker). Nothing to do.\n'
    return 0
  fi
  printf '%sDetected proxy port(s):%s %s\n\n' "$C_KEY" "$C_RESET" "$suggested"

  local answer ports
  read -rp "Ports to exempt [Enter=detected, space/comma separated]: " answer || return 0
  ports="$(_notrack_sanitize "${answer:-$suggested}")" || ports=''
  # Hard rule, even against manual input: a DNAT-forwarded port must never be
  # NOTRACK'd (it would break forwarding), so drop any that slipped in.
  if [[ -n $ports && -n $dnat_ports ]]; then
    local kept
    kept="$(_notrack_drop_ports "$ports" "$dnat_ports")"
    if [[ $kept != "$ports" ]]; then
      printf '%sRemoved Docker/DNAT port(s)%s from the selection — NOTRACK would break their forwarding.\n' \
        "$C_WARN" "$C_RESET"
      ports="$kept"
    fi
  fi
  if [[ -z $ports ]]; then
    printf 'No valid ports given — nothing to do.\n'
    return 0
  fi

  printf '\n%sWill exempt%s tcp+udp on port(s) %s, both directions, IPv4%s.\n' \
    "$C_KEY" "$C_RESET" "$ports" "$(has_cmd ip6tables && printf '+IPv6' || printf '')"
  ui_confirm "Apply NOTRACK now and persist it for reboots?" || return 0

  local -a plist=()
  mapfile -t plist < <(ports_split "$ports")
  _notrack_apply_live "${plist[@]}"

  if [[ -d /etc/systemd/system ]] && has_cmd systemctl; then
    _notrack_write_unit "${plist[@]}"
    systemctl daemon-reload 2>>"$ST_LOG_FILE" || log_warn "daemon-reload failed."
    if systemctl enable server-tools-notrack.service >/dev/null 2>>"$ST_LOG_FILE"; then
      manifest_add unit server-tools-notrack.service
    else
      log_warn "Could not enable boot persistence for the NOTRACK rules."
    fi
  else
    log_warn "No systemd — NOTRACK is active now but will not survive a reboot."
  fi

  if notrack_verify; then
    printf '%sNOTRACK active%s on %s — those flows no longer touch conntrack.\n' \
      "$C_OK" "$C_RESET" "$ports"
  else
    printf '%sNOTRACK rules did not all verify%s — see the log.\n' "$C_WARN" "$C_RESET"
  fi
  log_info "NOTRACK applied on ports: ${ports}."
  return 0
}

# notrack_verify — 0 when every persisted rule is live, 3 on drift, 2 when the
# feature was never configured on this host.
notrack_verify() {
  has_cmd iptables || return 2
  [[ -f $ST_NOTRACK_UNIT ]] || return 2
  local ports port spec
  local -a rule=()
  ports="$(_notrack_unit_ports)" || return 2
  [[ -n $ports ]] || return 2
  while IFS= read -r port; do
    [[ $port =~ ^[0-9]+$ ]] || continue
    while IFS= read -r spec; do
      # One argv entry per token — an unquoted $spec does not split under the
      # global IFS, so iptables would answer "no such rule" for every port.
      IFS=' ' read -ra rule <<<"$spec"
      iptables -t raw -C "${rule[@]}" -j CT --notrack 2>/dev/null && continue
      iptables -t raw -C "${rule[@]}" -j NOTRACK 2>/dev/null && continue
      return 3
    done < <(_notrack_specs "$port")
  done <<<"$ports"
  return 0
}

vpn_docker_ufw_audit() {
  ui_section "Docker + UFW audit"
  local docker_on=0 ufw_on=0
  if has_cmd docker && docker ps -q 2>/dev/null | grep -q .; then
    docker_on=1
  fi
  if has_cmd ufw && ufw status 2>/dev/null | grep -q '^Status: active'; then
    ufw_on=1
  fi

  if ((docker_on == 0)); then
    printf 'No running Docker containers — no bypass risk.\n'
    return 0
  fi
  if ((ufw_on == 0)); then
    printf 'Docker is running but UFW is inactive — nothing to bypass (no firewall).\n'
    return 0
  fi

  printf '%sBoth Docker and UFW are active.%s Docker inserts its own iptables rules,\n' "$C_WARN" "$C_RESET"
  printf 'so ports published with -p/ports: are reachable EVEN IF UFW blocks them.\n'
  printf '\n%sPublished ports right now:%s\n' "$C_KEY" "$C_RESET"
  docker ps --format '  {{.Names}}: {{.Ports}}' 2>/dev/null ||
    log_warn "Could not list container ports."
  printf '\nMitigations: bind sensitive ports to 127.0.0.1 in compose, or use the\n'
  printf 'ufw-docker approach (planned in ROADMAP.md backlog).\n'
}

# ------------------------- src/modules/priority.sh -------------------------
# ============================================================================
# modules/priority.sh — give VPN proxies the CPU and the OOM protection they
# deserve, for native services AND containers (Docker / Podman).
#
#   native services  systemd drop-in: Nice, OOMScoreAdjust, CPUWeight,
#                    LimitNOFILE — survives every restart and reboot.
#   containers       applied live to the container's host processes
#                    (renice every thread, oom_score_adj, cpu-shares), and
#                    re-applied at boot by a oneshot unit that exits at once.
#
# Nothing stays resident. A container that is recreated later (compose up,
# image update) starts without the boost until `st boost` or the next boot.
# ============================================================================

readonly ST_PRIO_NICE=-5
readonly ST_PRIO_OOM=-500
readonly ST_PRIO_CPU_WEIGHT=200  # systemd default is 100
readonly ST_PRIO_CPU_SHARES=2048 # docker default is 1024
readonly ST_PRIO_NOFILE=1048576
readonly ST_PRIO_UNIT='/etc/systemd/system/server-tools-boost.service'
readonly ST_PRIO_REGEX='marzban|marznode|pg[-_]?node|pasarguard|gozargah|x-?ui|xray|hiddify|sing-?box|hysteria|wireguard|wg-'
readonly -a ST_PRIO_SERVICES=(xray x-ui sing-box hysteria-server)

# Filled by priority_detect: service names, and "engine<TAB>name" lines.
ST_PRIO_SVC_TARGETS=()
ST_PRIO_CTR_TARGETS=()

# priority_detect — what is running right now that deserves priority.
priority_detect() {
  ST_PRIO_SVC_TARGETS=()
  ST_PRIO_CTR_TARGETS=()
  local svc engine line
  if has_cmd systemctl; then
    for svc in "${ST_PRIO_SERVICES[@]}"; do
      if systemctl is-active --quiet "$svc" 2>/dev/null; then
        ST_PRIO_SVC_TARGETS+=("$svc")
      fi
    done
  fi
  for engine in docker podman; do
    has_cmd "$engine" || continue
    # Match on name AND image, like detect_stack: a pg-node container is often
    # just called "node". grep exit 1 (no match) is a normal outcome.
    while IFS= read -r line; do
      [[ -n $line ]] && ST_PRIO_CTR_TARGETS+=("${engine}"$'\t'"${line}")
    done < <("$engine" ps --format '{{.Names}} {{.Image}}' 2>/dev/null |
      grep -iE "$ST_PRIO_REGEX" | awk '{print $1}' || true)
  done
  return 0
}

priority_has_targets() {
  priority_detect
  ((${#ST_PRIO_SVC_TARGETS[@]} + ${#ST_PRIO_CTR_TARGETS[@]} > 0))
}

# _prio_service_pids SERVICE — every process of the unit (its whole cgroup).
_prio_service_pids() {
  local svc="$1" cg main
  cg="$(systemctl show -p ControlGroup --value "$svc" 2>/dev/null)" || cg=''
  if [[ -n $cg && -r /sys/fs/cgroup${cg}/cgroup.procs ]]; then
    cat "/sys/fs/cgroup${cg}/cgroup.procs"
    return 0
  fi
  main="$(systemctl show -p MainPID --value "$svc" 2>/dev/null)" || main=''
  if [[ $main =~ ^[1-9][0-9]*$ ]]; then
    printf '%s\n' "$main"
  fi
  return 0
}

# _prio_container_pids ENGINE NAME — host PIDs of everything in the container.
_prio_container_pids() {
  "$1" top "$2" -eo pid 2>/dev/null | awk 'NR > 1 {print $1}'
}

# _prio_boost_pid PID — renice every thread (a Go proxy runs dozens; renice -p
# on the PID alone only touches the main thread) and shield it from the OOM
# killer. Returns 1 when the process could not be boosted at all.
_prio_boost_pid() {
  local pid="$1" tid ok=0
  [[ -d /proc/$pid ]] || return 1
  for tid in "/proc/${pid}/task/"*; do
    # A thread may exit between listing and renice; that is not a failure.
    if renice -n "$ST_PRIO_NICE" -p "${tid##*/}" >/dev/null 2>&1; then
      ok=1
    fi
  done
  ((ok)) || return 1
  printf '%s' "$ST_PRIO_OOM" >"/proc/${pid}/oom_score_adj" 2>>"$ST_LOG_FILE" ||
    log_warn "Could not lower oom_score_adj of PID ${pid}."
  return 0
}

# _prio_write_dropin SERVICE — persistent systemd settings for a native proxy.
# Returns 0 when the file changed, 1 when it was already correct.
_prio_write_dropin() {
  local svc="$1" dir file content
  dir="/etc/systemd/system/${svc}.service.d"
  file="${dir}/99-server-tools.conf"
  content="# Generated by ${ST_NAME} v${ST_VERSION}
[Service]
Nice=${ST_PRIO_NICE}
OOMScoreAdjust=${ST_PRIO_OOM}
CPUWeight=${ST_PRIO_CPU_WEIGHT}
LimitNOFILE=${ST_PRIO_NOFILE}"
  if [[ -f $file && "$(<"$file")" == "$content" ]]; then
    return 1
  fi
  st_track_file "$file"
  mkdir -p "$dir"
  printf '%s\n' "$content" >"$file"
}

# _prio_write_boot_unit — re-applies container priority after a reboot.
_prio_write_boot_unit() {
  if [[ ! -x $ST_INSTALL_PATH ]]; then
    log_warn "'st' is not installed (st --install) — container priority will not be re-applied at boot."
    return 3
  fi
  has_cmd systemctl || return 2
  st_track_file "$ST_PRIO_UNIT"
  cat >"$ST_PRIO_UNIT" <<EOF
# Generated by ${ST_NAME} v${ST_VERSION}
[Unit]
Description=ServerTools proxy priority (oneshot, exits after boot)
After=network-online.target docker.service podman.service
Wants=network-online.target

[Service]
Type=oneshot
RemainAfterExit=yes
TimeoutStartSec=180
Environment=ST_BOOST_WAIT=90
ExecStart=${ST_INSTALL_PATH} boost

[Install]
WantedBy=multi-user.target
EOF
  systemctl daemon-reload 2>>"$ST_LOG_FILE" || log_warn "daemon-reload failed."
  if systemctl enable server-tools-boost.service >/dev/null 2>>"$ST_LOG_FILE"; then
    manifest_add unit server-tools-boost.service
  else
    log_warn "Could not enable boot persistence for container priority."
    return 3
  fi
}

# priority_apply — boost everything detected. Prompts nothing.
# Returns 0 ok, 2 nothing to do, 3 partial.
priority_apply() {
  priority_detect
  if ((${#ST_PRIO_SVC_TARGETS[@]} + ${#ST_PRIO_CTR_TARGETS[@]} == 0)); then
    printf 'No proxy service or container found.\n'
    return 2
  fi

  local rc=0 svc entry engine name pid boosted reload=0
  for svc in "${ST_PRIO_SVC_TARGETS[@]}"; do
    if _prio_write_dropin "$svc"; then
      reload=1
    fi
    boosted=0
    while IFS= read -r pid; do
      [[ -n $pid ]] || continue
      if _prio_boost_pid "$pid"; then
        boosted=$((boosted + 1))
      fi
      # Raise the open-file ceiling of the running process too, so it does not
      # wait for a restart.
      if has_cmd prlimit; then
        prlimit --pid "$pid" --nofile="${ST_PRIO_NOFILE}:${ST_PRIO_NOFILE}" 2>>"$ST_LOG_FILE" ||
          log_warn "Could not raise nofile of PID ${pid} live (applies on next restart)."
      fi
    done < <(_prio_service_pids "$svc")
    if ((boosted > 0)); then
      printf '  %s  %s %s(%d processes, persisted via systemd)%s\n' \
        "$(ui_badge ok)" "$svc" "$C_MUTED" "$boosted" "$C_RESET"
    else
      printf '  %s  %s %s— drop-in written, running process not reachable%s\n' \
        "$(ui_badge warn)" "$svc" "$C_MUTED" "$C_RESET"
      rc=3
    fi
  done
  if ((reload)); then
    systemctl daemon-reload 2>>"$ST_LOG_FILE" || log_warn "daemon-reload failed."
  fi

  for entry in "${ST_PRIO_CTR_TARGETS[@]}"; do
    IFS=$'\t' read -r engine name <<<"$entry"
    boosted=0
    while IFS= read -r pid; do
      [[ -n $pid ]] || continue
      if _prio_boost_pid "$pid"; then
        boosted=$((boosted + 1))
      fi
    done < <(_prio_container_pids "$engine" "$name")
    "$engine" update --cpu-shares "$ST_PRIO_CPU_SHARES" "$name" >/dev/null 2>>"$ST_LOG_FILE" ||
      log_warn "Could not raise cpu-shares of ${name} (priority by nice still applies)."
    if ((boosted > 0)); then
      printf '  %s  %s %s(%s, %d processes)%s\n' \
        "$(ui_badge ok)" "$name" "$C_MUTED" "$engine" "$boosted" "$C_RESET"
    else
      printf '  %s  %s %s— no process could be boosted%s\n' \
        "$(ui_badge warn)" "$name" "$C_MUTED" "$C_RESET"
      rc=3
    fi
  done

  if ((${#ST_PRIO_CTR_TARGETS[@]} > 0)) && [[ ! -f $ST_PRIO_UNIT ]]; then
    _prio_write_boot_unit || rc=3
  fi
  log_info "Proxy priority applied (services=${#ST_PRIO_SVC_TARGETS[@]}, containers=${#ST_PRIO_CTR_TARGETS[@]}, rc=${rc})."
  return "$rc"
}

# priority_step — the non-interactive step used by Quick/Auto/Go.
priority_step() {
  # A temp file, not $(...): a subshell would hide st_track_file's bookkeeping
  # from this process, and st_run_step needs its status line to stay clean.
  local tmp out rc=0
  tmp="$(mktemp)"
  priority_apply >"$tmp" || rc=$?
  out="$(<"$tmp")"
  rm -f "$tmp"
  if [[ -n $out ]]; then
    ST_LOG_BUFFER+=("${out//$'\n'/; }")
  fi
  return "$rc"
}

# priority_boot — `st boost`: what the boot unit runs. Containers may still be
# starting, so it waits (ST_BOOST_WAIT seconds at most) for the first one.
priority_boot() {
  local waited=0 limit="${ST_BOOST_WAIT:-0}"
  while ((waited < limit)); do
    priority_detect
    if ((${#ST_PRIO_CTR_TARGETS[@]} > 0)); then
      break
    fi
    sleep 5
    waited=$((waited + 5))
  done
  priority_apply
}

# priority_menu — interactive screen with the explanation up front.
priority_menu() {
  ui_section "Proxy priority (native services + Docker/Podman)"
  priority_detect
  printf 'Under CPU pressure the proxy is the LAST thing that should slow down, and\n'
  printf 'the OOM killer should never pick it. This sets, per process:\n'
  printf '  · nice %s · OOM shield %s · CPU weight x2 · nofile %s\n' \
    "$ST_PRIO_NICE" "$ST_PRIO_OOM" "$ST_PRIO_NOFILE"
  printf 'Services get a systemd drop-in (permanent). Containers are boosted live\n'
  printf 'and again at every boot by a oneshot unit that exits immediately.\n\n'
  if ((${#ST_PRIO_SVC_TARGETS[@]} + ${#ST_PRIO_CTR_TARGETS[@]} == 0)); then
    printf 'No running proxy service or container was found.\n'
    return 0
  fi
  local entry
  for entry in "${ST_PRIO_SVC_TARGETS[@]}"; do
    printf '  · service   %s\n' "$entry"
  done
  for entry in "${ST_PRIO_CTR_TARGETS[@]}"; do
    printf '  · container %s\n' "${entry//$'\t'/ }"
  done
  ui_confirm_yes "Apply priority now? (no restart, no disconnects)" || return 0
  priority_apply || true # per-target outcome is printed above
}

# priority_verify — 0 in effect, 2 not set up, 3 drifted (Doctor contract).
priority_verify() {
  local svc file pid ni any=0
  for svc in "${ST_PRIO_SERVICES[@]}"; do
    file="/etc/systemd/system/${svc}.service.d/99-server-tools.conf"
    [[ -f $file ]] || continue
    systemctl is-active --quiet "$svc" 2>/dev/null || continue
    any=1
    pid="$(systemctl show -p MainPID --value "$svc" 2>/dev/null)" || pid=''
    [[ $pid =~ ^[1-9][0-9]*$ ]] || return 3
    ni="$(ps -o ni= -p "$pid" 2>/dev/null | tr -d '[:space:]')" || ni=''
    [[ $ni == "$ST_PRIO_NICE" ]] || return 3
  done
  if ((any)); then
    return 0
  fi
  if [[ -f $ST_PRIO_UNIT ]]; then
    return 0
  fi
  return 2
}

# ------------------------- src/modules/ipv6.sh -------------------------
# ============================================================================
# modules/ipv6.sh — optional, reversible full IPv6 disable.
#
# Some VPN stacks leak or lag over IPv6: happy-eyeballs races, half-configured
# SLAAC, or AAAA answers with no working v6 route. This switches the IPv6 stack
# off completely via a tracked sysctl drop-in — no reboot, no GRUB edit — undone
# by one Enable (or a normal rollback). It is deliberately NOT part of Quick
# Optimize: on a v6-only host it can cut network access, so it stays opt-in.
# ============================================================================

readonly ST_IPV6_SYSCTL='/etc/sysctl.d/99-server-tools-ipv6.conf'

# _ipv6_present — 0 when the kernel exposes the IPv6 stack at all (a kernel
# built or booted without IPv6 has no disable_ipv6 knob, so sysctl_get -> "?").
_ipv6_present() {
  [[ "$(sysctl_get net.ipv6.conf.all.disable_ipv6)" != '?' ]]
}

# _ipv6_disabled_live — 0 when the running kernel has IPv6 switched off.
_ipv6_disabled_live() {
  [[ "$(sysctl_get net.ipv6.conf.all.disable_ipv6)" == 1 ]]
}

# _ipv6_managed — 0 when ServerTools is the one that disabled IPv6 here.
_ipv6_managed() { [[ -f $ST_IPV6_SYSCTL ]]; }

# _ipv6_global_addrs — global-scope IPv6 addresses currently configured.
_ipv6_global_addrs() {
  has_cmd ip || return 0
  ip -6 addr show scope global 2>/dev/null | awk '/inet6 / {print $2}' || true
}

# _ipv6_ssh_is_v6 — 0 when THIS SSH session arrived over IPv6 (disabling would
# drop it). SSH_CONNECTION = "clientIP clientPort serverIP serverPort".
_ipv6_ssh_is_v6() {
  local srv
  [[ -n ${SSH_CONNECTION:-} ]] || return 1
  # SSH_CONNECTION is space-separated, but the tool's global IFS is $'\n\t'
  # (no space) — without an explicit space here every field lands empty.
  IFS=' ' read -r _ _ srv _ <<<"$SSH_CONNECTION"
  [[ $srv == *:* ]]
}

# _ipv6_v6_only — 0 when the host has no IPv4 default route but does have an
# IPv6 one: disabling IPv6 there would strand it off the network.
_ipv6_v6_only() {
  has_cmd ip || return 1
  local v4 v6
  v4="$(ip -4 route show default 2>/dev/null)" || v4=''
  v6="$(ip -6 route show default 2>/dev/null)" || v6=''
  [[ -z $v4 && -n $v6 ]]
}

ipv6_disable() {
  if ! _ipv6_present; then
    printf 'IPv6 is not present on this kernel (already fully disabled). Nothing to do.\n'
    return 0
  fi
  # Safety: never strand a host that reaches the network only over IPv6.
  if _ipv6_v6_only; then
    printf '%sRefusing:%s this host has no IPv4 default route but does have an IPv6\n' "$C_ERR" "$C_RESET"
    printf 'one — disabling IPv6 would cut it off the network. Nothing changed.\n'
    return 2
  fi

  printf 'This switches the IPv6 stack OFF completely on every interface; the\n'
  printf 'server keeps working over IPv4 only. It is reversible at any time.\n\n'
  printf '%sBefore you do this:%s\n' "$C_WARN" "$C_RESET"
  printf '  • A service listening on %s[::]%s (dual-stack) may need switching to\n' "$C_KEY" "$C_RESET"
  printf '    0.0.0.0, or it can fail to start after a reboot.\n'
  printf '  • Do not do this if your VPN actually serves IPv6 to clients.\n\n'

  if _ipv6_ssh_is_v6; then
    printf '%sWarning:%s your current SSH session is over IPv6 — it will drop the\n' "$C_ERR" "$C_RESET"
    printf 'moment IPv6 goes down. Reconnect over IPv4 first, or keep a console open.\n'
    ui_confirm "Continue disabling IPv6 anyway?" || return 2
  fi

  ui_confirm "Disable IPv6 completely now?" || return 2

  st_track_file "$ST_IPV6_SYSCTL"
  mkdir -p "$(dirname "$ST_IPV6_SYSCTL")"
  cat >"$ST_IPV6_SYSCTL" <<EOF
# Generated by ${ST_NAME} v${ST_VERSION} — full IPv6 disable.
# Reversible: Tools -> IPv6 control -> Enable, or delete this file and run
# 'sysctl --system'.
net.ipv6.conf.all.disable_ipv6 = 1
net.ipv6.conf.default.disable_ipv6 = 1
net.ipv6.conf.lo.disable_ipv6 = 1
EOF

  if has_cmd sysctl; then
    sysctl -p "$ST_IPV6_SYSCTL" >/dev/null 2>>"$ST_LOG_FILE" ||
      log_warn "sysctl reported errors applying the IPv6 disable (see log)."
  else
    log_warn "sysctl not found — the setting is written but not applied live."
  fi

  if _ipv6_disabled_live; then
    local left
    left="$(_ipv6_global_addrs | paste -sd' ' -)" || left=''
    printf '\n%sIPv6 disabled%s on all interfaces (persists across reboots).\n' "$C_OK" "$C_RESET"
    [[ -n $left ]] &&
      printf '%sNote:%s a few addresses linger until services restart or a reboot: %s\n' \
        "$C_MUTED" "$C_RESET" "$left"
  else
    printf '\n%sIPv6 is still reported as enabled%s — see the log.\n' "$C_WARN" "$C_RESET"
  fi
  log_info "IPv6 disabled via ${ST_IPV6_SYSCTL}."
  return 0
}

ipv6_enable() {
  if [[ -f $ST_IPV6_SYSCTL ]]; then
    rm -f "$ST_IPV6_SYSCTL" || log_warn "Could not remove ${ST_IPV6_SYSCTL}."
  fi
  # The drop-in is gone, but the running values must be reset too, then a full
  # reload lets any other drop-in reassert its own intent.
  if has_cmd sysctl; then
    local k
    for k in all default lo; do
      sysctl -w "net.ipv6.conf.${k}.disable_ipv6=0" >/dev/null 2>>"$ST_LOG_FILE" ||
        log_warn "Could not re-enable IPv6 on '${k}' live."
    done
    sysctl --system >/dev/null 2>>"$ST_LOG_FILE" ||
      log_warn "sysctl --system reported errors during IPv6 re-enable (see log)."
  fi

  if _ipv6_disabled_live; then
    printf '%sIPv6 still shows disabled%s — a reboot will fully restore it.\n' "$C_WARN" "$C_RESET"
  else
    printf '%sIPv6 re-enabled.%s Interfaces reacquire addresses via RA/DHCPv6.\n' "$C_OK" "$C_RESET"
  fi
  log_info "IPv6 re-enabled (drop-in removed)."
  return 0
}

# ipv6_verify — doctor contract: 0 in effect, 2 not configured, 3 drift.
ipv6_verify() {
  _ipv6_managed || return 2
  _ipv6_disabled_live && return 0
  return 3
}

# ipv6_control — the interactive screen: show state, then disable or enable.
ipv6_control() {
  ui_section "IPv6 control"
  printf 'IPv6 can cause connection races, leaks or lag on some VPN setups. Here\n'
  printf 'you can switch the whole IPv6 stack off (IPv4 keeps working) or back on\n'
  printf '— reversible, no reboot.\n'

  local state addrs
  if ! _ipv6_present; then
    state='not present (kernel-level off)'
  elif _ipv6_disabled_live; then
    if _ipv6_managed; then
      state='disabled (by ServerTools)'
    else
      state='disabled (outside ServerTools)'
    fi
  else
    state='enabled'
  fi
  addrs="$(_ipv6_global_addrs | paste -sd' ' -)" || addrs=''

  printf '\n'
  ui_kv "IPv6 stack" "$state"
  ui_kv "Global addresses" "${addrs:-none}"
  printf '\n'

  if ! _ipv6_present; then
    printf 'Nothing to manage — this kernel has no IPv6 stack.\n'
  elif _ipv6_managed; then
    if ui_confirm "Re-enable IPv6 now?"; then ipv6_enable; fi
  elif _ipv6_disabled_live; then
    printf 'IPv6 is already disabled here (not by ServerTools) — left unchanged.\n'
  else
    ipv6_disable
  fi
  return 0
}

# ------------------------- src/modules/installer.sh -------------------------
# ============================================================================
# modules/installer.sh — node helpers: back up node configuration and
# certificates (the part everyone forgets before an upgrade).
# ============================================================================

readonly ST_NODE_BACKUP_DIR="${ST_LIB_DIR}/backups/nodes"

# Format: label|paths (space separated)
readonly -a ST_NODE_TARGETS=(
  'Marzban node|/opt/marzban-node /var/lib/marzban-node'
  'Pasarguard node (pg-node)|/opt/pg-node /var/lib/pg-node /opt/pasarguard'
  '3x-ui panel|/etc/x-ui /usr/local/x-ui'
  'WireGuard + WGDashboard|/etc/wireguard'
)

# node_backup — archive whatever node configuration exists on this host.
node_backup() {
  ui_section "Back up node configuration"
  local entry _label paths found=() path
  for entry in "${ST_NODE_TARGETS[@]}"; do
    IFS="|" read -r _label paths <<<"$entry"
    for path in $paths; do
      [[ -e $path ]] && found+=("$path")
    done
  done

  if ((${#found[@]} == 0)); then
    printf 'No known node configuration found on this server.\n'
    return 2
  fi

  printf 'Found:\n'
  printf '  %s\n' "${found[@]}"
  if ! has_cmd tar; then
    log_error "tar is not available — cannot create the archive."
    return 1
  fi

  mkdir -p "$ST_NODE_BACKUP_DIR"
  local archive="${ST_NODE_BACKUP_DIR}/node-config-${ST_RUN_ID}.tar.gz"
  if ! tar -czf "$archive" "${found[@]}" 2>>"$ST_LOG_FILE"; then
    log_error "Creating ${archive} failed — see the log."
    return 1
  fi
  chmod 600 "$archive"
  printf '%sSaved:%s %s (%s)\n' "$C_OK" "$C_RESET" "$archive" \
    "$(du -h "$archive" 2>/dev/null | awk '{print $1}')"
  printf '%sIt contains certificates and keys — keep it private.%s\n' "$C_WARN" "$C_RESET"
  log_info "Node configuration archived to ${archive}."
  return 0
}

node_menu() {
  local choice
  while true; do
    ui_logo
    ui_title "Node & Docker helpers"
    ui_kv "Detected" "$(detect_summary)"
    ui_menu_item 1 "Back up node config" "archive certificates and settings"
    ui_menu_item 2 "Docker file limits" "raise nofile for all containers"
    ui_menu_item 0 "Back"
    read -rp "$(_ui_prompt)" choice || return 0
    case "${choice:-}" in
      1)
        node_backup || true # outcome already reported
        ui_pause
        ;;
      2)
        limits_docker_ulimits || true
        ui_pause
        ;;
      0) return 0 ;;
      *)
        printf '%sInvalid choice.%s\n' "$C_ERR" "$C_RESET"
        sleep 1
        ;;
    esac
  done
}

# ------------------------- src/modules/tools.sh -------------------------
# ============================================================================
# modules/tools.sh — on-demand network diagnostics. Read-only except where
# a tool explicitly says otherwise; nothing here runs in the background.
# ============================================================================

# Format: label|ip
readonly -a ST_PING_TARGETS=(
  'Iran - TCI (217.218.127.127)|217.218.127.127'
  'Iran - Shecan (178.22.122.100)|178.22.122.100'
  'Global - Cloudflare (1.1.1.1)|1.1.1.1'
  'Global - Google (8.8.8.8)|8.8.8.8'
)

tools_ping_matrix() {
  ui_section "Ping matrix (Iran + global, 3 probes each)"
  if ! has_cmd ping; then
    printf 'ping is not available on this system.\n'
    return 0
  fi
  printf 'Useful for judging how well this location serves users in Iran.\n\n'
  local entry label ip out loss avg
  for entry in "${ST_PING_TARGETS[@]}"; do
    IFS='|' read -r label ip <<<"$entry"
    out="$(ping -c 3 -W 1 "$ip" 2>/dev/null)" || out=''
    loss="$(grep -oE '[0-9]+(\.[0-9]+)?% packet loss' <<<"$out" | cut -d'%' -f1)" || loss=''
    avg="$(awk -F'/' '/rtt|round-trip/ {print $5; exit}' <<<"$out")" || avg=''
    if [[ -n $avg ]]; then
      printf '  %-38s loss %3s%%   avg %s ms\n' "$label" "${loss:-?}" "$avg"
    else
      printf '  %-38s %sunreachable%s\n' "$label" "$C_ERR" "$C_RESET"
    fi
  done
}

tools_tcp_status() {
  ui_section "TCP / conntrack live status"
  ui_kv "Congestion" "$(sysctl_get net.ipv4.tcp_congestion_control)"
  ui_kv "Qdisc" "$(sysctl_get net.core.default_qdisc)"
  ui_kv "Available cc" "$(sysctl_get net.ipv4.tcp_available_congestion_control)"
  ui_kv "IPv4 forward" "$(sysctl_get net.ipv4.ip_forward)"
  ui_kv "IPv6 forward" "$(sysctl_get net.ipv6.conf.all.forwarding)"

  local count max
  count="$(sysctl_get net.netfilter.nf_conntrack_count)"
  max="$(sysctl_get net.netfilter.nf_conntrack_max)"
  if [[ $count =~ ^[0-9]+$ && $max =~ ^[0-9]+$ && $max -gt 0 ]]; then
    ui_kv "Conntrack" "${count} / ${max} ($((count * 100 / max))% used)"
  else
    ui_kv "Conntrack" "module not loaded"
  fi
}

tools_listening_ports() {
  ui_section "Listening ports"
  if ! has_cmd ss; then
    printf 'ss (iproute2) is not available.\n'
    return 0
  fi
  # Display-only snapshot, capped with awk: `head` would SIGPIPE ss under
  # pipefail and turn a fine listing into a spurious warning.
  ss -tulnp 2>/dev/null | awk 'NR <= 30' || log_warn "Could not list sockets."
}

# Ookla speedtest CLI — the accurate, reliable path: it uses Ookla's own
# protocol and a nearby server, so it sidesteps the Cloudflare 403s / inbound
# throttling some hosts (notably in Iran) hit on plain HTTP tests. Fetched on
# demand, run once and deleted — zero persistent footprint (rule 1).
readonly ST_OOKLA_VER='1.2.0'
# Cloudflare's speed endpoints answer 403 to a bare curl UA on some IPs; a
# browser UA dodges that for the HTTP fallback.
readonly ST_HTTP_UA='Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0 Safari/537.36'

# _st_ookla_arch — Ookla CLI arch tag for this machine (non-zero if unsupported).
_st_ookla_arch() {
  case "$(uname -m)" in
    x86_64 | amd64) printf 'x86_64' ;;
    aarch64 | arm64) printf 'aarch64' ;;
    armv7* | armhf) printf 'armhf' ;;
    i386 | i686) printf 'i386' ;;
    *) return 1 ;;
  esac
}

# _st_fetch_ookla — download + extract the official Ookla CLI into a fresh temp
# dir; echo the dir on success (the caller runs and removes it). Empty output /
# non-zero on any failure, so the caller can fall back to the HTTP test.
_st_fetch_ookla() {
  local arch dir url
  arch="$(_st_ookla_arch)" || return 1
  has_cmd tar || return 1
  mkdir -p "$ST_LIB_DIR"
  dir="$(mktemp -d "${ST_LIB_DIR}/ookla.XXXXXX" 2>/dev/null)" || return 1
  url="https://install.speedtest.net/app/cli/ookla-speedtest-${ST_OOKLA_VER}-linux-${arch}.tgz"
  if has_cmd curl; then
    curl -fsSL --max-time 60 -o "${dir}/cli.tgz" "$url" 2>>"$ST_LOG_FILE" || {
      rm -rf "$dir"
      return 1
    }
  elif has_cmd wget; then
    wget -q -T 60 -O "${dir}/cli.tgz" "$url" 2>>"$ST_LOG_FILE" || {
      rm -rf "$dir"
      return 1
    }
  else
    rm -rf "$dir"
    return 1
  fi
  if ! tar -xzf "${dir}/cli.tgz" -C "$dir" 2>>"$ST_LOG_FILE" || [[ ! -x "${dir}/speedtest" ]]; then
    rm -rf "$dir"
    return 1
  fi
  printf '%s' "$dir"
}

# _st_fmt_speed BYTES_PER_SEC — "938.5 Mbit/s  (117.3 MB/s)" or "n/a".
_st_fmt_speed() {
  awk -v s="${1:-0}" 'BEGIN {
    if (s + 0 <= 0) { printf "n/a"; exit }
    printf "%.1f Mbit/s  (%.1f MB/s)", s * 8 / 1000000, s / 1048576
  }'
}

# _st_cf_streams N URL OUTDIR PREFIX WRITEOUT [UPLOAD_FILE] — run N parallel
# curl transfers, each writing its %{WRITEOUT} to OUTDIR/PREFIX<i>, and echo
# the summed rate (bytes/s). Parallel streams are what a real speed test uses:
# a single flow rarely saturates a fast path.
_st_cf_streams() {
  local n="$1" url="$2" dir="$3" prefix="$4" field="$5" upload="${6:-}" i
  rm -f "${dir}/${prefix}"* 2>/dev/null # reusable across fallback attempts
  for ((i = 1; i <= n; i++)); do
    if [[ -n $upload ]]; then
      curl -o /dev/null -s -A "$ST_HTTP_UA" --max-time 20 -w "%{${field}}\n" \
        --data-binary @"$upload" "$url" >"${dir}/${prefix}${i}" 2>/dev/null &
    else
      curl -o /dev/null -s -A "$ST_HTTP_UA" --max-time 20 -w "%{${field}}\n" \
        "$url" >"${dir}/${prefix}${i}" 2>/dev/null &
    fi
  done
  wait
  cat "${dir}/${prefix}"* 2>/dev/null | awk '{s += $1} END {printf "%.0f", s + 0}'
}

# --- Result rendering -------------------------------------------------------
# Both back-ends (Ookla and the HTTP fallback) funnel their numbers through one
# renderer, so a test looks identical wherever it came from and matches the rest
# of the UI (ui_kv rows, palette colours, whitespace instead of rules).

# _st_mbit BYTES_PER_SEC — short "938.5 Mbit/s" for the live status line.
_st_mbit() {
  awk -v b="${1:-0}" 'BEGIN { printf "%.1f Mbit/s", b * 8 / 1000000 }'
}

# _st_status TEXT — one in-place status line during a test (carriage return,
# padded wide enough to overwrite a longer previous line).
_st_status() {
  printf '\r    %s%-48s%s' "$C_MUTED" "$1" "$C_RESET"
}

# _st_render_card SERVER ISP PING JITTER DL_BPS UL_BPS LOSS URL — the result
# card. Empty fields are skipped, so it fits Ookla (full) and the HTTP fallback
# (no jitter/loss/url) alike.
_st_render_card() {
  local server="$1" isp="$2" ping="$3" jit="$4" dl="$5" ul="$6" loss="$7" url="$8"
  printf '\n'
  [[ -n $server ]] && ui_kv "Server" "$server"
  [[ -n $isp ]] && ui_kv "ISP" "$isp"
  printf '\n'
  if [[ -n $ping ]]; then
    if [[ -n $jit ]]; then
      ui_kv "Ping" "${ping} ms   (jitter ${jit} ms)"
    else
      ui_kv "Ping" "${ping} ms"
    fi
  fi
  ui_kv "Download" "$(_st_fmt_speed "$dl")"
  ui_kv "Upload" "$(_st_fmt_speed "$ul")"
  [[ -n $loss ]] && ui_kv "Packet loss" "${loss} %"
  if [[ -n $url ]]; then
    printf '\n'
    ui_kv "Result" "$url"
  fi
  printf '\n'
  return 0
}

# --- Minimal JSON readers for the Ookla CLI's one-object-per-line output.
# Flat, first-match, and ALWAYS successful (empty on no match) so a missing
# field can never trip errexit inside the read loop below.
_st_json_str() {
  local m
  m="$(grep -oE "\"$2\":\"[^\"]*\"" <<<"$1" | head -1)" || m=''
  m="${m#*:\"}"
  printf '%s' "${m%\"}"
  return 0
}

_st_json_num() {
  local m
  m="$(grep -oE "\"$2\":[0-9]+(\.[0-9]+)?" <<<"$1" | head -1)" || m=''
  printf '%s' "${m##*:}"
  return 0
}

_st_json_pct() {
  local p pct
  p="$(_st_json_num "$1" progress)"
  [[ $p =~ ^[0-9.]+$ ]] || p=0
  pct="$(awk -v x="$p" 'BEGIN { printf "%d", x * 100 }')"
  printf '%s' "$pct"
  return 0
}

# _st_ookla_card RESULT_JSON — parse one Ookla "type:result" object (bandwidth
# is bytes/s, same unit the card expects) and render it.
_st_ookla_card() {
  local json="$1" ping jit loss isp url server name loc country ping_obj srv_obj
  local -a bws
  ping_obj="${json#*\"ping\":\{}"
  ping_obj="${ping_obj%%\}*}"
  ping="$(_st_json_num "$ping_obj" latency)"
  jit="$(_st_json_num "$ping_obj" jitter)"
  # Exactly two "bandwidth" fields: download first, upload second.
  mapfile -t bws < <(grep -oE '"bandwidth":[0-9]+' <<<"$json" | grep -oE '[0-9]+')
  loss="$(_st_json_num "$json" packetLoss)"
  isp="$(_st_json_str "$json" isp)"
  url="$(grep -oE '"url":"[^"]*"' <<<"$json" | head -1)" || url=''
  url="${url#*:\"}"
  url="${url%\"}"
  srv_obj="${json#*\"server\":\{}"
  srv_obj="${srv_obj%%\}*}"
  name="$(_st_json_str "$srv_obj" name)"
  loc="$(_st_json_str "$srv_obj" location)"
  country="$(_st_json_str "$srv_obj" country)"
  server="$name"
  [[ -n $loc ]] && server="${server:+${server} · }${loc}"
  [[ -n $country ]] && server="${server:+${server}, }${country}"
  _st_render_card "$server" "$isp" "$ping" "$jit" "${bws[0]:-0}" "${bws[1]:-0}" "$loss" "$url"
  return 0
}

# --- Server selection -------------------------------------------------------
# ST_SPEEDTEST_SERVER holds the chosen Ookla server id (empty = automatic).
ST_SPEEDTEST_SERVER=''

# _st_nearby BIN — "id|description" per nearby server, parsed from the stable
# text of `-L`. Empty if none / unsupported.
_st_nearby() {
  "$1" -L --accept-license --accept-gdpr 2>/dev/null | awk '
    /^=+$/ { seen = 1; next }
    seen && $1 ~ /^[0-9]+$/ {
      id = $1; $1 = ""; sub(/^ +/, ""); gsub(/ {2,}/, " ")
      print id "|" $0
    }' || true
}

# _st_pick_nearby BIN — list the closest servers and let the user choose one.
_st_pick_nearby() {
  local nearby line n=0 sel
  local -a list
  printf '  %sFinding nearby servers…%s\n' "$C_MUTED" "$C_RESET"
  nearby="$(_st_nearby "$1")" || nearby=''
  if [[ -z $nearby ]]; then
    printf '  %sCould not list servers — using Automatic.%s\n' "$C_WARN" "$C_RESET"
    ST_SPEEDTEST_SERVER=''
    return 0
  fi
  mapfile -t list <<<"$nearby"
  printf '\n'
  for line in "${list[@]}"; do
    ((n < 12)) || break
    n=$((n + 1))
    printf '    %s%2d%s  %s\n' "$C_KEY" "$n" "$C_RESET" "${line#*|}"
  done
  read -rp "  Server number [1-${n}, Enter = Automatic]: " sel ||
    {
      ST_SPEEDTEST_SERVER=''
      return 0
    }
  if [[ $sel =~ ^[0-9]+$ ]] && ((sel >= 1 && sel <= n)); then
    ST_SPEEDTEST_SERVER="${list[sel - 1]%%|*}"
  else
    ST_SPEEDTEST_SERVER=''
  fi
  return 0
}

# _st_pick_by_id — target any city/country by its speedtest.net server id.
_st_pick_by_id() {
  local id
  printf '  %sEvery server page on speedtest.net shows its numeric ID. Any\n' "$C_MUTED"
  printf '  city or country works — enter one to test that route.%s\n' "$C_RESET"
  read -rp "  Server ID [Enter = Automatic]: " id ||
    {
      ST_SPEEDTEST_SERVER=''
      return 0
    }
  if [[ $id =~ ^[0-9]+$ ]]; then
    ST_SPEEDTEST_SERVER="$id"
  else
    [[ -n $id ]] && printf '  %sNot a numeric ID — using Automatic.%s\n' "$C_WARN" "$C_RESET"
    ST_SPEEDTEST_SERVER=''
  fi
  return 0
}

# _st_choose_server BIN — sets ST_SPEEDTEST_SERVER. Returns 2 if cancelled.
_st_choose_server() {
  local bin="$1" choice
  ST_SPEEDTEST_SERVER=''
  printf '\n  %sTest server%s\n' "$C_ACCENT" "$C_RESET"
  ui_menu_item 1 "Automatic" "nearest server · recommended"
  ui_menu_item 2 "Choose nearby" "pick from the closest servers"
  ui_menu_item 3 "By server ID" "any city worldwide (from speedtest.net)"
  ui_menu_item 0 "Cancel"
  read -rp "$(_ui_prompt)" choice || return 2
  case "${choice:-1}" in
    1 | '') return 0 ;;
    2) _st_pick_nearby "$bin" ;;
    3) _st_pick_by_id ;;
    0) return 2 ;;
    *) return 0 ;;
  esac
}

# _st_run_ookla BIN — run Ookla in jsonl mode, animate a live status line from
# its progress events, and render the result card. Honours ST_SPEEDTEST_SERVER.
_st_run_ookla() {
  local bin="$1" line type result='' lat bw ping_obj
  local -a args=(--format=jsonl --accept-license --accept-gdpr)
  [[ -n $ST_SPEEDTEST_SERVER ]] && args+=(-s "$ST_SPEEDTEST_SERVER")

  printf '\n'
  # Process substitution: a non-zero exit from the client just ends the loop
  # (no pipefail/ERR-trap surprise) and leaves $result empty, handled below.
  while IFS= read -r line; do
    type="$(_st_json_str "$line" type)"
    case "$type" in
      ping)
        lat="$(_st_json_num "$line" latency)"
        _st_status "Latency · ${lat:-…} ms · $(_st_json_pct "$line")%"
        ;;
      download)
        bw="$(_st_json_num "$line" bandwidth)"
        _st_status "Download · $(_st_mbit "${bw:-0}") · $(_st_json_pct "$line")%"
        ;;
      upload)
        bw="$(_st_json_num "$line" bandwidth)"
        _st_status "Upload · $(_st_mbit "${bw:-0}") · $(_st_json_pct "$line")%"
        ;;
      result) result="$line" ;;
    esac
    # The client's own non-zero exit (e.g. a chosen server refused the test) is
    # surfaced by the empty-$result check below; `|| true` keeps that failure
    # from reaching the ERR trap from inside this process substitution.
  done < <("$bin" "${args[@]}" 2>>"$ST_LOG_FILE" || true)
  printf '\r%*s\r' 54 ''

  if [[ -z $result ]]; then
    log_warn "The Ookla speedtest returned no result (server unreachable?)."
    printf '  %sNo result — the chosen server may be unavailable. Try Automatic.%s\n' \
      "$C_WARN" "$C_RESET"
    return 1
  fi
  _st_ookla_card "$result"
  ping_obj="${result#*\"ping\":\{}"
  ping_obj="${ping_obj%%\}*}"
  log_info "Speedtest (Ookla): ping=$(_st_json_num "$ping_obj" latency)ms server=${ST_SPEEDTEST_SERVER:-auto}"
  return 0
}

# tools_speedtest — a real, reliable bandwidth test with a premium, consistent
# result card and a location picker. In order of preference:
#   1. an Ookla binary already on the host (gold standard);
#   2. the official Ookla CLI, fetched, run once and deleted (accurate, picks a
#      nearby server, sidesteps Cloudflare 403s some hosts get);
#   3. a self-contained HTTP test (parallel streams to Cloudflare + mirrors).
# The deprecated speedtest.net Python client is never used — it breaks against
# Ookla's API and is frequently filtered from Iran.
tools_speedtest() {
  ui_section "Bandwidth test"
  printf 'A real download / upload / latency test. It briefly uses bandwidth.\n'

  local bin='' fetched=''
  if has_cmd speedtest && speedtest --version 2>/dev/null | grep -qi 'ookla'; then
    bin='speedtest'
  elif _st_ookla_arch >/dev/null 2>&1 && has_cmd tar && { has_cmd curl || has_cmd wget; }; then
    printf '\nThe most accurate test uses the official %sOokla%s client —\n' "$C_KEY" "$C_RESET"
    printf '%sdownloaded, run once, then deleted (nothing stays installed).%s\n' "$C_MUTED" "$C_RESET"
    if ui_confirm "Download and run it now?"; then
      printf '  %sFetching the Ookla client…%s\n' "$C_MUTED" "$C_RESET"
      fetched="$(_st_fetch_ookla)" || fetched=''
      if [[ -n $fetched ]]; then
        bin="${fetched}/speedtest"
      else
        log_warn "Could not fetch the Ookla client — using the built-in HTTP test instead."
      fi
    fi
  fi

  if [[ -n $bin ]]; then
    local rc=0
    if _st_choose_server "$bin"; then
      _st_run_ookla "$bin" || rc=$?
    else
      rc=2 # cancelled at the server picker
    fi
    [[ -n $fetched ]] && rm -rf "$fetched"
    return "$rc"
  fi

  _st_http_test
}

# _st_http_test — dependency-light fallback when no Ookla client is available:
# parallel HTTP streams to Cloudflare with mirror fallback, into the same card.
_st_http_test() {
  if ! has_cmd curl; then
    log_error "curl is required for the built-in bandwidth test."
    return 1
  fi
  printf '\nBuilt-in %sdownload · upload · latency%s test (Cloudflare + mirrors).\n' "$C_KEY" "$C_RESET"
  ui_confirm "Run it now? (transfers up to ~500 MB)" || return 2

  local base='https://speed.cloudflare.com' streams=4 ul_bytes=26214400
  local dir lat dl=0 ul=0 src dl_host='n/a'

  printf '\n'
  _st_status "Latency…"
  lat="$(for _ in 1 2 3; do
    curl -o /dev/null -s -A "$ST_HTTP_UA" -w '%{time_connect}\n' --max-time 5 "${base}/__down?bytes=0" 2>/dev/null
  done | awk 'NF && $1 + 0 > 0 {if (m == 0 || $1 < m) m = $1} END {if (m > 0) printf "%.1f", m * 1000}')"

  mkdir -p "$ST_LIB_DIR"
  dir="$(mktemp -d "${ST_LIB_DIR}/sptest.XXXXXX" 2>/dev/null)" || dir=''
  if [[ -z $dir ]]; then
    printf '\r%*s\r' 54 ''
    log_error "Could not create a work directory for the test."
    return 1
  fi

  # Cloudflare caps __down at 1e8 bytes and some networks throttle large inbound
  # CDN transfers even when upload is fine, so we try Cloudflare then mirrors and
  # keep the first source that actually moves bytes.
  _st_status "Download…"
  for src in \
    "${base}/__down?bytes=100000000|Cloudflare" \
    'https://speed.hetzner.de/100MB.bin|Hetzner' \
    'http://ipv4.download.thinkbroadband.com/100MB.zip|thinkbroadband'; do
    dl="$(_st_cf_streams "$streams" "${src%%|*}" "$dir" dl speed_download)"
    if ((dl > 0)); then
      dl_host="${src##*|}"
      break
    fi
  done

  _st_status "Upload…"
  head -c "$ul_bytes" /dev/zero >"${dir}/payload" 2>/dev/null
  ul="$(_st_cf_streams "$streams" "${base}/__up" "$dir" ul speed_upload "${dir}/payload")"
  rm -rf "$dir"
  printf '\r%*s\r' 54 ''

  if ((dl == 0 && ul == 0)); then
    log_error "Could not reach the Cloudflare speed servers — network blocked? See the log."
    return 1
  fi
  _st_render_card "HTTP test · ${dl_host} · ${streams} streams" "" "${lat}" "" "$dl" "$ul" "" ""
  log_info "Bandwidth test (HTTP): down=${dl}B/s (${dl_host}) up=${ul}B/s ping=${lat:-?}ms."
  return 0
}

# tools_benchmark — quick, dependency-light CPU and disk figures. Comparable
# between servers, not absolute hardware ratings. The disk test averages three
# runs (like bench.sh) so one cached run cannot flatter the result, and AES-NI
# is reported because it decides TLS/Reality throughput on a proxy node.
tools_benchmark() {
  ui_section "Quick benchmark"

  ui_kv "CPU" "$(cpu_model)"
  local aes='no'
  grep -qm1 -w aes /proc/cpuinfo 2>/dev/null && aes='yes'
  ui_kv "Cores · AES-NI" "$(cpu_cores) · ${aes}"

  if has_cmd sha256sum; then
    local start end
    start="$(date +%s%N)"
    dd if=/dev/zero bs=1M count=256 status=none 2>/dev/null | sha256sum >/dev/null
    end="$(date +%s%N)"
    ui_kv "SHA256 (256 MB)" "$(awk -v n=$((end - start)) 'BEGIN {printf "%.2f s", n / 1000000000}')"
  fi

  local target='/var/tmp' avail_mb
  avail_mb="$(df -Pm "$target" 2>/dev/null | awk 'NR == 2 {print $4}')" || avail_mb=0
  [[ $avail_mb =~ ^[0-9]+$ ]] || avail_mb=0
  if ((avail_mb > 2048)); then
    printf '  %s%-19s%s measuring…' "$C_KEY" "Disk write (3×1 GB)" "$C_RESET"
    local run out mbps sum=0 cnt=0
    for run in 1 2 3; do
      out="$(LC_ALL=C dd if=/dev/zero of="${target}/.st-bench" bs=1M count=1024 conv=fdatasync 2>&1)" || out=''
      # dd's summary line ends in "… , N MB/s" (or GB/s / kB/s) — normalise to MB/s.
      mbps="$(awk '/copied|bytes/ {u = $NF; v = $(NF - 1) + 0
        if (u == "GB/s") v *= 1024; else if (u == "kB/s") v /= 1024
        printf "%.0f", v; exit}' <<<"$out")"
      [[ $mbps =~ ^[0-9]+$ ]] && {
        sum=$((sum + mbps))
        cnt=$((cnt + 1))
      }
    done
    rm -f "${target}/.st-bench"
    if ((cnt > 0)); then
      printf '\r  %s%-19s%s %d MB/s (avg of %d)        \n' "$C_KEY" "Disk write (3×1 GB)" "$C_RESET" $((sum / cnt)) "$cnt"
    else
      printf '\r  %s%-19s%s unavailable        \n' "$C_KEY" "Disk write (3×1 GB)" "$C_RESET"
    fi
  else
    ui_kv "Disk write" "skipped (needs 2 GB free in ${target})"
  fi

  ui_kv "Load · RAM" "$(load_avg) · $(mem_total_mb) MB"
  return 0
}

# tools_watch — live view of what matters under load. A foreground viewer,
# not a service: it exits when you leave and leaves nothing behind.
tools_watch() {
  if [[ ! -t 0 ]]; then
    printf 'The live view needs an interactive terminal.\n'
    return 2
  fi
  local iface rx_prev tx_prev rx tx ct max sockets key
  iface="$(net_default_iface)" || iface=''
  if [[ -z $iface || ! -r /sys/class/net/${iface}/statistics/rx_bytes ]]; then
    printf 'Cannot read interface counters for the live view.\n'
    return 2
  fi
  rx_prev="$(cat "/sys/class/net/${iface}/statistics/rx_bytes")"
  tx_prev="$(cat "/sys/class/net/${iface}/statistics/tx_bytes")"

  while true; do
    sleep 2
    rx="$(cat "/sys/class/net/${iface}/statistics/rx_bytes")"
    tx="$(cat "/sys/class/net/${iface}/statistics/tx_bytes")"
    ct="$(sysctl_get net.netfilter.nf_conntrack_count)"
    max="$(sysctl_get net.netfilter.nf_conntrack_max)"
    sockets="$(awk '/^TCP:/ {print $3; exit}' /proc/net/sockstat 2>/dev/null)" || sockets='?'

    clear 2>/dev/null || true # cosmetic only
    ui_title "Live view — ${iface} (press q to quit)"
    ui_kv "Traffic" "$(awk -v r=$((rx - rx_prev)) -v t=$((tx - tx_prev)) \
      'BEGIN {printf "down %.2f Mbit/s · up %.2f Mbit/s", r * 8 / 2000000, t * 8 / 2000000}')"
    ui_kv "TCP sockets" "$sockets"
    if [[ $ct =~ ^[0-9]+$ && $max =~ ^[0-9]+$ && $max -gt 0 ]]; then
      ui_kv "Conntrack" "${ct} / ${max} ($((ct * 100 / max))%)"
    else
      ui_kv "Conntrack" "module not loaded"
    fi
    ui_kv "Load" "$(load_avg)"
    ui_kv "RAM available" "$(awk '/^MemAvailable:/ {printf "%d MB", $2 / 1024; exit}' /proc/meminfo)"
    rx_prev="$rx"
    tx_prev="$tx"

    # Non-blocking key check: the sleep above paces the loop.
    if read -rsn1 -t 0.01 key && [[ ${key,,} == q ]]; then
      printf '\n'
      return 0
    fi
  done
}

# tools_report — plain-text support bundle (also behind --report). Printed
# to stdout AND saved, so users can paste it into an issue/ticket directly.
tools_report() {
  local out="${ST_LIB_DIR}/report-${ST_RUN_ID}.txt"
  {
    printf '=== %s support report v%s — %s ===\n\n' "$ST_NAME" "$ST_VERSION" "$(date '+%F %T')"
    printf -- '--- System\n'
    printf 'OS: %s\nKernel: %s\nVirt: %s\nUptime: %s\n' \
      "$(os_pretty_name)" "$(kernel_release)" "$(detect_virt)" "$(uptime_pretty)"
    printf 'CPU: %s (%s cores)\nRAM: %s MB\nLoad: %s\n\n' \
      "$(cpu_model)" "$(cpu_cores)" "$(mem_total_mb)" "$(load_avg)"
    printf -- '--- Workload\n'
    printf 'Detected: %s\n' "$(detect_summary)"
    printf 'Saved profile/tier: %s / %s\n\n' \
      "$(config_get last_profile none)" "$(config_get last_tier -)"
    printf -- '--- DNS\n'
    printf 'Resolver stack: %s\n' "$(dns_stack)"
    printf 'Servers in effect: %s\n' "$(dns_effective_servers)"
    printf 'DNS over TLS: %s\n\n' "$(dns_over_tls_state)"
    printf -- '--- Kernel tuning (live)\n'
    local key
    for key in net.ipv4.tcp_congestion_control net.core.default_qdisc \
      net.ipv4.tcp_mtu_probing net.ipv4.ip_forward net.ipv6.conf.all.forwarding \
      net.core.somaxconn net.core.rmem_max net.netfilter.nf_conntrack_max \
      net.netfilter.nf_conntrack_count fs.file-max vm.swappiness; do
      printf '%s = %s\n' "$key" "$(sysctl_get "$key")"
    done
    printf 'nofile soft/hard: %s / %s\n\n' \
      "$(ulimit -Sn 2>/dev/null || printf '?')" "$(ulimit -Hn 2>/dev/null || printf '?')"
    printf -- '--- Swap\n'
    if [[ -r /proc/swaps ]]; then cat /proc/swaps; else printf 'unavailable\n'; fi
    printf '\n'
    printf -- '--- Manifest (last 15 changes)\n'
    if [[ -f $ST_MANIFEST_FILE ]]; then
      awk 'NR > 1' "$ST_MANIFEST_FILE" | tail -n 15
    else
      printf 'no manifest yet\n'
    fi
    printf '\n'
    printf -- '--- Log (last 30 lines)\n'
    if [[ -f $ST_LOG_FILE ]]; then tail -n 30 "$ST_LOG_FILE"; else printf 'no log yet\n'; fi
    printf '\n=== end of report ===\n'
  } | tee "$out"
  printf '\n%sSaved:%s %s\n' "$C_OK" "$C_RESET" "$out"
  log_info "Support report written to ${out}."
}

